var model = function() {
  // initial hidden state
  var s0 = true;
  // emission at time 0, conditioned to be false
  var o0 = flip(0.9);        // P(obs=true | s0=true)=0.9
  condition(o0 === false);

  // transition to time 1
  var s1 = s0 ? flip(0.7) : flip(0.3);
  // emission at time 1, conditioned to be false
  var o1 = s1 ? flip(0.9) : flip(0.1);
  condition(o1 === false);

  // transition to time 2
  var s2 = s1 ? flip(0.7) : flip(0.3);
  // emission at time 2, conditioned to be false
  var o2 = s2 ? flip(0.9) : flip(0.1);
  condition(o2 === false);

  // return the three-step hidden state sequence (including the fixed initial state)
  return [s0, s1, s2];
};

var ANSWER = Infer({method: 'enumerate'}, model);

