var model = function() {
  // Non-terminal expansions
  var start = function() {
    var rule = categorical([0.4, 0.6]);
    if (rule === 0) {
      return [np(), 'V', np()];
    } else {
      return [np(), 'V'];
    }
  };

  var np = function() {
    var rule = categorical([0.4, 0.6]);
    if (rule === 0) {
      return ['A', np()];
    } else {
      return ['N'];
    }
  };

  // Pre-terminal vocabulary
  var n = function() {
    var word = categorical([0.6, 0.4]);
    if (word === 0) {
      return 'John';
    } else {
      return 'soup';
    }
  };

  var v = function() {
    var word = categorical([0.3, 0.3, 0.4]);
    if (word === 0) {
      return 'loves';
    } else if (word === 1) {
      return 'hates';
    } else {
      return 'runs';
    }
  };

  var a = function() {
    var word = categorical([0.6, 0.4]);
    if (word === 0) {
      return 'tall';
    } else {
      return 'salty';
    }
  };

  // Generate sentence
  var sentence = start();
  var words = [];

  function expand(sentence) {
    for (var i = 0; i < sentence.length; i++) {
      if (sentence[i] === 'NP') {
        var newSentence = [];
        for (var j = 0; j < sentence.length; j++) {
          if (sentence[j] === 'NP') {
            newSentence = newSentence.concat(np());
          } else {
            newSentence.push(sentence[j]);
          }
        }
        sentence = newSentence;
      } else if (sentence[i] === 'N') {
        sentence[i] = n();
      } else if (sentence[i] === 'V') {
        sentence[i] = v();
      } else if (sentence[i] === 'A') {
        sentence[i] = a();
      }
    }
    return sentence;
  }

  while (sentence.some(function(x) { return x === 'NP' || x === 'N' || x === 'V' || x === 'A'; })) {
    sentence = expand(sentence);
  }

  // Condition on starting with 'tall' and 'John'
  if (sentence[0] !== 'tall' || sentence[1] !== 'John') {
    factor(0);
  }

  // Return third word or empty string
  if (sentence.length > 2) {
    return sentence[2];
  } else {
    return '';
  }
};

