function generate() {
  var words = [];

  function expand(symbol) {
    if (vocabulary[symbol]) {
      words.push(vocabulary[symbol][uniformDraw(categorical(vocabulary[symbol]))]);
      return;
    }

    var ruleIndex;
    if (symbol === "start") {
      if (uniformDraw(Bernoulli(0.4))) {
        expand("NP"); expand("V"); expand("NP");
      } else {
        expand("NP"); expand("V");
      }
    } else if (symbol === "NP") {
      if (uniformDraw(Bernoulli(0.4))) {
        expand("A"); expand("NP");
      } else {
        expand("N");
      }
    } else if (symbol === "V") {
      expand("V");
    } else if (symbol === "A") {
      expand("A");
    } else if (symbol === "N") {
