    }
  }

  expand("start");
  return words.length >= 3 ? words[2] : "";
} // won't reach here due to prune

function forwardStep() {
  function generateTree(symbol) {
    if (symbol in vocabulary) {
      return vocabulary[symbol][uniformDraw(categorical(vocabulary[symbol]))];
    }

    var result;
    if (symbol === "start") {
      var V = uniformDraw(Bernoulli(0.4));
      if (V) {
        result = generateTree("NP") + " " + generateTree("V") + " " + generateTree("NP");
      } else {
        result = generateTree("NP") + " " + generateTree("V");
      }
    } else if (symbol === "NP") {
      var N = uniformDraw(Bernoulli(0.4));
      if (N) {
        result = generateTree("A") + " " + generateTree("NP");
      } else {
        result = generateTree("N");
      }
    } else if (symbol === "A") {
      if (uniformDraw(Bernoulli(0.6))) result = vocabulary["A"][0];
      else result = vocabulary["A"][1];
    } else if (symbol === "N") {
      if (uniformDraw(Bernoulli(0.6))) result = vocabulary["N"][0];
      else result = vocabulary["N"][1];
    } else if (symbol === "V") {
      if (uniformDraw(Bernoulli(0.3))) result = vocabulary["V"][0];
      else if (uniformDraw(Bernoulli(0.67))) result = vocabulary["V"][1];
      else result = vocabulary["V"][2];
    } else {
      return "empty";
    }
    return result;
  }

  function wordSequence() {
    function rec(symbol, depth) {
      if (depth > 15) return "many";
      if (symbol in vocabulary) {
        return {[symbol]: [
          vocabulary[symbol].map(w => w),
          "many"
        ]};
      }
      var parts = [];
      if (symbol === "start") {
        var V = uniformDraw(Bernoulli(0.4));
        parts.push(V ? [rec("NP", depth+1), rec("V", depth+1), rec("NP", depth+1)] : [rec("NP", depth+1), rec("V", depth+1)]);
      } else if (symbol === "NP") {
        var N = uniformDraw(Bernoulli(0.4));
        parts.push(N ? [rec("A", depth+1), rec("NP", depth+1)] : [rec("N", depth+1)]);
      } else if (symbol === "A") {
        parts.push(vocabulary["A"]);
      } else if (symbol === "N") {
        parts.push(vocabulary["N"]);
      } else if (symbol === "V") {
        parts.push(vocabulary["V"]);
      }
      return parts;
    }
    return rec("start", 0);
  };

  var seq = wordSequence();
  var w1 = seq[0][0] || seq[0][1];
  if (w1 !== "tall") return "skip-1";
  if (typeof seq[0] === 'string') return seq[1] || "";
  var w2All = typeof seq[1] === 'string' ? [seq[1]] : (seq[1] || seq[1][0]);
  if (w2All.length === 0) return "skip-2";
  var w2 = w2All[0];
  if (w2 !== "John") return "skip-2";
  return seq[2] || "";
}

