// Score for a given utterance, world, QUD and theta
var scoreGiven = function(utter, price, val, qud, theta){
  var cond = (utter === "expensive") ? (price >= theta) : (price <= theta);
  if (!cond) return 0;
  var N = countCond(utter, theta);
  if (qud === "price") {
    return 1 / N;
  } else if (qud === "valence") {
    return valProb(price, val) / N;
  } else { // "both"
    return valProb(price, val) / N;
  }
};

// Probability that a pragmatic speaker would utter "expensive"
var probSpeakerExpensive = function(price, val, theta){
  var quds = ["price", "valence", "both"];
  var total = 0;
  for (var i = 0; i < quds.length; i++) {
    var qud = quds[i];
    var sExp = scoreGiven("expensive", price, val, qud, theta);
    var sNot = scoreGiven("notExpensive", price, val, qud, theta);
    var expExp = Math.exp(sExp);                // cost(expensive)=0
    var expNot = Math.exp(sNot - 1);            // cost(notExpensive)=1
    var pExp = expExp / (expExp + expNot);
    total += pExp;
  }
  return total / quds.length; // average over QUD
};

