var secondLevelSpeaker = function(trueState) {
  return Infer({method: "enumerate"}, function() {
    var utterance = uniformDraw(["shirleyTemple", "shirleyTemple person", "shirleyTemple drink"]);

    var cost = utterance === "shirleyTemple" ? 1 : 2;

    // Get pragmatic listener's posterior
    var pragmaticListenerDist = pragmaticListener(utterance);

    // Compute P(true state | utterance) by marginalizing over interpretation
    var trueStateProb = 0;
    pragmaticListenerDist.support().forEach(function(support) {
      if (support.state === trueState) {
        trueStateProb += Math.exp(pragmaticListenerDist.score([], support));
      }
    });

    // Factor by log probability of true state minus cost
    if (trueStateProb > 0) {
      factor(Math.log(trueStateProb) - cost);
    } else {
      factor(-1000 - cost);
    }

    return utterance;
  });
};

