// WebPPL program to compute the posterior over intelligence state
// given the utterance "dumb as rocks" in a multi-goal RSA model.

var utterances = ["", "dumb as rocks", "dumb", "f*cking idiot"];

var semantics = {
  "" : [0.25, 0.25, 0.25, 0.25],
  "dumb as rocks" : [0.45, 0.85, 0.20, 0.02],
  "dumb" : [0.85, 0.95, 0.02, 0.02],
  "f*cking idiot" : [0.95, 0.55, 0.02, 0.02]
};

var valenceProb = [0.01, 0.33, 0.66, 0.99]; // P(good | state)
var lowProb =    [0.10, 0.70, 0.70, 0.10]; // P(low | state)

var goals = ["goalState", "goalValence", "goalArousal"];

var alpha = 10;
var lambda = -1.25;

// Helper to sample a state (1-4)
function sampleState() {
  return (randomInteger(4) + 1);
}

// Helper to sample valence (1=good, 0=bad)
function sampleValence(stateIndex) {
  var p = valenceProb[stateIndex];
  return Bernoulli(p);
}

// Helper to sample arousal (1=low, 0=high)
function sampleArousal(stateIndex) {
  var p = lowProb[stateIndex];
  return Bernoulli(p);
}

// Helper to sample goal
function sampleGoal() {
  return sample(Categorical({goalState: 1/3, goalValence: 1/3, goalArousal: 1/3}));
}

// Helper to sample phi
function samplePhi() {
  return (randomInteger(18)+1) * 0.05; // {0.05,0.10,...,0.90}
}

// Compute posterior state probabilities given utterance (numerical form)
function posteriorS(utterance) {
  var unnorm = semantics[utterance];
  var sum = unnorm.reduce(function(a,b){return a+b;},0);
  return unnorm.map(function(x){return x/sum;}); // length 4
}

// Compute probability of a specific valence outcome given utterance
function valenceProbGivenUtter(vTrue, postS) { // vTrue = 1 for good, 0 for bad
  var prob = 0;
  for(var s=0;s<4;s++){
    var vp = valenceProb[s];
    var pV = (vTrue===1)? vp : (1-vp);
    prob += pV * postS[s];
  }
  return prob;
}

// Compute probability of a specific arousal outcome given utterance
function arousalProbGivenUtter(aTrue, postS) { // aTrue = 1 for low, 0 for high
  var prob = 0;
  for(var s=0;s<4;s++){
    var lp = lowProb[s];
    var pA = (aTrue===1)? lp : (1-lp);
    prob += pA * postS[s];
  }
  return prob;
}

// Speaker produces a distribution over utterances
function speakerDist(state, valence, arousal, goal, phi) {
  var dist = {}; // map utterance -> prob
  var weights = {};

  // Precompute state posterior probs for each utterance
  var postSFor = {};
  for(var i=0;i<utterances.length;i++){
    postSFor[utterances[i]] = posteriorS(utterances[i]); // length 4
  }

  // Expected state value for each utterance
  var expectedStateValue = {};
  for(var i=0;i<utterances.length;i++){
    var u = utterances[i];
    var postS = postSFor[u];
    var exp = 0;
    for(var s=0;s<4;s++){
      exp += (s+1)*postS[s];
    }
    expectedStateValue[u] = exp;
  }

  // Compute weights
  for(var i=0;i<utterances.length;i++){
    var u = utterances[i];
    var postS = postSFor[u];

    // Epistemic component
    var ep;
    if(goal === "goalState"){
      ep = Math.log(postS[state-1]); // state-1 index
    } else if(goal === "goalValence"){
      ep = Math.log(valenceProbGivenUtter(valence, postS));
    } else { // goalArousal
      ep = Math.log(arousalProbGivenUtter(arousal, postS));
    }

    // Antisocial component
    var anti = lambda * expectedStateValue[u];

    var util = phi * ep + (1-phi) * anti;
    weights[u] = Math.exp(alpha * util);
  }

  // Normalize
  var sumW = 0;
  for(var u in weights){ sumW += weights[u]; }
  for(var u in weights){
    dist[u] = weights[u] / sumW;
  }
  return dist;
}

// Pragmatic listener model
function listener() {
  var state = sampleState(); // 1-4
  var valence = sampleValence(state-1); // 1 or 0
  var arousal = sampleArousal(state-1); // 1 or 0
  var goal = sampleGoal();
  var phi = samplePhi();

  var dist = speakerDist(state, valence, arousal, goal, phi);
  var utter = sample(Categorical(dist));
  condition(utter === "dumb as rocks");
  return state; // we care about the state
}

