function speakerSelection(state, phi) {
  var alpha = 10;
  var lambda = -1.25;

  var bestU = "";
  var bestLogU = -Infinity;

  for (var i = 0; i < utts.length; i++) {
    var U = utts[i];

    var Ps = literalS[U].slice();

    var sum = Ps.reduce((a, b) => a + b, 0);
    for (var j = 0; j < Ps.length; j++) {
      Ps[j] /= sum;
    }

    var avgState = 0;
    for (var j = 0; j < Ps.length; j++) {
      avgState += Ps[j] * (j + 1);
    }

    var mls = Ps.indexOf(Math.max.apply(null, Ps)) + 1;

    var goal = goalsPrior.goals[Math.floor(Math.random() * 3)];
    var good = Math.random() < 0.5 ? "good" : "bad";
    var low = Math.random() < 0.5 ? "low" : "high";

    var epi = 0;
    if (goal === "state") {
      epi = Ps[state - 1];
    } else if (goal === "valence") {
      var infGood = Ps[2];
      epi = good === "good" ? infGood : (1 - infGood);
    } else {
      var infLow = Ps[1];
      epi = low === "low" ? infLow : (1 - infLow);
    }

    var anti = lambda * avgState;
    var total = alpha * epi + (1 - alpha) * anti;
    var expTotal = Math.exp(phi * total);

    if (expTotal > bestLogU) {
      bestLogU = expTotal;
      bestU = U;
    }
  }

  return bestU;
}

