function truth(u, world, scope){
  var blond = world.filter(function(p){return p.blond;});
  var anyBlond = blond.length > 0;

  var allNice = true, anyNice = false;
  var allNotNice = true, anyNotNice = false;
  for (var i = 0; i < blond.length; i++) {
    var nice = blond[i].nice;
    if (!nice) allNice = false;
    if (nice) anyNice = true;
    if (nice) allNotNice = false;
    if (!nice) anyNotNice = true;
  }

  if (u === "all of the blond people are nice") {
    return anyBlond ? allNice : true;
  }
  if (u === "none of the blond people are nice") {
    return anyBlond ? !anyNice : true;
  }
  if (u === "null") {
    return true;
  }
  if (u === "none of the blond people are not nice") {
    return anyBlond ? allNice : true;
  }
  if (u === "all of the blond people are not nice") {
    if (scope === "surface") {
      return anyBlond ? allNotNice : true;
    } else { // inverse scope
      return anyBlond ? anyNotNice : false;
    }
  }
  return false;
}

function literalListenerProb(u, scope, w){
  var dist = Infer({method:'enumerate'}, function(){
    var world = sampleWorld();
    condition(truth(u, world, scope));
    return world;
