var literalMeaning = function(utt, world, scope) {
  var blonds = world.filter(function(person) { return person.blond; });
  var allNice = blonds.every(function(person) { return person.nice; });
  var noneNice = blonds.every(function(person) { return !person.nice; });
  var someNotNice = blonds.some(function(person) { return !person.nice; });
  var allNotNice = blonds.every(function(person) { return !person.nice; });

  return utt === "all of the blond people are nice" ? allNice :
         utt === "none of the blond people are nice" ? noneNice :
         utt === "null" ? true :
         utt === "all of the blond people are not nice" ?
           (scope === 'surface' ? allNotNice : someNotNice) :
         utt === "none of the blond people are not nice" ? allNice :
         false;
};

var literalListener = cache(function(utt, scope) {
  return Infer({method: 'enumerate'}, function() {
    var world = worldPrior();
    condition(literalMeaning(utt, world, scope));
    return world;
  });
});

var speaker = cache(function(world, scope) {
  return Infer({method: 'enumerate'}, function() {
    var utt = uniformDraw(utterances);
    var L0 = literalListener(utt, scope);
