  } else if (utterance === "none of the blond people are nice") {
    return _.every(blondNice, function(n) { return !n; });
  } else if (utterance === "null") {
    return true;
  } else if (utterance === "all of the blond people are not nice") {
    if (scope === "surface") {
      return _.every(blondNice, function(n) { return !n; });
    } else {
      return _.some(blondNice, function(n) { return !n; });
    }
  } else if (utterance === "none of the blond people are not nice") {
    return _.every(blondNice, function(n) { return n; });
  }
}

