// Discretization grids
var skillVals = _.range(-3, 3+1e-9, 0.2);      // 31 points, inclusive
var threshVals = _.range(-3, 3, 0.2);           // 30 points, exclude 3

// Gaussian density (unnormalized)
var gauss = function(mean, sd, x){
  var z = (x-mean)/sd;
  return Math.exp(-0.5*z*z)/(sd*Math.sqrt(2*Math.PI));
};

// Belief distributions (means -1,0,1, sd=1) discretized and normalized
var beliefMeans = [-1,0,1];
var beliefProbsMap = {};
beliefMeans.forEach(function(m){
  var ps = skillVals.map(function(x){return gauss(m,1,x);});
  var sum = _.sum(ps);
  beliefProbsMap[m] = ps.map(function(p){return p/sum;});
});
// True‑skill distribution (mean 0, sd 1)
var trueSkillProbs = beliefProbsMap[0];

// Utterances and their costs
var utterances = ["good","actuallyGood","silence"];
var costs = {good:10, actuallyGood:20, silence:0};
var priorU = {};
utterances.forEach(function(u){ priorU[u]=Math.exp(-costs[u]); });

// Speaker optimality parameters
var opt1 = 10;
var opt2 = 2;

// Truth condition
var cond = function(u,s,t){
  if(u==="silence") return true;
  return s>t;
};

// -------------------- Literal Listener --------------------
var literalProb = function(sIdx, u, tIdx, mean){
  var s = skillVals[sIdx];
  var t = threshVals[tIdx];
  if (!cond(u,s,t)) return 0;
  var probs = beliefProbsMap[mean];
  // mass of allowed skills under this belief and threshold
  var mass = 0;
  for (var i=0;i<skillVals.length;i++){
    if (cond(u,skillVals[i],t)) mass += probs[i];
  }
  return probs[sIdx]/mass; // normalized probability of this s
};

// -------------------- First Speaker --------------------
var firstSpeaker = {}; // firstSpeaker[mean][sIdx][tIdx][u] = prob
beliefMeans.forEach(function(mean){
  firstSpeaker[mean] = [];
  for (var si=0; si<skillVals.length; si++){
    firstSpeaker[mean][si] = [];
    for (var ti=0; ti<threshVals.length; ti++){
      // compute unnormalized weights for each utterance
      var weights = {};
      var sumW = 0;
      utterances.forEach(function(u){
        var lp = literalProb(si,u,ti,mean);
        var w = priorU[u]*Math.pow(lp,opt1);
        weights[u]=w;
        sumW+=w;
      });
      // normalize
      var probs = {};
      utterances.forEach(function(u){
        probs[u]= (sumW===0)?0:weights[u]/sumW;
      });
      firstSpeaker[mean][si][ti]=probs;
    }
  }
});

// -------------------- First Listener --------------------
// firstListenerProb[mean][u][sIdx] = probability that first listener
// assigns to skill sIdx after hearing u given belief mean
var firstListenerProb = {};
beliefMeans.forEach(function(mean){
  firstListenerProb[mean]={};
  utterances.forEach(function(u){
    // unnormalized weight for each skill
    var w = new Array(skillVals.length).fill(0);
    for (var si=0; si<skillVals.length; si++){
      var beliefP = beliefProbsMap[mean][si];
      var sumOverT = 0;
      for (var ti=0; ti<threshVals.length; ti++){
        sumOverT += firstSpeaker[mean][si][ti][u];
      }
      w[si] = beliefP * sumOverT; // prior * likelihood of utterance
    }
    var total = _.sum(w);
    var probs = w.map(function(v){ return total===0?0:v/total; });
    firstListenerProb[mean][u]=probs;
  });
});

// -------------------- Second Speaker --------------------
var secondSpeakerProb = {}; // secondSpeakerProb[mean][sIdx][u]
beliefMeans.forEach(function(mean){
  secondSpeakerProb[mean]={};
  for (var si=0; si<skillVals.length; si++){
    // compute unnormalized weight for each utterance
    var weights = {};
    var sumW = 0;
    utterances.forEach(function(u){
      var fl = firstListenerProb[mean][u][si];
      var w = priorU[u]*Math.pow(fl,opt2);
      weights[u]=w;
      sumW+=w;
    });
    // normalize
    var probs = {};
    utterances.forEach(function(u){
      probs[u]=(sumW===0)?0:weights[u]/sumW;
    });
    secondSpeakerProb[mean][si]=probs;
  }
});

// -------------------- Second Listener (the required posterior) --------------------
var secondListenerPosterior = function(obsU){
  return Infer({method:'enumerate'}, function(){
    // hypothesis (mean) uniform
    var hypIdx = sample(Categorical({ps:[1/3,1/3,1/3]}));
    var mean = beliefMeans[hypIdx];
    // true skill from the fixed mean‑0 distribution
    var skillIdx = sample(Categorical({ps:trueSkillProbs}));
    var prob = secondSpeakerProb[mean][skillIdx][obsU];
    factor(Math.log(prob)); // weight by speaker's production probability
    return mean;
  });
};

