// Discretised Gaussian distribution over the grid [-3,3] step 0.2
function discretisedGaussian(mu, sigma) {
  var vs = [], ps = [];
  var total = 0;
  for (var i = 0; i < 31; i++) {
    var x = -3 + 0.2 * i;
    vs.push(x);
    var dens = Math.exp(-((x - mu) * (x - mu)) / (2 * sigma * sigma)) /
               (sigma * Math.sqrt(2 * Math.PI));
    ps.push(dens);
    total += dens;
  }
  for (var i = 0; i < ps.length; i++) ps[i] /= total;
  var dist = categorical({ vs: vs, ps: ps });
  // helper to query probability
  dist.prob = function (v) {
    var idx = vs.indexOf(v);
    return idx >= 0 ? ps[idx] : 0;
  };
  return dist;
}

// Grids
var skillGrid = [];
for (var i = 0; i < 31; i++) skillGrid.push(-3 + 0.2 * i);
var thresholdGrid = [];
for (var i = 0; i < 30; i++) thresholdGrid.push(-3 + 0.2 * i);

// True skill distribution: mean 0, sd 1
var trueSkillDist = discretisedGaussian(0, 1);

// Costs
function cost(u) {
  if (u === 'good') return 10;
  if (u === 'actuallyGood') return 20;
  return 0; // silence
}

// Log probability of a skill under the literal listener
function literalProb(skill, utter, theta, beliefDist) {
  var cond;
  if (utter === 'good' || utter === 'actuallyGood') {
    cond = skill > theta;
  } else {
    cond = true;
  }
  if (!cond) return 0;

  var norm = 0;
  for (var i = 0; i < beliefDist.vs.length; i++) {
    var s = beliefDist.vs[i];
    var ok = (utter === 'good' || utter === 'actuallyGood') ? s > theta : true;
    if (ok) norm += beliefDist.prob(s);
  }
  return beliefDist.prob(skill) / norm;
}

// First speaker probability of producing an utterance
function probFirstSpeaker(utter, trueSkill, theta, beliefMean) {
  var prior = Math.exp(-cost(utter));
  var belief = discretisedGaussian(beliefMean, 1);
  var lit = literalProb(trueSkill, utter, theta, belief);
  return prior * Math.pow(lit, 10); // speaker-optimality 10
}

// First listener probability of a skill given utterance and belief mean
function firstListenerProbSkill(trueSkill, utter, beliefMean) {
  var belief = discretisedGaussian(beliefMean, 1);
  var unnorm = {}, total = 0;

  for (var tIdx = 0; tIdx < thresholdGrid.length; tIdx++) {
    var theta = thresholdGrid[tIdx];
    var wTheta = 1 / thresholdGrid.length;
    for (var i = 0; i < belief.vs.length; i++) {
      var sk = belief.vs[i];
      var wSpeaker = probFirstSpeaker(utter, sk, theta, beliefMean);
      var w = wTheta * belief.prob(sk) * wSpeaker;
      unnorm[sk] = (unnorm[sk] || 0) + w;
      total += w;
    }
  }
  if (total === 0) return 0;
  return unnorm[trueSkill] / total;
}

// Second speaker probability of producing an utterance
function probSecondSpeaker(utter, trueSkill, beliefMean) {
  var prior = Math.exp(-cost(utter));
  var flProb = firstListenerProbSkill(trueSkill, utter, beliefMean);
  return prior * Math.pow(flProb, 2); // speaker-optimality 2
}

// Build posterior over hypothesis means given an utterance
function buildPosterior(utt) {
  return Infer({ method: 'enumerate' }, function () {
    var hyps = [-1, 0, 1];
    var hyp = categorical({ vs: hyps, ps: [1 / 3, 1 / 3, 1 / 3] });
    var trueSkill = sample(trueSkillDist);
    var pUtter = probSecondSpeaker(utt, trueSkill, hyp);
    factor(Math.log(pUtter));
    return hyp;
  });
}

