var gaussianDensity = function(x, mean, sd) {
  return Math.exp(-0.5 * Math.pow((x - mean) / sd, 2)) / (sd * Math.sqrt(2 * Math.PI));
};

var skillPrior = function(mean, sd) {
  var ps = map(function(x) { return gaussianDensity(x, mean, sd); }, gridSkill);
  return Categorical({ps: ps, vs: gridSkill});
};

// Utterance prior
