// Define the grid of points for discretization
var grid = _.range(-15, 16).map(function(x) { return x / 5; });

// Define the Gaussian distribution with given mean and standard deviation
function gaussianMeanVariance(mean, variance) {
  return function(x) {
    return Math.exp(-0.5 * Math.pow(x - mean, 2) / variance) / Math.sqrt(2 * Math.PI * variance);
  };
}

// Discretize a continuous distribution onto a grid
function discretize(dist, grid) {
  return function(x) {
    return dist(x) / grid.map(dist).reduce(function(a, b) { return a + b; });
  };
}

// Get the prior probability of an utterance
function priorUtterance(utterance) {
  var costs = { 'good': 10, 'actually good': 20, 'silence': 0 };
  return Math.exp(-costs[utterance]);
}

// Define the truth conditions for utterances
function truthCondition(skillLevel, threshold, utterance) {
  if (utterance === 'good' || utterance === 'actually good') {
    return skillLevel > threshold;
  } else {
    return true;
  }
}

// Define the literal listener's belief
function literalListener(utterance, threshold, belief, skillLevel) {
  return truthCondition(skillLevel, threshold, utterance) ? belief(skillLevel) : 0;
}

// Define the first speaker's utterance choice
function firstSpeaker(trueSkillLevel, threshold, belief, utterance) {
  var opt = 10;
  return priorUtterance(utterance) * Math.exp(opt * Math.log(literalListener(utterance, threshold, belief, trueSkillLevel)));
}

// Define the first listener's belief
function firstListener(utterance, belief, skillLevel) {
  var thresholds = _.range(-15, 15).map(function(x) { return x / 5; });
  return thresholds.reduce(function(a, b) {
    return a + firstSpeaker(skillLevel, b, belief, utterance);
  }, 0);
}

// Define the second speaker's utterance choice
function secondSpeaker(trueSkillLevel, belief, utterance) {
  var opt = 2;
  return priorUtterance(utterance) * Math.exp(opt * Math.log(firstListener(utterance, belief, trueSkillLevel)));
}

// Define the second listener's posterior distribution
function secondListener(utterance) {
  var hypotheses = [{ mean: -1, variance: 1 }, { mean: 0, variance: 1 }, { mean: 1, variance: 1 }];
  var trueSkillLevels = grid;
  return Infer({
    method: 'enumerate',
    model: function() {
      var hypothesis = uniformDraw(hypotheses);
      var trueSkillLevel = categorical(trueSkillLevels.map(function(skillLevel) {
        return { skillLevel: skillLevel, weight: gaussianMeanVariance(0, 1)(skillLevel) };
      }));
      var belief = gaussianMeanVariance(hypothesis.mean, hypothesis.variance);
      var utterances = ['good', 'actually good', 'silence'];
      var likelihood = secondSpeaker(trueSkillLevel, belief, utterance);
      condition(likelihood > 0);
      return hypothesis.mean;
    }
  });
}

// Compute the posterior distributions for each utterance
