// Discretized threshold RSA with belief-hypothesis inference (L2 over speaker's assumed mean)

var round1 = function(x) { return Math.round(x * 10) / 10; };

var stateGrid = map(function(i) { return round1(-3 + 0.2 * i); }, _.range(31));
var thetaGrid = map(function(i) { return round1(-3 + 0.2 * i); }, _.range(30));

var gaussDens = function(x, mu, sd) {
  return Math.exp(-0.5 * Math.pow((x - mu) / sd, 2)) / sd;
};

var statePrior = cache(function(mu, sd) {
