    // ep = 0.20 + 0.08 = 0.28 for brown, 0.64 + 0.08 = 0.72 for small
    // Brown filter applied first (phrase "small brown box")
    var eps1 = 0.28;

    factor(A1 == true ? (Math.exp( Math.log(1-eps1) ) : Math.exp(Math.log(eps1) )));

    var A2 = false;
    // Second filter eps depends on survivors
    var nSurvs = (A1 ? 1 : 0) + (B1 ? 1 : 0) + (C1 ? 1 : 0);
    var eps2 = 0.28 + 0.04 * Math.max(0, (nSurvs - 1));
    var pASurv2 = 1 - eps2;

    var A_correct = A1 && pASurv2;
    return A_correct;
  })
