// Boxes: A = small+brown, B = brown only, C = small only
// eps(adjective, n) = base + 0.04*(n-1)
// "keeps" a box that HAS the property with prob (1-eps)
// "keeps" a box that LACKS the property with prob eps

var epsRate = function(adjective, n) {
  var base = adjective === 'small' ? 0.64 : 0.20;
  return base + 0.04 * (n - 1);
};

// Returns probability of keeping a box given whether it has the property and eps
var keepProb = function(hasProperty, eps) {
  return hasProperty ? (1 - eps) : eps;
};

// Compute P(A survives both filters) for a given order [first, second]
// Properties: A={small:true, brown:true}, B={small:false, brown:true}, C={small:true, brown:false}
var boxes = [
  {name:'A', small:true,  brown:true},
  {name:'B', small:false, brown:true},
  {name:'C', small:true,  brown:false}
];

var computeProb = function(firstAdj, secondAdj) {
  // Step 1: apply firstAdj to all 3 boxes, independently
  var n1 = 3;
  var eps1 = epsRate(firstAdj, n1);

  // We want P(A survives step1 AND A survives step2)
  // A survives step1 with prob:
  var pA1 = keepProb(boxes[0][firstAdj], eps1); // A has both properties

  // Enumerate over survival of B and C in step 1 (they're independent of A)
  var pB1 = keepProb(boxes[1][firstAdj], eps1);
  var pC1 = keepProb(boxes[2][firstAdj], eps1);

  // For each combination of B,C surviving step1, compute contribution to P(A survives both)
  // Combinations: (B survives?, C survives?) -> (prob, set size in step2)
  var combos = [
    {bSurv: false, cSurv: false, prob: (1-pB1)*(1-pC1)},
    {bSurv: true,  cSurv: false, prob: pB1*(1-pC1)},
    {bSurv: false, cSurv: true,  prob: (1-pB1)*pC1},
    {bSurv: true,  cSurv: true,  prob: pB1*pC1}
  ];

  var totalProb = sum(map(function(combo) {
    // Set entering step2 includes A (given A survived step1) plus B and/or C
    var n2 = 1 + (combo.bSurv ? 1 : 0) + (combo.cSurv ? 1 : 0);
    var eps2 = epsRate(secondAdj, n2);
    var pA2 = keepProb(boxes[0][secondAdj], eps2);
    return combo.prob * pA2;
  }, combos));

  return pA1 * totalProb;
};

