    }
    return sum;
  };

  var klExplicit = KL(priorSub, listenerExplicit);
  var klSilence  = KL(priorSub, listenerSilence);

  // 8. Final decision probability
  var prefExplicit = Math.exp(-3 * klExplicit);
  var prefSilence  = Math.exp(-3 * klSilence);
  var finalProb = prefExplicit / (prefExplicit + prefSilence);

  // 9. Return distribution over explicit utterance (true=1 false=0)
  return Bernoulli({p: finalProb});
