// ---- constants ----
var expNeg32 = Math.exp(-3.2);
var expNeg64 = Math.exp(-6.4);
var g6 = 0.01 / 6;
var N = 1000;                       // lexicon samples per partner per round
var speakerRole = [1, 2, 2, 1, 1, 2, 2, 1, 1, 2];   // rounds 1..10
var wordsOf = [[0], [1], [2], [3], [0, 1], [2, 3]]; // words in each utterance

// ---- informed speaker S1 tables for a fixed lexicon ----
// returns {b: [P(u|blue) for 6 utts], r: [P(u|red) for 6 utts]}
var s1tab = function(p0, p1, p2, p3) {
  var q0 = 1 - p0;
  var q1 = 1 - p1;
  var q2 = 1 - p2;
  var q3 = 1 - p3;
  var fb4 = p0 * p1;
  var fr4 = q0 * q1;
  var fb5 = p2 * p3;
  var fr5 = q2 * q3;
  var d4 = fb4 + fr4;
  var d5 = fb5 + fr5;
  // literal listener prob of blue given each utterance
  var a0 = 0.005 + 0.99 * p0;
  var a1 = 0.005 + 0.99 * p1;
  var a2 = 0.005 + 0.99 * p2;
  var a3 = 0.005 + 0.99 * p3;
  var a4 = d4 > 0 ? 0.005 + 0.99 * fb4 / d4 : 0.5;
  var a5 = d5 > 0 ? 0.005 + 0.99 * fb5 / d5 : 0.5;
  // exp(16*(0.8*log L0 - 0.2*cost)) = L0^12.8 * exp(-3.2*cost)
  var eb0 = Math.pow(a0, 12.8) * expNeg32;
  var eb1 = Math.pow(a1, 12.8) * expNeg32;
  var eb2 = Math.pow(a2, 12.8) * expNeg32;
  var eb3 = Math.pow(a3, 12.8) * expNeg32;
  var eb4 = Math.pow(a4, 12.8) * expNeg64;
  var eb5 = Math.pow(a5, 12.8) * expNeg64;
  var er0 = Math.pow(1 - a0, 12.8) * expNeg32;
  var er1 = Math.pow(1 - a1, 12.8) * expNeg32;
  var er2 = Math.pow(1 - a2, 12.8) * expNeg32;
  var er3 = Math.pow(1 - a3, 12.8) * expNeg32;
  var er4 = Math.pow(1 - a4, 12.8) * expNeg64;
  var er5 = Math.pow(1 - a5, 12.8) * expNeg64;
  var sb = eb0 + eb1 + eb2 + eb3 + eb4 + eb5;
  var sr = er0 + er1 + er2 + er3 + er4 + er5;
  return {
    b: [g6 + 0.99 * eb0 / sb, g6 + 0.99 * eb1 / sb, g6 + 0.99 * eb2 / sb,
        g6 + 0.99 * eb3 / sb, g6 + 0.99 * eb4 / sb, g6 + 0.99 * eb5 / sb],
    r: [g6 + 0.99 * er0 / sr, g6 + 0.99 * er1 / sr, g6 + 0.99 * er2 / sr,
        g6 + 0.99 * er3 / sr, g6 + 0.99 * er4 / sr, g6 + 0.99 * er5 / sr]
  };
};

// informed listener log-prob of target object given utterance (fixed lexicon)
var l1log = function(sb, sr, targetBlue) {
  var A = Math.pow(sb, 16);
  var B = Math.pow(sr, 16);
  var pb = 0.005 + 0.99 * A / (A + B);
  return Math.log(targetBlue ? pb : 1 - pb);
};

// ---- accumulate E[log L1(target|u,lex)] over lexicon samples ----
var accSpk = function(i, bel, tb, a0, a1, a2, a3, a4, a5) {
  if (i === 0) {
    return [a0, a1, a2, a3, a4, a5];
  } else {
    var p0 = beta({a: bel[0][0], b: bel[0][1]});
    var p1 = beta({a: bel[1][0], b: bel[1][1]});
    var p2 = beta({a: bel[2][0], b: bel[2][1]});
    var p3 = beta({a: bel[3][0], b: bel[3][1]});
    var t = s1tab(p0, p1, p2, p3);
    return accSpk(i - 1, bel, tb,
      a0 + l1log(t.b[0], t.r[0], tb),
