var model = function() {
  // Prior on the speaker's situation
  var situation = flip(0.4) ? 'pregnant' : 'embarrassed'; // P(pregnant) = 0.4, P(embarrassed) = 0.6

  // Prior on speaker's Spanish competence
  var competence = flip(0.5) ? 'high' : 'low';

  // Literal meanings of English words
  var literallyTrue = {
    pregnant: function(sit) { return sit === 'pregnant'; },
    embarrassed: function(sit) { return sit === 'embarrassed'; }
  };

  // List of English words
  var englishWords = ['pregnant', 'embarrassed'];

  // Correct Spanish translations
  var translation = {
    pregnant: 'embarazada',
    embarrassed: 'avergonzada'
  };

  // The other Spanish word (the one that is NOT the correct translation)
  var otherSpanishWord = function(engWord) {
    return engWord === 'pregnant' ? 'avergonzada' : 'embarazada';
  };

  // Compute bigrams of a word
  var bigrams = function(word) {
    var bs = [];
    for (var i = 0; i < word.length - 1; i++) {
      bs.push(word.slice(i, i+2));
    }
    return bs;
  };

  // DICE coefficient between word1 and word2: 2 * |bigrams(word1) ∩ bigrams(word2)| / (|bigrams1| + |bigrams2|)
  var dice = function(word1, word2) {
    var b1 = bigrams(word1);
    var b2 = bigrams(word2);
    var set2 = {};
    for (var i = 0; i < b2.length; i++) {
      set2[b2[i]] = true;
    }
    var overlap = 0;
    for (var j = 0; j < b1.length; j++) {
      if (set2[b1[j]]) overlap += 1;
    }
    return (2 * overlap) / (b1.length + b2.length);
  };

  // Simulate the speaker's word choice
  // Speaker chooses among English words that are literally true in the situation
  var possibleWords = englishWords.filter(function(w) {
    return literallyTrue[w](situation);
  });

  // Literal listener interprets a word by restricting the prior to situations where it's true
  var literalListener = function(word) {
    var possibilities = ['pregnant', 'embarrassed'].filter(function(s) {
      return literallyTrue[word](s);
    });
    // Compute prior probabilities for those possibilities
    var probs = possibilities.map(function(s) {
      return s === 'pregnant' ? 0.4 : 0.6;
    });
    var Z = probs.reduce(function(a, b) { return a + b; }, 0);
    probs = probs.map(function(p) { return p / Z; });
    // Return probability of actual situation under this conditional
    var index = possibilities.indexOf(situation);
    return probs[index];
  };

  // Speaker optimality parameter
  var alpha = 1;

  // Speaker weights words by literal listener's belief in actual situation, raised to alpha
  var weights = possibleWords.map(function(w) {
    return Math.pow(literalListener(w), alpha);
