  // Normalize weights to get speaker's word distribution
  var totalWeight = weights.reduce(function(a, b) { return a + b; }, 0);
  var wordProbs = weights.map(function(w) { return w / totalWeight; });

  // Sample the chosen English word
  var chosenWord = possibleWords[uniformDraw(weightedSample(possibleWords, wordProbs))];

  // Now translate to Spanish
  var correctTranslation = translation[chosenWord];
  var incorrectTranslation = otherSpanishWord(chosenWord);

  var spanishWord;
  if (competence === 'high') {
    spanishWord = correctTranslation;
  } else {
    // Low competence: compare DICE similarity of chosen English word to both Spanish words
    var simToCorrect = dice(chosenWord, correctTranslation);
    var simToIncorrect = dice(chosenWord, incorrectTranslation);
    // If the incorrect Spanish word is STRICTLY more similar, use it; otherwise use correct
    if (simToIncorrect > simToCorrect) {
