// Define observer's belief update
function observersBeliefUpdate(utterance, evidence) {
  return Infer({
    method: 'enumerate',
    enumStrategy: {
      values: ['x0', 'x1']
    }
  }, function() {
    var type = sample(typePrior);
    var prevalence = prevalencePrior[type]();
    prevalence = Math.round(prevalence / snapResolution) * snapResolution;
    var threshold = sample(Uniform({a: 0, b: thresholdList.length - 1}));
    threshold = thresholdList[threshold];
    if (utterance !== undefined) {
      // Reweight by speaker's probability of producing utterance
      var utteranceProbability = Math.exp(optimalityParameter * math.log(literalListener(type, prevalence, threshold, utterance)));
      factor(utteranceProbability);
    }
    if (evidence !== undefined) {
      // Reweight by binomial probability of observing evidence
      var evidenceProbability = binomial(evidence.positives, evidence.trials - evidence.positives, prevalence);
      factor(evidenceProbability);
    }
    return {type: type, prevalence: prevalence};
  });
}

// Define literal listener
function literalListener(type, prevalence, threshold, utterance) {
  if (utterance === undefined) return 1;
  if (utterance === 'generic') {
    return prevalence > threshold ? 1 : 0;
  } else {
    return 1;
  }
}

// Define speaker
function speaker(incomingBelief) {
  return Infer({
    method: 'enumerate'
  }, function() {
    var type = sample(incomingBelief);
    var prevalence = type.prevalence;
    var utterance = sample(Categorical({ps: [0.5, 0.5], vs: ['generic', 'silence']}));
    var threshold = sample(Uniform({a: 0, b: thresholdList.length - 1}));
    threshold = thresholdList[threshold];
    var listenersBelief = observersBeliefUpdate(utterance);
    var reweightedProbability = math.exp(scalingParameter * math.log(listenersBelief.score(prevalence))) * (utterance === 'generic' ? 1 : 0);
    factor(reweightedProbability);
    return utterance;
  });
}

// Define listener population
function listenerPopulation(speakerDistribution) {
  return Infer({
    method: 'enumerate'
  }, function() {
    var utterance = sample(speakerDistribution);
    var evidence = {
      positives: sample(Binomial({n: listenerEvidenceTrials, p: listenerEvidenceProbability})),
      trials: listenerEvidenceTrials
    };
    return observersBeliefUpdate(utterance, evidence);
  });
}

