var logBinomKernel = function(k, n, p){
  var a = (k === 0) ? 0 : ((p === 0) ? -Infinity : k * Math.log(p));
  var b = ((n - k) === 0) ? 0 : ((p === 1) ? -Infinity : (n - k) * Math.log(1 - p));
  return a + b;
};

