    var snapped = Math.round(rawPreval * 20) / 20;
    return [type, snapped];
  }

  function generatePrior(ApproximationCount=10000) {
    var samples = [];
    for (var i = 0; i < ApproximationCount; i++) {
      samples.push(sampleStatePrior());
    }

    var valueCounts = {};
    for (var s of samples) {
      valueCounts[s[1]] = (valueCounts[s[1]] || 0) + 1;
    }

    var distinctValues = Object.keys(valueCounts)
      .map(parseFloat)
      .sort(function(a, b) { return a - b; });

