      }
      return state;
    };
  }

  function runBeliefUpdate(belief, utterance, directK, directM) {
    return Infer({
      method: 'rejection',
      probability: function() {
        var state = sample(belief);
        var prevalence = state[1];
        var threshold = sampleThreshold();
        var utteranceLogProb = 0;
        if (utterance === 'generic') {
          utteranceLogProb = Math.exp(
            OPT_PARAM * Math.log(
              sample(literalListenerBelief('generic', threshold)) === 'generic' ? 1 : 0
            )
          ) || 1;
        }

        var binomialLikelihood;
        if (typeof directK !== 'undefined' && typeof directM !== 'undefined') {
          binomialLikelihood = function() {
            return Math.pow(prevalence, directK) * 
                     Math.pow(1 - prevalence, directM);
