  var beliefSequence = [beliefForPrior];
  var speakerSequence = [sample(flip(0.5))];

  for (var i = 0; i < 6; i++) {
    var speakerInput = beliefSequence[i];
    var generatedSpeaker = Infer({method: 'enumerate', samples: 100}, function() {
      var choice = 'generic';
      var state = sample(speakerInput);
