  for (var n = 0; n < 7; n++) {
    var belief = beliefSequence[n];
    var speakerOutcome = Infer({method: 'SMC', steps: 50}, function() {
      var utterance = sample(flip(0.5) ? 'generic' : 'silence');
      var logPosterior = 0;
