// ── helpers ──────────────────────────────────────────────────────────────────
var snap = function(x){ return Math.round(x / 0.05) * 0.05; };
var clamp01 = function(x){ return Math.max(0, Math.min(1, x)); };

// log-sum-exp
var logSumExp = function(arr){
  var m = Math.max.apply(null, arr);
  if(!isFinite(m)) return -Infinity;
  return m + Math.log(_.sum(map(function(x){ return Math.exp(x - m); }, arr)));
};

// binomial log-prob
var binomLogProb = function(k, n, p){
  if(p === 0) return k === 0 ? 0 : -Infinity;
  if(p === 1) return k === n ? 0 : -Infinity;
  var lc = 0;
  for(var i=0;i<k;i++) lc += Math.log(n-i) - Math.log(i+1);
  return lc + k*Math.log(p) + (n-k)*Math.log(1-p);
};

// ── 1. Build state prior from 10000 samples ──────────────────────────────────
var N = 10000;
var rawSamples = repeat(N, function(){
  var isX1 = flip(0.05);
  var type = isX1 ? 'x1' : 'x0';
  var prev = isX1 ? sample(Beta({a:1,b:4})) : sample(Beta({a:0.1,b:100}));
  return {type: type, prev: clamp01(snap(prev))};
});

// Collect unique (type,prev) pairs and their weights
var stateMap = {};
map(function(s){
  var key = s.type + '|' + s.prev;
  stateMap[key] = (stateMap[key] || {type:s.type, prev:s.prev, count:0});
  stateMap[key].count += 1;
}, rawSamples);
var stateList = _.values(stateMap);
var stateWeights = map(function(s){ return s.count/N; }, stateList);

// ── 2. Threshold list ─────────────────────────────────────────────────────────
var distinctPrevs = _.sortBy(_.uniq(map(function(s){ return s.prev; }, stateList)));
var thresholds = _.sortBy(_.uniq(map(function(v){
  var t = v - 0.025; return t < 0 ? v : t;
}, distinctPrevs)));
var nThresh = thresholds.length;

// ── 3. Literal listener: for each threshold, compute log-probs over states ───
// L0(threshold, utterance='generic') ∝ stateWeight * (prev > threshold ? 1 : 0)
// L0(threshold, utterance='silence') ∝ stateWeight * 1
var L0_generic = map(function(thr){
  var logW = map(function(i){
    var s = stateList[i];
    return s.prev > thr ? Math.log(stateWeights[i]) : -Infinity;
  }, _.range(stateList.length));
  var Z = logSumExp(logW);
  return map(function(lw){ return lw - Z; }, logW);
}, thresholds);

var L0_silence = map(function(thr){
  var logW = map(function(i){ return Math.log(stateWeights[i]); }, _.range(stateList.length));
  var Z = logSumExp(logW);
  return map(function(lw){ return lw - Z; }, logW);
}, thresholds);

// ── 4. First-order speaker probability of 'generic' given (stateIdx, thrIdx) ─
var alpha = 5;
var S1_generic_prob = map(function(ti){
  return map(function(si){
    var prev = stateList[si].prev;
    var lpGeneric = L0_generic[ti][si];
    var lpSilence = L0_silence[ti][si]; // all states get same mass up to Z diff
    var uGeneric = alpha * lpGeneric;
    var uSilence = alpha * lpSilence;
    var Z2 = logSumExp([uGeneric, uSilence]);
    return Math.exp(uGeneric - Z2);
  }, _.range(stateList.length));
}, _.range(nThresh));

// ── 5. Observer belief update ─────────────────────────────────────────────────
// Returns array of log-weights over stateList (unnormalized)
var observerUpdate = function(heardUtterance, directK, directM){
  // For each (state, threshold) pair compute log-weight
  // Joint weight = stateWeight * (1/nThresh) * speakerProb(utterance) * binomProb
  var logW = map(function(si){
    var sw = Math.log(stateWeights[si]);
    var prev = stateList[si].prev;
    // marginalize over thresholds
    var thrLogWeights = map(function(ti){
      var lp = -Math.log(nThresh);
      if(heardUtterance !== null){
        var pg = S1_generic_prob[ti][si];
        var prob = heardUtterance === 'generic' ? pg : (1 - pg);
        if(prob <= 0) return -Infinity;
        lp += Math.log(prob);
      }
      return lp;
    }, _.range(nThresh));
    var thrLSE = logSumExp(thrLogWeights);
    var base = sw + thrLSE;
    if(directK !== null){
      base += binomLogProb(directK, directK + directM, prev);
    }
    return base;
  }, _.range(stateList.length));
  var Z = logSumExp(logW);
  return map(function(lw){ return lw - Z; }, logW);
};

// Expected prevalence from log-weight array
var expectedPrev = function(logW){
  return _.sum(map(function(i){ return Math.exp(logW[i]) * stateList[i].prev; }, _.range(stateList.length)));
};

// ── 6. Generation speaker: given incoming belief logW ────────────────────────
var genSpeakerGenericProb = function(incomingLogW){
  // For each (state drawn from incoming, threshold), compute reweighted generic probability
  // Speaker draws (type,prev) from incoming belief, picks utterance
  // Reweights by: observer update with that utterance (no direct evidence), evaluated at true prev
  var logWgen = map(function(si){
    var lp = incomingLogW[si];
    // observer update with 'generic', no direct evidence
    var postGen = observerUpdate('generic', null, null);
    var prevProb = Math.exp(postGen[si]);
    return lp + Math.log(prevProb > 0 ? prevProb : 1e-300);
  }, _.range(stateList.length));
  var logWsil = map(function(si){
    var lp = incomingLogW[si];
    var postSil = observerUpdate('silence', null, null);
    var prevProb = Math.exp(postSil[si]);
    return lp + Math.log(prevProb > 0 ? prevProb : 1e-300);
  }, _.range(stateList.length));
  var totalGen = Math.exp(logSumExp(logWgen));
  var totalSil = Math.exp(logSumExp(logWsil));
  return totalGen / (totalGen + totalSil);
};

// ── 7. Generation listener: given speaker generic prob, returns belief logW ───
// Fresh direct evidence: k ~ Binomial(10, 0.1)
var freshK_probs = map(function(k){ return Math.exp(binomLogProb(k, 10, 0.1)); }, _.range(11));

var genListenerBelief = function(speakerGenProb){
  // Marginalize over utterance (generic w.p. speakerGenProb, silence w.p. 1-speakerGenProb)
  // and fresh direct evidence k=0..10
  var logW_total = map(function(si){
    var terms = [];
    // utterance = generic
    var wGen = speakerGenProb;
    if(wGen > 0){
      for(var k=0;k<=10;k++){
        var post = observerUpdate('generic', k, 10-k);
        terms.push(Math.log(wGen) + Math.log(freshK_probs[k]) + post[si]);
      }
    }
    // utterance = silence
    var wSil = 1 - speakerGenProb;
    if(wSil > 0){
      for(var k=0;k<=10;k++){
        var post2 = observerUpdate('silence', k, 10-k);
        terms.push(Math.log(wSil) + Math.log(freshK_probs[k]) + post2[si]);
      }
    }
    return logSumExp(terms);
  }, _.range(stateList.length));
  var Z = logSumExp(logW_total);
  return map(function(lw){ return lw - Z; }, logW_total);
};

