function model() {
  // Define prevalence bins: 0.01, 0.03, 0.05, ..., 0.99
  const prevalenceBins = [];
  for (let i = 1; i <= 50; i++) {
    prevalenceBins.push(i * 0.02);
  }

  // Define threshold midpoints: 0.02, 0.04, ..., 0.98
  const thresholdMidpoints = [];
  for (let i = 1; i < 50; i++) {
    thresholdMidpoints.push((i + 1) * 0.02);
  }

  // Probability alpha for mixture component 1 is 0.3
  const alpha = 0.3;

  // Sample prevalence from mixture prior
  let prevalence;
  if (flip(alpha)) {
    // Beta with a=5, b=5 (mean=0.5, concentration=10)
    const a = 5, b = 5;
    let weights = [];
    for (let i = 0; i < prevalenceBins.length; i++) {
      const x = prevalenceBins[i];
      weights.push(Math.pow(x, a - 1) * Math.pow(1 - x, b - 1));
    }
    // Normalize weights
    const totalWeight = weights.reduce((sum, w) => sum + w, 0);
    const normalizedWeights = weights.map(w => w / totalWeight);
    prevalence = prevalenceBins(categorical(normalizedWeights));
  } else {
    // Beta with a=1, b=99 (very low-prevalence)
    const a = 1, b = 99;
    let weights = [];
    for (let i = 0; i < prevalenceBins.length; i++) {
      const x = prevalenceBins[i];
      weights.push(Math.pow(x, a - 1) * Math.pow(1 - x, b - 1));
    }
    // Normalize weights
    const totalWeight = weights.reduce((sum, w) => sum + w, 0);
    const normalizedWeights = weights.map(w => w / totalWeight);
    prevalence = prevalenceBins(categorical(normalizedWeights));
  }

  // Sample threshold uniformly from midpoints
  const threshold = randomInteger(0, 49);
  const thresholdValue = thresholdMidpoints[threshold];

  // Generic statement is true if prevalence exceeds threshold
  condition(prevalence > thresholdValue, 1);

  return prevalenceBins(categorical([1])); // Just return the mean of the bin as the answer is the prevalence distribution
}

