function sum(arr){
  var s = 0;
  for (var i = 0; i < arr.length; i++) s += arr[i];
  return s;
}

// literal listener posterior over qualities given an utterance
function literalPosterior(u){
  var lik = probTable[u];
  var Z = sum(lik);
  var post = [];
  for (var i = 0; i < lik.length; i++) {
    post.push(lik[i] / Z);
  }
  return post; // array of length 5, index 0 => quality 1
}

// utility for a given utterance, true state, QUD and weight
function utility(u, trueQ, trueA, qud, w){
  var post = literalPosterior(u);
  var probTrue, expected;
  if (qud === "quality"){
    probTrue = post[trueQ-1];
    expected = 0;
    for (var i = 0; i < 5; i++) expected += post[i] * (i+1);
  } else { // arousal
    probTrue = 0;
    for (var i = 0; i < 5; i++) {
      if (arousalVals[i+1] === trueA) probTrue += post[i];
    }
    expected = 0;
    for (var i = 0; i < 5; i++) expected += post[i] * arousalVals[i+1];
  }
  return w * Math.log(probTrue) + (1-w) * 1.25 * expected;
}

// speaker distribution over utterances given state, QUD and weight
function speakerDist(stateQ, stateA, qud, w){
  var utils = utterances.map(function(u){ return utility(u, stateQ, stateA, qud, w); });
  var maxU = Math.max.apply(null, utils);
  var expVals = utils.map(function(u){ return Math.exp(10 * (u - maxU)); }); // alpha = 10
  var Z = sum(expVals);
  return expVals.map(function(v){ return v / Z; });
}

