  // for "habitual": only lf > thresh
  var compatible = _.filter(_.range(nGrid), i => grid[i] > thresh);
  var Z = _.sum(compatible.map(i => priorLF[i])); // normaliser
  var pHabit = (lf > thresh) ? pPrior / Z : 0;
