  var den = _.sum(_.range(nGrid).map(lIdx => {
    var inner = _.sum(_.range(nThresh).map(tIdx => (1/nThresh)*speaker1Prob(utter, lIdx, tIdx)));
    return priorLF[lIdx] * inner;
  }));
  return num/den;
