    var nextWords = vocabulary.filter(function(word) {
      return utterance.concat([word]).every(function(word, index) {
        return index === 0 || index === utterance.length + 1 || utterances.some(function(completion) {
          return completion.slice(0, utterance.length + 1).every(function(word2, index2) {
            return word2 === utterance[index2] || (index2 === index && word2 === word);
          });
        });
      });
    });
    var probabilities = incrementalLiteralListener(utterance);
    var weightedProbabilities = {};
    nextWords.forEach(function(word) {
      weightedProbabilities[word] = probabilities[referent];
    });
    return categorical(weightedProbabilities);
  }
