// Helper functions
function normalize(probabilities) {
  var total = Object.values(probabilities).sum();
  return Object.keys(probabilities).reduce(function(acc, key) {
    acc[key] = probabilities[key] / total;
    return acc;
  }, {});
}

function probabilityOf(listenerProbabilities, referent, word) {
  return listenerProbabilities[referent];
}

function categorical(probabilities) {
  var keys = Object.keys(probabilities);
  var values = Object.values(probabilities);
  var total = values.sum();
  var random = Math.random() * total;
  var cumulative = 0;
  for (var i = 0; i < keys.length; i++) {
    cumulative += values[i];
    if (random < cumulative) {
      return keys[i];
    }
  }
}

function uniformDraw(options) {
  return options[Math.floor(Math.random() * options.length)];
}

