var alpha = 1;

// word-level truth (1/0)
var truthWord = function(w, r) {
  return (w === 'red') ? ((r === 'R1' || r === 'R3') ? 1 : 0)
       : (w === 'dress') ? ((r === 'R1' || r === 'R2') ? 1 : 0)
       : 1; // 'object', 'start', 'end' trivially true
};

// plain literal truth of a (possibly partial) word sequence
var plainTruth = function(words, r) {
  return reduce(function(w, acc) { return acc * truthWord(w, r); }, 1, words);
};

// the three complete utterances
var completes = [
  ['start', 'dress', 'end'],
  ['start', 'red', 'dress', 'end'],
  ['start', 'red', 'object', 'end']
];
var names = ['dress', 'red dress', 'red object'];

// prefix test
var isPrefix = function(p, u) {
  return (p.length > u.length) ? false
    : all(function(x) { return x; },
          mapIndexed(function(i, w) { return w === u[i]; }, p));
};

var wellFormed = function(p) {
  return any(function(u) { return isPrefix(p, u); }, completes);
};

// ---------- global model ----------
var globalListenerProb = function(u, r) {
  var ws = map(function(rr) { return plainTruth(u, rr); }, refs);
  var Z = sum(ws);
  return (Z === 0) ? 0 : plainTruth(u, r) / Z;
};

var globalSpeaker = function(r) {
  return Infer({method: 'enumerate'}, function() {
    var i = randomInteger(3);
    var L = globalListenerProb(completes[i], r);
    condition(L > 0);
    factor(alpha * Math.log(L));
    return names[i];
  });
};

// ---------- incremental model ----------
// graded truth: fraction of completions of prefix p that are plainly true at r
var gradedTruth = function(p, r) {
  var exts = filter(function(u) { return isPrefix(p, u); }, completes);
  var vals = map(function(u) { return plainTruth(u, r); }, exts);
  return (exts.length === 0) ? 0 : sum(vals) / exts.length;
};

var incListenerProb = function(p, r) {
  var ws = map(function(rr) { return gradedTruth(p, rr); }, refs);
  var Z = sum(ws);
  return (Z === 0) ? 0 : gradedTruth(p, r) / Z;
};

var nextWordProb = function(prefix, word, r) {
  var cands = filter(function(w) { return wellFormed(prefix.concat([w])); }, vocab);
  if (plainTruth(prefix, r) === 0) {
    return 1 / cands.length;
  } else {
    var ws = map(function(c) {
      return Math.pow(incListenerProb(prefix.concat([c]), r), alpha);
    }, cands);
    var Z = sum(ws);
    var wWord = Math.pow(incListenerProb(prefix.concat([word]), r), alpha);
    return (Z === 0) ? (1 / cands.length) : (wWord / Z);
  }
};

var incrementalUttProb = function(u, r) {
  var probs = mapIndexed(function(i, w) {
    return nextWordProb(u.slice(0, i), w, r);
  }, u);
  return reduce(function(x, acc) { return acc * x; }, 1, probs);
};

