// Properties
var isRed = function(r) { return r === 'R1' || r === 'R3'; };
var isDress = function(r) { return r === 'R1' || r === 'R2'; };
var isObject = function(r) { return true; };
var isOpening = function(r) { return true; };
var isClosing = function(r) { return true; };

// Utterances: represented as lists of words
var utterances = {
  "dress": ["<s>", "dress", "</s>"],
  "red dress": ["<s>", "red", "dress", "</s>"],
  "red object": ["<s>", "red", "object", "</s>"]
};

// Check if a word sequence is a valid prefix of any complete utterance
var isValidPrefix = function(prefix) {
  var isPrefix = function(utt) {
    return _.isEqual(prefix, utt.slice(0, prefix.length));
  };
  return _.some(_.values(utterances), isPrefix);
};

// Get all complete utterances that extend a given prefix
var getExtensions = function(prefix) {
  return _.filter(_.keys(utterances), function(key) {
    var utt = utterances[key];
    return _.isEqual(prefix, utt.slice(0, prefix.length));
  });
};

// Plain literal truth of a complete utterance at a referent
var literalTruth = function(utt, r) {
  var words = utterances[utt];
  return _.all(words, function(w) {
    if (w === "red") return isRed(r);
    if (w === "dress") return isDress(r);
    if (w === "object") return isObject(r);
    if (w === "<s>") return isOpening(r);
    if (w === "</s>") return isClosing(r);
    return false;
  }) ? 1 : 0;
};

// Global literal listener: P(referent | utterance)
var literalListener_global = cache(function(utt) {
  return Infer({method: 'enumerate'}, function() {
    var r = sample(prior);
    var truth = literalTruth(utt, r);
    condition(truth === 1);
    return r;
  });
});

// Global speaker: P(utterance | referent)
var speaker_global = cache(function(r) {
  return Infer({method: 'enumerate'}, function() {
    var utt = uniformDraw(_.keys(utterances));
    var L0_prob = Math.exp(literalListener_global(utt).score(r));
    factor(Math.log(L0_prob)); // optimality parameter = 1
    return utt;
  });
});

// Graded truth of a (possibly partial) prefix at a referent
var gradedTruth = function(prefix, r) {
  var extensions = getExtensions(prefix);
  var total = extensions.length;
  if (total === 0) return 0;
  var trueCount = _.sum(extensions, function(utt) {
    return literalTruth(utt, r);
  });
  return trueCount / total;
};

// Incremental literal listener: P(referent | prefix)
var literalListener_incremental = cache(function(prefix) {
  return Infer({method: 'enumerate'}, function() {
    var r = sample(prior);
    var gTruth = gradedTruth(prefix, r);
    factor(Math.log(gTruth));
    return r;
  });
});

// Incremental production: P(word | prefix, referent)
var nextWordProb = cache(function(prefix, r) {
  var candidates = _.filter(['<s>', 'red', 'dress', 'object', '</s>'], function(w) {
    var extended = prefix.concat([w]);
    return isValidPrefix(extended);
  });

  // If current prefix is already literally false, choose uniformly
  var currentTruth = gradedTruth(prefix, r);
  if (currentTruth === 0) {
    return Categorical({vs: candidates, ps: Array(candidates.length).fill(1)});
  }

  // Otherwise, reweight by incremental listener's belief
  var scores = map(function(w) {
    var extended = prefix.concat([w]);
    var L_inc = literalListener_incremental(extended);
    return L_inc.score(r); // log probability
  }, candidates);

  return Categorical({vs: candidates, ps: scores});
});

// Incremental production probability of a full utterance given referent
var incrementalProductionProb = function(utt, r) {
  var words = utterances[utt];
  var prob = 1;
  var prefix = [];
  for (var i = 0; i < words.length; i++) {
    var w = words[i];
    var dist = nextWordProb(prefix, r);
    var p = Math.exp(dist.score(w));
    prob *= p;
    prefix = prefix.concat([w]);
  }
  return prob;
};

