// Truth functions
var wordTruth = function(word, ref) {
  if (word === "O" || word === "C" || word === "object") return 1;
  if (word === "red") return (ref === "R1" || ref === "R3") ? 1 : 0;
  if (word === "dress") return (ref === "R1" || ref === "R2") ? 1 : 0;
  return 1;
};

