};
var uttNames = ["dress", "red dress", "red object"];

// Plain literal truth of a complete utterance
var plainTruth = function(uttName, ref) {
  var words = utterances[uttName];
  return reduce(function(w, acc) { return acc * wordTruth(w, ref); }, 1, words);
};

// Global literal listener: P(ref | complete utterance)
var globalL0 = function(uttName) {
  return Infer({method: 'enumerate'}, function() {
    var ref = uniformDraw(referents);
    condition(plainTruth(uttName, ref) === 1);
    return ref;
  });
