// Graded truth: fraction of complete utterances extending the prefix that are literally true
var isPrefix = function(prefix, uttName) {
  var words = utterances[uttName];
  if (prefix.length > words.length) return false;
  return all(function(i) { return prefix[i] === words[i]; }, _.range(prefix.length));
};

var gradedTruth = function(prefix, ref) {
  var extenders = filter(function(u) { return isPrefix(prefix, u); }, uttNames);
  if (extenders.length === 0) return 0;
  var trues = filter(function(u) { return plainTruth(u, ref) === 1; }, extenders);
  return trues.length / extenders.length;
};

// Incremental literal listener: P(ref | prefix) proportional to uniform * gradedTruth
var incL0prob = function(prefix, ref) {
  var weights = map(function(r) { return gradedTruth(prefix, r); }, referents);
  var total = sum(weights);
  if (total === 0) return 1 / 3;
  var idx = indexOf(ref, referents);
  return weights[idx] / total;
};

// Next-word candidates: words that keep the prefix well-formed
var nextWordCandidates = function(prefix) {
  var vocab = ["O", "red", "dress", "object", "C"];
  return filter(function(w) {
    var extended = prefix.concat([w]);
    return any(function(u) { return isPrefix(extended, u); }, uttNames);
  }, vocab);
};

// Probability of choosing word w from prefix, given true referent
var nextWordProb = function(prefix, w, trueRef) {
  var candidates = nextWordCandidates(prefix);
  if (!member(w, candidates)) return 0;
  // Check if prefix is plainly literally false of trueRef
  // = gradedTruth is 0
  var gt = gradedTruth(prefix, trueRef);
  if (gt === 0) {
    // Uniform over grammatical candidates
    return 1 / candidates.length;
  } else {
    // Weighted by incremental listener probability of trueRef given extended prefix
    var extWeights = map(function(c) {
      var extended = prefix.concat([c]);
      return incL0prob(extended, trueRef);
    }, candidates);
    var total = sum(extWeights);
    var idx = indexOf(w, candidates);
    return total === 0 ? (1 / candidates.length) : extWeights[idx] / total;
  }
};

// Incremental production probability of a complete utterance given true referent
var incrementalProd = function(uttName, trueRef) {
  var words = utterances[uttName];
  // Product over each word given the prefix before it
  var result = reduce(function(i, acc) {
    var prefix = words.slice(0, i);
    var w = words[i];
    return acc * nextWordProb(prefix, w, trueRef);
  }, 1, _.range(words.length));
  return result;
};

