  terrible: [1,10,30,45,50],
  bad:      [1,5,25,40,45],
  ok:       [50,45,30,10,1],
  good:     [1,5,25,40,45],
  amazing:  [1,10,30,45,50]
};
function arousalProb(state,a) {
  var weights = arousalWeightTable[state];
  var sum = weights.reduce(function(x,y){return x+y;},0);
  var idx = arousalValues.indexOf(a);
  return weights[idx] / sum;
