  var state_idx = sample(categorical([1, 5, 40, 40, 40]));

  // 2. Sample Valence
  var p_neg = p_neg1[state_idx];
  var val_short = sample(bernoulli(p_neg)); // 1 if -1, 0 if 1 (consistent with P(-1)=p)
  var valence = (val_short === 1) ? -1 : 1;

