  var w_state = aw_by_state[state_idx];
  var w_sum = sum(w_state);
  var w_arousal = w_state.map(function(w) { return w / w_sum; });
  var arousal_idx = sample(categorical(w_arousal));
  var arousal = arousal_values[arousal_idx];

