      var prob = (valence === -1) ? p_neg1[u_idx] : (1 - p_neg1[u_idx]);
      score = prob;
    } else { // goalArousal
      var w_u = aw_by_state[u_idx];
      var u_sum = sum(w_u);
      var idx_a = arousal_values.indexOf(arousal);
      score = w_u[idx_a] / u_sum;
    }
    scores.push(score);
  }
  var U_idx = sample(categorical(scores));
  var utterance = U_choices[U_idx];

