var literalListenerScore = function(utterance, goal, targetValue) {
  var s = utterance; // L0 conditions on state == utterance, drawn uniformly
  if (goal === "goalState") {
    return targetValue === s ? 1.0 : 0.0;
  } else if (goal === "goalValence") {
    return valenceProbGivenState(targetValue, s);
  } else {
    return arousalProbGivenState(targetValue, s);
  }
};

