    var valence = flip(valenceProbNeg[state]) ? -1 : 1;

    // Draw arousal conditionally given state
    var arousalIdx = categorical({vs: [0,1,2,3,4], ps: arousalWeights[state]});
    var arousal = arousalValues[arousalIdx];

    // Draw goal uniformly
    var goal = uniformDraw(goals);

