    var scores = map(function(u) {
      return speakerUtteranceScore(u, state, valence, arousal, goal);
    }, utterances);
    var total = sum(scores);
    var myScore = speakerUtteranceScore(observedUtt, state, valence, arousal, goal);
    var logProb = total === 0 ? -Infinity : Math.log(myScore / total);
    factor(logProb);

    return {state: state, valence: valence, arousal: arousal};
  });
};

