var ANSWER = Infer({method: 'enumerate'}, function() {
    var alpha = 5;
    var classes = ['child', 'adult', 'bodybuilder'];

    // Box weights
    var w_vals = [0.0];
    for (var i = 1; i < 30; i++) w_vals.push(i * 0.2);

    // Threshold sets
    var th_set = w_vals.map(function(v) { return v - 0.1; });
    var tl_set = w_vals.map(function(v) { return v + 0.1; });

    // Prior for Comparison Class given Speaker = child
    var p_c = [0.75, 0.25, 0.15];

    // Gaussian parameters
    var mu_map = { child: 0.5, adult: 2.0, bodybuilder: 5.0 };
    var sigma_map = { child: 1.0, adult: 3.0, bodybuilder: 3.0 };

    // 1. Sample Comparison Class
    var c = sample(categorical(p_c, classes));

    // 2. Sample Weight W from discrete Gaussian
    var w_norms = [];
    for (var w of w_vals) {
        var mu = mu_map[c];
        var sigma = sigma_map[c];
        w_norms.push(Math.exp(-0.5 * Math.pow((w - mu) / sigma, 2)));
    }
    var w_sum = w_norms.reduce(function(a, b) { return a + b; }, 0);
    var w_probs = w_norms.map(function(v) { return v / w_sum; });

    var w = sample(categorical(w_probs, w_vals));

    // 3. Sample Thresholds
    // Uniform over the sets
    var th_t = sample(categorical(Array(30).fill(1/30), th_set));
    var tl_t = sample(categorical(Array(30).fill(1/30), tl_set));

    // 4. Speaker Model Utility
    // "heavy" is true with prob 0.9999 if w > th_t
    var p_m_h = (w > th_t) ? 0.9999 : 0.0001;
    // "light" is true with prob 0.9999 if w < tl_t
    var p_m_l = (w < tl_t) ? 0.9999 : 0.0001;

    // Score = log(prob) -> Prob proportional to exp(alpha * log(prob)) = prob^alpha
    var score_h = Math.pow(p_m_h, alpha);
    var score_l = Math.pow(p_m_l, alpha);

    var p_h = score_h / (score_h + score_l);

    // 5. Sample Utterance U
    var u = sample(categorical([1 - p_h, p_h], ['light', 'heavy']));

    // 6. Condition on hearing "heavy"
    condition(u === 'heavy');

    // 7. Return weight
    return w;
});

