    }
  }
  var utterances = oneWord.concat(twoWord);

  // Utterance cost
  function cost(u) { return u.indexOf(' ') >= 0 ? 0.5 : 0.25; }

  // Matching function for literal listener
  function objMatches(obj, u) {
    if (u.indexOf(' ') >= 0) {
      var uParts = u.split(' ');
      var oParts = obj.split(' ');
      return oParts[0]===uParts[0] && oParts[1]===uParts[1];
