    for (var k=0; k<context.length; k++) {
      var obj = context[k];
      var w = objMatches(obj,u) ? 1 : Math.exp(-100);
      totalWeight += w;
      if (obj===d) probWeight = w;
    }
    return probWeight / totalWeight;
  }

