  function marginalizedScore(u, target) {
    var sum = 0;
    for (var k=0; k<objects.length; k++) {
      var hidden = objects[k];
      var ctx = Array.from(new Set(shared.concat([hidden]))); // dedupe
      sum += listenerProb(ctx, u, target);
