var STATES = [0,1,2];
var UTT = ['null','every-not'];
var SCOPES = ['surface','inverse'];
var QUDS = ['how many?','all red?','none red?'];
var COST = 1;
var ALPHA = 1;

// utterance truth conditions
function utteranceTrue(u, scope, state){
  if (u === 'null') return true;
  // every-not
  if (scope === 'surface') return state === 0;
  // inverse
  return state < 2;
}

// QUD mapping
function QUDvalue(q, state){
  if (q === 'how many?') return state;
  if (q === 'all red?') return state === 2;
  // none red?
  return state === 0;
}

// literal listener score for a given world, scope, QUD and utterance
function literalScore(state, scope, qud, utter){
  // possible underlying states (uniform prior over 0,1,2)
  var poss = [];
  for (var s of STATES){
    if (utteranceTrue(utter, scope, s)){
      poss.push(s);
    }
  }
  var Z = poss.length; // uniform weighting
  var targetAns = QUDvalue(qud, state);
  var match = 0;
  for (var s of poss){
    if (QUDvalue(qud, s) === targetAns) match++;
  }
  return Z === 0 ? 0 : match / Z;
}

// probability that S1 produces utterance u given state, scope, QUD
function S1Prob(u, state, scope, qud){
  // compute scores for both utterances
  var scores = {};
  for (var utt of UTT){
    scores[utt] = literalScore(state, scope, qud, utt);
  }
  // raw (unnormalised) weights
  var raw = {};
  var sum = 0;
  for (var utt of UTT){
    raw[utt] = Math.exp(ALPHA * (scores[utt] - COST));
    sum += raw[utt];
  }
  return raw[u] / sum;
}

// pragmatic listener posterior probability that world == targetState given utterance
function L1Posterior(targetState, utter){
  var posterior = Infer({method:'enumerate'}, function(){
    // state prior (binomial)
    var state = categorical([0.25,0.5,0.25]);
    var scope = uniformDraw(SCOPES);
    var qud = uniformDraw(QUDS);
    var probU = S1Prob(utter, state, scope, qud);
    factor(Math.log(probU)); // condition on S1 choosing this utterance
    return state;
  });
  return posterior.get(targetState);
}

