// WebPPL program to compute the pragmatic speaker (S2) distribution
// over utterances ["null", "every-not"] at world state 1.

var states = [0, 1, 2];
var scopeList = ["surface", "inverse"];           // 0.5 each
var quidList = ["how many?", "all red?", "none red?"]; // 1/3 each
var utterations = ["null", "every-not"];
var cost = 1;
var alpha = 1;

// Truth conditions for utterances under scopes
function truth(u, scope, state) {
  if (u === "null") return true;
  if (u === "every-not") {
    if (scope === "surface") return state === 0;
    if (scope === "inverse") return state < 2;
    throw "unknown scope";
  }
  throw "unknown utterance";
}

// Quantity function for QUDs
function quantity(quid, state) {
  if (quid === "how many?") return state;
  if (quid === "all red?")  return state === 2 ? 1 : 0;
  if (quid === "none red?") return state === 0 ? 1 : 0;
  throw "unknown QUD";
}

// Literal-listener score: probability that the returned quantity equals
// the target quantity for the true state, given scope and utterance.
function computeScore(state, scope, quid, u) {
  var validStates = states.filter(function(s) { return truth(u, scope, s); });
  var target = quantity(quid, state);
  var count = validStates.filter(function(s) { return quantity(quid, s) === target; })
                         .length;
  return count / validStates.length;   // probability
}

// Speaker S1 distribution over utterances given state, scope, QUD
function speakerDist(state, scope, quid) {
  var weights = utterations.map(function(u) {
    var ss = computeScore(state, scope, quid, u);
    return Math.exp(alpha * (ss - cost));   // weight
  });
  var sum = weights.reduce(function(a, b) { return a + b; }, 0);
  var probs = weights.map(function(w) { return w / sum; });
  var dist = {};
  utterations.forEach(function(u, i) { dist[u] = probs[i]; });
  return dist;   // maps utterance -> probability
}

// P(u | state) = average over scope and QUD of S1 probabilities
function P_u_given_s(u, state) {
  var sum = 0;
  scopeList.forEach(function(scp) {
    quidList.forEach(function(q) {
      sum += speakerDist(state, scp, q)[u];
    });
  });
  return sum / (scopeList.length * quidList.length);
}

// Posterior probability that the true state is stateTarget given utterance u
function posteriorStateProb(u, stateTarget) {
  var numerators = [];
  var total = 0;
  states.forEach(function(s) {
    var prior = (s === 0) ? 0.25 : (s === 1) ? 0.5 : 0.25;
    var pU = P_u_given_s(u, s);
    var num = prior * pU;
    numerators.push({state: s, num: num});
    total += num;
  });
  var targetNum = numerators.filter(function(x) { return x.state === stateTarget; })[0].num;
  return targetNum / total;
}

// Compute S2 weights for each utterance
var s2_weights = {};
utterations.forEach(function(u) {
  s2_weights[u] = posteriorStateProb(u, 1);   // target state is 1
});
var sumWeights = utterations.reduce(function(a, u) { return a + s2_weights[u]; }, 0);
var s2_probs = utterations.map(function(u) { return s2_weights[u] / sumWeights; });

// Final distribution
var ANSWER = categorical({ vs: utterations, ps: s2_probs });

