  var Z = 0.0, correct = 0.0;
  worlds.forEach(function(wp){
    if (truth(u,wp,s)){
      var weight = 1/3;                // uniform prior over worlds
      Z += weight;
      if (answer(wp,q) === answer(w,q)){
        correct += weight;
      }
    }
  });
  return Z > 0 ? correct / Z : 0;
};

