var speaker2Dist = function(w){
  var wNull = S1Weight('null',w);
  var wNot  = S1Weight('not-two',w);
  // normalize the level‑1 speaker
  var Z1 = wNull + wNot;
  var pNull = wNull / Z1;
  var pNot  = wNot  / Z1;

