  var L1 = function(u){
    var probs = worlds.map(function(wp){
      var prior = 1/3;
      var s1 = (u === 'null' ? pNull : pNot); // same as above because S1 for the given world
      // we need the listener to marginalise over world priors and speaker choices
      // compute P(wp | u) ∝ prior(wp) * S1Prob(u|wp)
      var wNull_wp = S1Weight('null',wp);
      var wNot_wp  = S1Weight('not-two',wp);
      var Z_wp = wNull_wp + wNot_wp;
      var S1prob = (u === 'null' ? wNull_wp : wNot_wp) / Z_wp;
