function posteriorStateProb(stateTrue, utter) {
  var num = (1 / 3) * speaker1Prob(stateTrue, utter);
  var denom = states.reduce((sum, s) => sum + (1 / 3) * speaker1Prob(s, utter), 0);
  return num / denom;
}

