// RSA hierarchy for the rabbit‑feeding scenario
var worlds = [0,1,2,3,4];               // number of rabbits fed
var utterances = ['null','not-two'];    // possible utterances
var utterancePrior = [1,10];            // categorical prior weights
var cost = 1;                           // utterance cost
var alpha = 1;                          // rationality parameter

var scopes = ['surface','inverse'];     // equally likely scopes
var scopePrior = [0.5,0.5];

var quds = ['how many?','all red?','none red?']; // equally likely QUDs
var qudPrior = [1/3,1/3,1/3];

// ---------- Semantics ----------
var semantics = function(u, s, w){
  if (u === 'null') return true;
  // 'not-two' under the two possible scopes
  if (u === 'not-two'){
    if (s === 'surface') return w < 2;   // fewer than 2 rabbits fed
    if (s === 'inverse') return w < 3;   // fewer than 3 rabbits fed
  }
  return false;
};

// ---------- QUD projection ----------
var qudValue = function(q, w){
  if (q === 'how many?') return w;
  if (q === 'all red?') return w === 4;
  if (q === 'none red?') return w === 0;
};

// ---------- Literal listener ----------
var literalProb = function(v, u, s, q){
  var total = 0, good = 0;
  worlds.forEach(function(w){
    if (semantics(u,s,w)){
      total += 1;
      if (qudValue(q,w) === v) good += 1;
    }
  });
  return total === 0 ? 0 : good / total;
};

// ---------- First‑level speaker ----------
var speaker1Weight = function(u, w, s, q){
  var priorU = utterancePrior[utterances.indexOf(u)];
  var v = qudValue(q,w);
  var lp = literalProb(v, u, s, q);          // P_L0(v | u, s, q)
  return priorU * Math.pow(lp, alpha) * Math.exp(-cost);
};

// ---------- First‑level pragmatic listener ----------
var pragmaticListener1 = function(u){
  // returns a map world→probability P(w | u)
  var priorW = 1 / worlds.length;
  var unnorm = {};
  var Z = 0;
  worlds.forEach(function(w){
    var sum = 0;
    scopes.forEach(function(s,i){
      scopes.forEach(function(q,j){
        var ps = scopePrior[i];
        var pq = qudPrior[j];
        sum += ps * pq * speaker1Weight(u, w, s, q);
      });
    });
    var val = priorW * sum;
    unnorm[w] = val;
    Z += val;
  });
  // normalise
  var result = {};
  worlds.forEach(function(w){
    result[w] = unnorm[w] / Z;
  });
  return result;   // map world → P
};

// ---------- Second‑level speaker ----------
var speaker2 = function(wTarget){
  var probs = [];
  utterances.forEach(function(u){
    var priorU = utterancePrior[utterances.indexOf(u)];
    var L1dist = pragmaticListener1(u);
    var pl1 = L1dist[wTarget];                     // P_L1(wTarget | u)
    var weight = priorU * Math.pow(pl1, alpha) * Math.exp(-cost);
    probs.push(weight);
  });
  // normalise to get a proper distribution over utterances
  var Z = probs.reduce(function(a,b){return a+b;},0);
  var norm = probs.map(function(p){return p/Z;});
  // sample according to this distribution (enumerate later)
  return categoricalDraw(utterances, norm);
};

// ---------- Model and inference ----------
var model = function(){
  var w = 2;               // the given world state: two rabbits fed
  return speaker2(w);
};

var ANSWER = Infer({method: 'enumerate'}, model);

