// Truth condition of an utterance given a state and scope
function truth(state, utter, scope) {
  if (utter === "null") {
    return true;
  } else if (utter === "none") {
    return state === 0;
  } else if (utter === "not-two") {
    if (scope === "surface") {
      return state < 2; // 0 or 1
    } else if (scope === "inverse") {
      return state === 0;
    }
  }
  return false;
}

// Literal listener's answer to a QUD given a state
function answer(q, state) {
  if (q === "how many?") return state;
  if (q === "all red?") return state === 2;
  if (q === "none red?") return state === 0;
  return null;
}

// Probability that literal listener returns the correct QUD answer
// for a given state, utterance, scope, and QUD
function probCorrect(state, utter, scope, q) {
  // Prior over states is uniform
  var prior = 1 / states.length;
  // Compute posterior over states given utterance
  var probs = states.map(function (s) {
    return truth(s, utter, scope) ? prior : 0;
  });
  var total = probs.reduce(function (a, b) { return a + b; }, 0);
  if (total === 0) return 0; // utterance impossible under this scope
  var norm = probs.map(function (p) { return p / total; });

  var targetAnswer = answer(q, state);
  var correctProb = 0;
  for (var i = 0; i < states.length; i++) {
    if (answer(q, states[i]) === targetAnswer) {
      correctProb += norm[i];
    }
  }
  return correctProb;
}

// Utility: probability that speaker level 1 will choose an utterance
// for a given true state (average over scope and QUD)
function speakProb(state, utter) {
  var total = 0;
  scopes.forEach(function (scope) {
    quds.forEach(function (q) {
      var pCorr = probCorrect(state, utter, scope, q);
      total += scopeProb[scope] * qudProb[q] * pCorr;
    });
  });
  return total; // proportional to probability (constant cancels in normalization)
}

