var states = [0,1,2,3,4];
var utterances = ["null","not-two","none"];
var scopes = ["surface","inverse"];
var quds = ["how many","all red","none red"];

// priors
var priorState = 1/states.length;          // uniform over 5 states
var priorScope = {surface:100/101, inverse:1/101};
var priorQud = 1/quds.length;              // uniform over 3 QUDs
var cost = 1;                              // uniform utterance cost
var alpha = 1;

// literal truth conditions
var truth = function(u,s,sc){
  if (u === "null") return true;
  if (u === "none") return s === 0;
  // u === "not-two"
  if (sc === "surface") return s < 2;
  else /* inverse */     return s < 3;
};

// QUD projection
var project = function(s,q){
  if (q === "how many") return s;
  if (q === "all red") return s === 4;
  if (q === "none red") return s === 0;
};

// log‑sum‑exp helper
var logSumExp = function(arr){
  var max = Math.max.apply(null,arr);
  var sum = 0;
  for (var i=0;i<arr.length;i++) sum += Math.exp(arr[i]-max);
  return max + Math.log(sum);
};

// literal listener: probability that it would return the *correct* QUD value
var literalCorrectProb = function(u,sc,q,target){
  var denom = 0, num = 0;
  states.forEach(function(s){
    var p = priorState;
    if (truth(u,s,sc)){
      denom += p;
      if (project(s,q) === target) num += p;
    }
  });
  return denom===0 ? 0 : num/denom;
};

// first‑level speaker distribution for a given world state
var S1dist = function(state){
  // utilities for each utterance (expected log prob under L0)
  var utils = utterances.map(function(u){
    var expCorrect = 0;
    scopes.forEach(function(sc){
      var psc = priorScope[sc];
      quds.forEach(function(q){
        var pq = priorQud;
        var target = project(state,q);
        var pcorr = literalCorrectProb(u,sc,q,target);
        expCorrect += psc * pq * pcorr;
      });
    });
    // utility = α·log(expectedCorrectProb) – cost
    return alpha*Math.log(expCorrect) - cost;
  });
  // turn utilities into a proper distribution (softmax)
  var logZ = logSumExp(utils);
  return utils.map(function(u){ return Math.exp(u-logZ); });
};

