// it weighs utterances by how likely the first‑level pragmatic listener
// would infer the true world state (here state = 2)
var model = function(){
  var trueState = 2;

  // P_S1(u | s) for every s (needed for the level‑1 listener)
  var S1all = states.map(function(s){ return S1dist(s); });

  // posterior of state = 2 after hearing utterance u
  var postState2 = utterances.map(function(uIdx){
    var ul = utterances[uIdx];
    // likelihood P_S1(u|2)
    var lik2 = S1all[2][uIdx];
    // normalising constant Σ_s P_S1(u|s)·P(s) ; P(s) uniform so just sum over s
    var norm = 0;
    states.forEach(function(s){ norm += S1all[s][uIdx]; });
    var post = lik2 / norm;          // α = 1 so log‑prob = log(post)
    return post;
  });

  // utilities for the level‑2 speaker
  var utils2 = postState2.map(function(p){ return alpha*Math.log(p) - cost; });
  var logZ2 = logSumExp(utils2);
  var probs2 = utils2.map(function(u){ return Math.exp(u - logZ2); });

  // sample an utterance according to this distribution
  return sample(Categorical({ps:probs2, vs:utterances}));
};

