var claim = function(u, price, expThresh, incThresh){
  if (u === "expensive")        return price > expThresh;
  if (u === "not-expensive")    return !(price > expThresh);
  if (u === "inexpensive")      return price < incThresh;
  if (u === "not-inexpensive")  return !(price < incThresh);
};

// Literal listener's log‐probability of observing a true noisy claim
var literalLogProb = function(price, u, expThresh, incThresh){
  var holds = claim(u, price, expThresh, incThresh);
  var prob = holds ? 0.9999 : 0.0001;
  return Math.log(prob);
};

