var speakerProb = function(u, price, expThresh, incThresh){
  var unnorm = utterances.map(function(uu){
    var lp = literalLogProb(price, uu, expThresh, incThresh);
    return Math.exp(2 * (lp - cost(uu))); // speaker optimality = 2
  });
  var z = unnorm.reduce(function(a,b){return a+b;},0);
  var probs = unnorm.map(function(v){ return v / z; });
  return probs[utterances.indexOf(u)];
};

