function claimHolds(utt, price, expThresh, inexpThresh) {
  if (utt === "expensive") return price > expThresh;
  if (utt === "not-expensive") return price <= expThresh;
  if (utt === "inexpensive") return price < inexpThresh;
  if (utt === "not-inexpensive") return price >= inexpThresh;
}

function truthTrueProb(utt, price, expThresh, inexpThresh) {
  return claimHolds(utt, price, expThresh, inexpThresh) ? 0.9999 : 0.0001;
}

function L0ProbTrue(price, expThresh, inexpThresh, utt) {
  var total = 0;
  var trueWeight = 0;
  for (var i = 0; i < values.length; i++) {
    var p = values[i];
    var w = truthTrueProb(utt, p, expThresh, inexpThresh);
    total += w;
    if (p === price) trueWeight = w;
  }
  return trueWeight / total;
}

function speakerProb(price, expThresh, inexpThresh, utt) {
  var weights = {};
  var sum = 0;
  for (var j = 0; j < utterances.length; j++) {
    var u = utterances[j];
    var l0 = L0ProbTrue(price, expThresh, inexpThresh, u);
    var w = Math.exp(2 * (Math.log(l0) - costs[u]));
    weights[u] = w;
    sum += w;
  }
  return weights[utt] / sum;
}

