    var price = sample(pricePriorDist);
    var spk = speakerProb(price, expThresh, inexpThresh, heardUtt);
    factor(Math.log(spk));
    return {expensiveThreshold: expThresh,
            inexpensiveThreshold: inexpThresh,
            price: price};
  });
}

