function truthProb(utterance, individual){
  var fruit=individual.fruit;
  var shirt=individual.shirt;
  var truth;
  if(utterance==="apples") truth = fruit==="apples";
  else if(utterance==="oranges") truth = fruit==="oranges";
  else if(utterance==="no apples") truth = fruit!=="apples";
  else if(utterance==="no oranges") truth = fruit!=="oranges";
  else if(utterance==="red shirt") truth = shirt==="red";
  else if(utterance==="blue shirt") truth = shirt==="blue";
  else if(utterance==="green shirt") truth = shirt==="green";
  else if(utterance==="yellow shirt") truth = shirt==="yellow";
  return truth? 0.999 : 0.001;
}

function answerToQuestion(individual, question){
  var fruit=individual.fruit;
  if(question==="apples_noapples"){
    return fruit==="apples" ? "yes":"no";
  }else{
    return fruit===null ? "none":fruit;
