}

function speakerProbNoApples(targetFruit, style, question){
  var probs=[];
  for(var size=0; size<=3; size++){
    var group=[];
    if(size===1){
      group.push({fruit:"apples", shirt:"red"});
    }else if(size===2){
      group.push({fruit:"apples", shirt:"red"});
      if(style==="A"){
        group.push({fruit:null, shirt:"blue"});
      }else{
        group.push({fruit:"oranges", shirt:"blue"});
      }
    }else if(size===3){
      group.push({fruit:"apples", shirt:"red"});
      if(style==="A"){
        group.push({fruit:null, shirt:"blue"});
        group.push({fruit:null, shirt:"green"});
      }else{
        group.push({fruit:"oranges", shirt:"blue"});
        group.push({fruit:"oranges", shirt:"green"});
      }
    }
    var target={fruit:targetFruit, shirt:"yellow"};
    var all=[target].concat(group);
    var targetAns=answerToQuestion(target, question);
    var weights = {};
    utterances.forEach(u=>{
      var pSurvive=truthProb(u,target);
      var numerator=0, denominator=0;
      all.forEach(ind=>{
        var ans=answerToQuestion(ind, question);
        var pTrue=truthProb(u,ind);
        denominator+=pTrue;
        if(ans===targetAns) numerator+=pTrue;
      });
      var fraction = numerator/denominator;
      var weight = baseP[u]*pSurvive*fraction;
      weights[u]=weight;
    });
    var total = Object.values(weights).reduce((a,b)=>a+b,0);
    probs.push(weights["no apples"] / total);
  }
  return probs;
}

