var noisyTruthValue = function(utterance, individual) {
  var trueValue = function() {
    if (utterance.startsWith("no")) {
      return !questions["apples/no-apples"](individual) || individual.fruit !== utterance.substring(3);
    } else if (utterance in questions) {
      return questions[utterance](individual);
    } else {
