  var trueIndividuals = individuals.filter(function(individual) {
    return noisyTruthValue(utterance, individual) > 0.5;
  });
  var answers = trueIndividuals.map(function(individual) {
    if (question === "apples/no-apples") {
      return questions[question](individual);
    } else {
      return questions[question](individual);
    }
  });
  return answers;
};

