var speaker = function(target, comparisonGroup, question) {
  var individuals = comparisonGroup.concat([target]);
  var utterancePrior = Object.keys(utterances).map(function(utterance) {
    return Math.exp(-utterances[utterance]);
  });
  var utteranceWeights = utterancePrior.map(function(prior, index) {
    var utterance = Object.keys(utterances)[index];
    var trueValue = noisyTruthValue(utterance, target);
    var listenerProbability = literalListener(utterance, question, individuals).filter(function(answer) {
      if (question === "apples/no-apples") {
        return answer === questions[question](target);
      } else {
        return answer === questions[question](target);
      }
    }).length / literalListener(utterance, question, individuals).length;
    return prior * Math.exp(trueValue * listenerProbability);
  });
  return utteranceWeights.reduce(function(acc, weight, index) {
    var utterance = Object.keys(utterances)[index];
    acc[utterance] = weight;
    return acc;
  }, {});
};

