// Speaker
var speaker = function(target, comparisonGroup, question) {
  var individuals = [target].concat(comparisonGroup);
  var utterance = sample(utterancePrior());
  // Check truth of utterance on target
  condition(isTrue(utterance, target, question));
  // Rationality: weight by listener's probability of target's answer
  var targetAnswer = (question === "apples_qud") ? 
                      (target.fruit === "apples" ? "yes" : "no") : 
                      target.fruit;
  var listenerDist = Infer({method: 'enumerate'}, function() {
    return literalListener(utterance, question, individuals);
  });
  var listenerProb = Math.max(0.001, Math.min(0.999, 
                              Math.exp(listenerDist.score(targetAnswer))));
  factor(1 * Math.log(listenerProb)); // rationality = 1
  return utterance;
};

