  if (u === "no apples") return {property: "fruit", value: "apples", negated: true};
  if (u === "no oranges") return {property: "fruit", value: "oranges", negated: true};
  if (u === "red shirt") return {property: "shirt", value: "red", negated: false};
  if (u === "blue shirt") return {property: "shirt", value: "blue", negated: false};
  if (u === "green shirt") return {property: "shirt", value: "green", negated: false};
