var satisfiesClaim = function(ind, utt) {
  if (utt === "apples")      return ind.fruit === "apples";
  if (utt === "oranges")     return ind.fruit === "oranges";
  if (utt === "no apples")   return ind.fruit !== "apples";
  if (utt === "no oranges")  return ind.fruit !== "oranges";
