  var total = comp[0] + comp[1] + comp[2];
  if (total > thr) return 0.99;
  if (total < thr) return 0.01;
  // total == thr
  return 0.5; // Φ(0) = 0.5
}

// compute sum over all compositions of the weight function w for a given rule
function sumWDistributive(thr){
  var sum = 0;
  allComps.forEach(function(comp){
    sum += wDistributive(comp, thr);
  });
  return sum;
}
function sumWCollective(thr){
  var sum = 0;
  allComps.forEach(function(comp){
    sum += wCollective(comp, thr);
  });
  return sum;
}

// model enumerating all latent variables
var model = function(){
