  var s3 = uniformDraw(sizes);
  var trueComp = [s1,s2,s3];

  // thresholds
  var distThresh = uniformDraw(distThreshVals);
  var collThresh = uniformDraw(collThreshVals);

  // which rule applies to the ambiguous description
  var isCollective = flip(0.8); // true = collective, false = distributive

  // ----- compute weights for each description -----
  // vacuous
  var wTrueVac = 1;
  var sumWVac = 27; // all comps weight 1

  // unambiguous distributive
  var wTrueUnDist = wDistributive(trueComp, distThresh);
  var sumWUnDist = sumWDistributive(distThresh);

  // unambiguous collective
  var wTrueUnColl = wCollective(trueComp, collThresh);
  var sumWUnColl = sumWCollective(collThresh);

  // ambiguous (depends on rule)
  var wTrueAmb = isCollective ? wTrueUnColl : wTrueUnDist;
  var sumWAmb = isCollective ? sumWUnColl : sumWUnDist;

  // probability that the reasoner would produce each description
  var probVac  = weight.vac * wTrueVac   / sumWVac;
  var probUnDist = weight.unDist * wTrueUnDist / sumWUnDist;
  var probUnColl = weight.unColl * wTrueUnColl / sumWUnColl;
  var probAmb  = weight.amb * wTrueAmb   / sumWAmb;

  var total = probVac + probUnDist + probUnColl + probAmb;
  var probAmbNorm = probAmb / total; // reasoner’s probability of the ambiguous description

  // ----- informativity weighting (power 10) -----
  // factor adds log-weight
  factor(10 * Math.log(probAmbNorm));

  // return the rule that applies to the ambiguous description
  return isCollective ? 'collective' : 'distributive';
};

