// Probability of a composition under distributive rule
function probDis(comp, dThresh) {
  return (comp[0] >= dThresh && comp[1] >= dThresh && comp[2] >= dThresh) ? 0.99 : 0.01;
}

// Probability of a composition under collective rule
function probCollect(comp, cThresh) {
  var total = comp[0] + comp[1] + comp[2];
  // With noise=0.01 the comparison is nearly deterministic; use 0.99/0.01 rule
  return (total >= cThresh) ? 0.99 : 0.01;
}

// Model producing the posterior over the rule for the ambiguous description
function model() {
  // Object sizes
  var s1 = sample( categorical({cats:[2,3,4], probs:[1/3,1/3,1/3]}) );
  var s2 = sample( categorical({cats:[2,3,4], probs:[1/3,1/3,1/3]}) );
  var s3 = sample( categorical({cats:[2,3,4], probs:[1/3,1/3,1/3]}) );
  var trueComp = [s1,s2,s3];

  // Applicable rule for ambiguous description
  var rule = sample( categorical({cats:["collective","distributive"], probs:[0.8,0.2]}) );

  // Thresholds
  var dThresh = sample( categorical({cats:[2,3,4], probs:[1/3,1/3,1/3]}) );
  var cThresh = sample( randomInteger(2,12) ); // inclusive

  // Prior weights for descriptions
  var wV = 3;
  var wA = 2;
  var wD = 1;
  var wC = 1;

  // Compute probability weights
  function computeWeight(desc) {
    var pTrue, Z;
    if (desc === "vacuous") {
      pTrue = 1;
      Z = 27;
    } else if (desc === "distributive") {
      pTrue = probDis(trueComp, dThresh);
      Z = combos.reduce(function(sum, comp){ return sum + probDis(comp, dThresh); },0);
    } else if (desc === "collective") {
      pTrue = probCollect(trueComp, cThresh);
      Z = combos.reduce(function(sum, comp){ return sum + probCollect(comp, cThresh); },0);
    } else if (desc === "ambiguous") {
      if (rule === "collective") {
        pTrue = probCollect(trueComp, cThresh);
        Z = combos.reduce(function(sum, comp){ return sum + probCollect(comp, cThresh); },0);
      } else {
        pTrue = probDis(trueComp, dThresh);
        Z = combos.reduce(function(sum, comp){ return sum + probDis(comp, dThresh); },0);
      }
    }
    var w = (desc==="vacuous")? wV : (desc==="distributive")? wD : (desc==="collective")? wC : wA;
    return w * (pTrue / Z);
  }

  var weightV = computeWeight("vacuous");
  var weightA = computeWeight("ambiguous");
  var weightD = computeWeight("distributive");
  var weightC = computeWeight("collective");

  var totalWeight = weightV + weightA + weightD + weightC;
  var reasonerProb = weightA / totalWeight;

  // Weight the scenario by the probability of producing the observed description,
  // raised to the informativity parameter (10)
  factor( 10 * Math.log(reasonerProb) );

  return rule;  // we want posterior over the rule for the ambiguous description
}

