// Check distributive rule
var checkDistributive = function(group, threshold) {
  return group.every(function(s) { return s >= threshold; });
};

// Check collective rule (with Gaussian smoothing)
var checkCollective = function(group, threshold) {
  var total = group.reduce(function(a, b) { return a + b; }, 0);
  var z = (total - threshold) / 0.01;
  var prob = Phi(z);
  if (prob === 0) prob = 0.01;
  if (prob === 1) prob = 0.99;
  return flip(prob);
};

// Build judge's belief: samples where description is true, normalized
var getJudgeBelief = function(isTrueFunc, numSamples) {
  var trueSamples = [];
  repeat(numSamples, function() {
    var group = randomGroup();
    if (isTrueFunc(group)) {
      trueSamples.push(group);
    }
  });

  if (trueSamples.length === 0) {
    return null; // No support
  }

  return trueSamples;
};

// KL divergence from point mass at trueGroup to distribution of judge samples
var computeKL = function(trueGroup, judgeSamples) {
  if (judgeSamples === null || judgeSamples.length === 0) {
    return Infinity;
  }

  // Find probability that judge assigns to trueGroup
  var matchCount = 0;
  for (var i = 0; i < judgeSamples.length; i++) {
    if (judgeSamples[i].every(function(x, idx) { return x === trueGroup[idx]; })) {
      matchCount++;
    }
  }

  var judgeProb = matchCount / judgeSamples.length;

  if (judgeProb === 0) {
    return Infinity;
  }

  // KL(point mass at trueGroup || judge distribution)
  // = log(1) - log(judgeProb) = -log(judgeProb)
  return -Math.log(judgeProb);
};

var model = function() {
  // Sample scenario components
  var object_sizes = [uniformDraw(sizes), uniformDraw(sizes), uniformDraw(sizes)];
  var isCollective = flip(0.8);
  var distThreshold = uniformDraw(distThresholds);
  var collThreshold = uniformDraw(collThresholds);

  // Define truth functions for each description
  var vacuousIsTrue = function(group) { return true; };

  var distributiveIsTrue = function(group) { 
    return checkDistributive(group, distThreshold); 
  };

  var collectiveIsTrue = function(group) { 
    return checkCollective(group, collThreshold); 
  };

  var ambiguousIsTrue = isCollective ? collectiveIsTrue : distributiveIsTrue;

  // Get judge's beliefs (samples where each description is true)
  var numSamples = 500;
  var vacuousJudge = getJudgeBelief(vacuousIsTrue, numSamples);
  var distributiveJudge = getJudgeBelief(distributiveIsTrue, numSamples);
  var collectiveJudge = getJudgeBelief(collectiveIsTrue, numSamples);
  var ambiguousJudge = getJudgeBelief(ambiguousIsTrue, numSamples);

  // Compute KL divergences
  var klVacuous = computeKL(object_sizes, vacuousJudge);
  var klDistributive = computeKL(object_sizes, distributiveJudge);
  var klCollective = computeKL(object_sizes, collectiveJudge);
  var klAmbiguous = computeKL(object_sizes, ambiguousJudge);

  // Compute unnormalized weights for each description
  var weights = [
    3 * Math.exp(-klVacuous),
    2 * Math.exp(-klAmbiguous),
    1 * Math.exp(-klDistributive),
    1 * Math.exp(-klCollective)
  ];

  var normalizingConstant = weights.reduce(function(a, b) { return a + b; }, 0);
  var probAmbiguous = weights[1] / normalizingConstant;

  // Condition on ambiguous description being produced
  // Weight by (probAmbiguous)^10
  factor(10 * Math.log(probAmbiguous));

  return isCollective;
};

