// Standard normal CDF (Abramowitz & Stegun 26.2.17)
var Phi = function(x) {
  if (x < 0) {
    return 1 - Phi(-x);
  }
  var p = 0.2316419;
  var t = 1 / (1 + p * x);
  var b1 = 0.319381530, b2 = -0.356563782, b3 = 1.781477937,
      b4 = -1.821255978, b5 = 1.330274429;
  var pdf = Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI);
  var poly = b1 * t + b2 * Math.pow(t, 2) + b3 * Math.pow(t, 3) +
             b4 * Math.pow(t, 4) + b5 * Math.pow(t, 5);
  return 1 - pdf * poly;
};

