var truthProb = function(desc, state, rule, dT, cT) {
  var effective = (desc === 'ambiguous')
        ? (rule === 'collective' ? 'collective' : 'distributive')
        : desc;
  if (effective === 'vacuous') {
    return 1;
  }
  if (effective === 'distributive') {
    return all(function(s) { return s >= dT; }, state) ? 0.99 : 0.01;
  }
  var total = sum(state);
  var z = (total - cT) / noise;
  var pr = Phi(z);
  if (pr === 0) { return 0.01; }
  if (pr === 1) { return 0.99; }
  return pr;
};

// literal judge's belief (renormalized over group compositions where desc is true)
var litProb = function(desc, state, rule, dT, cT) {
  var ws = map(function(s) { return truthProb(desc, s, rule, dT, cT); }, allStates);
  var denom = sum(ws);
  return truthProb(desc, state, rule, dT, cT) / denom;
};

