  var Phi = function(z) {
    return 0.5 * (1 + Math.erf(z / Math.sqrt(2)));
  };

  // Function to judge truth of unambiguous distributive description
  var isDistributiveTrue = function(sizes, threshold) {
    return all(function(s) { return s >= threshold; }, sizes) ? 0.99 : 0.01;
  };

  // Function to judge truth of unambiguous collective description
  var isCollectiveTrue = function(totalSize, threshold, noise) {
    var z = (totalSize - threshold) / noise;
    var p = Phi(z);
    // Clamp to avoid 0 or 1
    if (p < 1e-9) p = 0.01;
    if (p > 1 - 1e-9) p = 0.99;
    return p;
  };

  // Function to sample group compositions consistent with a description being true
  // under given thresholds and rule (for ambiguous, we pass which rule applies)
  var sampleGroupGivenDescription = function(description, distributiveThreshold, collectiveThreshold, ruleIsCollective) {
    return function() {
      var s1 = uniformDraw([2, 3, 4]);
      var s2 = uniformDraw([2, 3, 4]);
      var s3 = uniformDraw([2, 3, 4]);
      var ts = s1 + s2 + s3;
      var sizes = [s1, s2, s3];

      var probTrue = 0;
      if (description === 'vacuous') {
        probTrue = 1.0;
      } else if (description === 'ambiguous') {
        if (ruleIsCollective) {
          probTrue = isCollectiveTrue(ts, collectiveThreshold, noiseScale);
        } else {
          probTrue = isDistributiveTrue(sizes, distributiveThreshold);
        }
      } else if (description === 'unambiguous_distributive') {
        probTrue = isDistributiveTrue(sizes, distributiveThreshold);
      } else if (description === 'unambiguous_collective') {
        probTrue = isCollectiveTrue(ts, collectiveThreshold, noiseScale);
      }

      // Use factor to condition on the description being true with probability probTrue
      factor(Math.log(probTrue));
