  var judgeAmbiguous = getJudgeBelief('ambiguous');
  var judgeUnambigDist = getJudgeBelief('unambiguous_distributive');
  var judgeUnambigColl = getJudgeBelief('unambiguous_collective');

  // Reasoner's belief: certain about the true sizes
  var reasonerBelief = Enumerate(function() { return sizes; });

  // Compute KL divergence from reasoner belief to judge belief
  var klDivergence = function(pDist, qDist) {
    // p is reasoner (true), q is judge
    var pSupport = pDist.support();
    var kl = 0;
    map(function(val) {
      var p = Math.max(pDist.score(val), -100); // avoid -Inf
      p = Math.exp(p);
      var q = Math.max(qDist.score(val), -100);
      q = Math.exp(q);
      // If p is 0, skip (0 log 0 = 0)
      if (p > 1e-9) {
