    return kl;
  };

  // Prior weights for descriptions
  var priorWeights = {
    vacuous: 3,
    ambiguous: 2,
    unambiguous_distributive: 1,
    unambiguous_collective: 1
  };

  // Compute production probability for each description
  var informativityWeight = 10;

  var getProductionProb = function(desc, judgeDist) {
    var kl = klDivergence(reasonerBelief, judgeDist);
    var utility = -kl;
    var weight = priorWeights[desc];
    return weight * Math.exp(utility);
