  Z += getProductionProb('ambiguous', judgeAmbiguous);
  Z += getProductionProb('unambiguous_distributive', judgeUnambigDist);
  Z += getProductionProb('unambiguous_collective', judgeUnambigColl);

  // Probability of producing the ambiguous description in this scenario
  var probAmbiguous = getProductionProb('ambiguous', judgeAmbiguous) / Z;

  // Informativity weighting: reweight scenario by probAmbiguous^informativityWeight
  factor(informativityWeight * Math.log(probAmbiguous));

  // Return whether the rule for ambiguous is collective
  return ruleIsCollective;
};

