  var s1 = uniformDraw(sizeVals);
  var s2 = uniformDraw(sizeVals);
  var s3 = uniformDraw(sizeVals);
  var trueSizes = [s1, s2, s3];

  var applicableRule = flip(0.8) ? 'collective' : 'distributive';
  var dThresh = uniformDraw(sizeVals);
  var cThresh = uniformDraw(collThreshVals);

  // For each description, compute literal judge's probability of trueSizes
  var literalJudgeProb = function(desc) {
    var weights = map(function(comp) {
      return descTrueProb(desc, comp, dThresh, cThresh, applicableRule);
    }, allCompositions);
    var totalW = sum(weights);
    if (totalW === 0) return 0;
    var myW = descTrueProb(desc, trueSizes, dThresh, cThresh, applicableRule);
    return myW / totalW;
  };

  // Reasoner's unnormalized score for each description
  var unnormScores = map(function(desc) {
    var ljp = literalJudgeProb(desc);
    return descWeights[desc] * ljp;
  }, descriptions);

  var totalScore = sum(unnormScores);
  var reasonerProbs = map(function(w) { return w / totalScore; }, unnormScores);

  // Index of 'ambiguous' in descriptions array
  var pAmbig = reasonerProbs[1]; // descriptions[1] === 'ambiguous'

  // Weight scenario by pAmbig^informativity
  factor(informativity * Math.log(pAmbig));

  return applicableRule === 'collective';
};

