// ----- Helper functions -----
function priorWeight(utt) {
  return Math.exp( -(utt.negated ? 2 : 1) );
}

function literalStats(utt) {
  var key = utt.word + (utt.negated ? "_negated" : "_direct");
  var probs = table[key];
  var sum = probs.reduce(function(a,b){return a+b;},0);
  var norm = probs.map(function(p){return p / sum;});
  var expected = norm.reduce(function(acc,p,i){return acc + (i+1)*p;},0);
  return {norm: norm, expected: expected};
}

// probability that a first‑speaker would emit `utt` given rating & weight
function firstSpeakerScore(utt, rating, weight) {
  var stats = literalStats(utt);
  var logProbTrue = Math.log(stats.norm[rating-1]);   // rating is 1‑indexed
  var expected = stats.expected;
  return priorWeight(utt) *
         Math.exp( opt1 * ( weight*logProbTrue + (1-weight)*expected ) );
}

// ----- First listener (enumerated) -----
function firstListenerDist(utt) {
  return Infer({method: 'enumerate'}, function(){
    var rating = uniformDraw([1,2,3,4,5]);
    var w = uniformDraw(weightVals);
    factor( Math.log( firstSpeakerScore(utt, rating, w) ) );
    return {rating: rating, weight: w};
  });
}

// ----- Second speaker (enumerated) -----
function secondSpeakerDist(intendedWeight) {
  return Infer({method: 'enumerate'}, function(){
    // compute unnormalised weight for each utterance
    var unnorm = utterances.map(function(utt){
      var flDist = firstListenerDist(utt);
      var p = flDist.score({rating: trueRating, weight: intendedWeight});
      if (p === 0) return 0;
      // priorWeight already inside firstSpeakerScore, but we need it again here:
      // the second‑speaker utility uses priorWeight * p^{opt2}
      return priorWeight(utt) * Math.pow(p, opt2);
    });
    var idx = categorical(unnorm);
    var chosen = utterances[idx];
    return chosen.negated ? "negation" : "direct";
  });
}

