// Literal listener: posterior prob of rating given utterance
function literalListenerProb(uIdx,r) {
  var probs = utterances[uIdx].truth;
  var denom = probs.reduce((a,b)=>a+b,0);
  return probs[r-1]/denom;
}

// Expected rating for a given utterance according to literal listener
function expectedRating(uIdx) {
  var probs = utterances[uIdx].truth;
  var denom = probs.reduce((a,b)=>a+b,0);
  var sum = 0;
  for(var r=1;r<=5;r++){
    sum += r * probs[r-1]/denom;
  }
  return sum;
}

// First speaker: probability of utterance given rating and weight
function firstSpeakerDist(r,w) {
  var utilities = [];
  var weights = [];
  for(var u=0;u<10;u++){
    var litProb = literalListenerProb(u,r);
    var expR = expectedRating(u);
    var util = w*Math.log(litProb) + (1-w)*expR;
    var wght = prior[u] * Math.exp(optSpeaker*util);
    utilities.push(util);
    weights.push(wght);
  }
  var total = weights.reduce((a,b)=>a+b,0);
  return weights.map(wgt => wgt/total);
}

function speakerProb(u,r,w) {
  var dist = firstSpeakerDist(r,w);
  return dist[u];
}

// Second speaker: given intended weight wInt, compute distribution over neg/direct
function getDistForWeight(wInt) {
  var probsU = [];
  // Precompute denom (sum over r,w of speakerProb(u,r,w))
  var denomU = [];
  for(var u=0;u<10;u++){
    var sum = 0;
    for(var r=1;r<=5;r++){
      for(var wx of weightVals){
        sum += speakerProb(u,r,wx);
      }
    }
    denomU[u] = sum;
  }
  // Compute posterior of interest and mass
  var mass = [];
  for(var u=0;u<10;u++){
    var num = speakerProb(u,1,wInt);
    var post = num/denomU[u];
    // weight by exp(optSecond * ln(post)) = post^optSecond
    mass[u] = Math.pow(post,optSecond);
  }
  // Normalize mass
  var totalMass = mass.reduce((a,b)=>a+b,0);
  var normMass = mass.map(m=>m/totalMass);
  // Sum over direct (0-4) and negated (5-9)
  var pDirect = 0, pNeg = 0;
  for(var u=0;u<10;u++){
    if(u<5) pDirect += normMass[u];
    else    pNeg    += normMass[u];
  }
  // Return distribution over 'direct' and 'negation'
  return new Categorical({negation:pNeg, direct:pDirect});
}

