var slotValues = [0.1,0.3,0.5,0.7,0.9];
var thetaVals  = [0.4,0.5,0.6,0.7,0.8,0.9,1.0];

// all non‑empty world states (31 of them)
var allStates = [];
for (var i = 1; i < 32; i++) { // skip 0 (no slots true)
  var s = {};
  for (var j = 0; j < 5; j++) {
    s['slot' + (j+1)] = !!(i & (1 << j));
  }
  allStates.push(s);
}

// all valid (theta_R,theta_T) pairs (28 of them)
var allPairs = [];
for (var a = 0; a < thetaVals.length; a++) {
  for (var b = a; b < thetaVals.length; b++) {
    allPairs.push([thetaVals[a], thetaVals[b]]);
  }
}

// --- Coverage condition ---
function satisfies(state, theta) {
  var half = theta/2;
  var first = false, second = false;
  for (var i = 0; i < 5; i++) {
    if (!state['slot' + (i+1)]) continue;
    var v = slotValues[i];
    if (v > 0 && v <= half)      first  = true;
    else if (v > half && v <= theta) second = true;
  }
  return first && second;
}

// pre‑compute how many states satisfy the progressive / imperfective condition for each theta
var satCount = {}; // key = theta, value = number of satisfying states
thetaVals.forEach(function(theta){
  var cnt = 0;
  allStates.forEach(function(st){ if (satisfies(st,theta)) cnt++; });
  satCount[theta] = cnt;
});

// --- Speaker model ---
var costProg = 5, costImp = 1, costNull = 100;
var priorRaw = {
  progressive: Math.exp(-costProg),
  imperfective: Math.exp(-costImp),
  null: Math.exp(-costNull)
};
var Z = priorRaw.progressive + priorRaw.imperfective + priorRaw.null;
var prior = {
  progressive:   priorRaw.progressive   / Z,
  imperfective: priorRaw.imperfective / Z,
  null:          priorRaw.null          / Z
};

function literalProb(state, utter, thetaR, thetaT) {
  if (utter === 'progressive') {
    if (!satisfies(state, thetaR)) return 0;
    return 1 / satCount[thetaR];
  } else if (utter === 'imperfective') {
    if (!satisfies(state, thetaT)) return 0;
    return 1 / satCount[thetaT];
  } else { // null
    return 1 / allStates.length; // uniform over all 31 states
  }
}

// probability that a speaker would emit "progressive" given state & thresholds
function speakerProbProg(state, thetaR, thetaT) {
  var lpProg = literalProb(state,'progressive',thetaR,thetaT);
  var lpImp  = literalProb(state,'imperfective',thetaR,thetaT);
  var lpNull = literalProb(state,'null',thetaR,thetaT);
  var num = prior.progressive * lpProg;
  var den = prior.progressive * lpProg + prior.imperfective * lpImp + prior.null * lpNull;
  return num / den;
}

