// Literal listener: P_L(state | utt, thetaR, thetaT)
// Returns a map from state index to probability
var literalListenerProbs = function(utt, thetaR, thetaT) {
  var weights = _.map(allStates, function(s) {
    return uttMeaning(utt, s, thetaR, thetaT) ? 1 : 0;
  });
  var total = _.sum(weights);
  return _.map(weights, function(w) { return total > 0 ? w / total : 0; });
};

// Speaker: P_S(utt | state, thetaR, thetaT) with alpha=1
// Returns unnormalized weights for each utterance
var speakerWeights = function(stateIdx, thetaR, thetaT) {
  return _.map(utterances, function(utt, ui) {
    var llProbs = literalListenerProbs(utt, thetaR, thetaT);
    var probOfState = llProbs[stateIdx];
    // weight = exp(-cost) * probOfState^1
    return uttPriorWeights[ui] * probOfState;
  });
};

// Pragmatic listener: observe "progressive"
// Joint distribution over (state, thetaR, thetaT)
var pragmaticListenerDist = Infer({method: 'enumerate'}, function() {
  // Draw state uniformly from 31 states
  var stateIdx = randomInteger(31);
  var state = allStates[stateIdx];

  // Draw threshold pair uniformly from 28 pairs
  var pairIdx = randomInteger(28);
  var pair = thetaPairs[pairIdx];
  var thetaR = pair.thetaR;
  var thetaT = pair.thetaT;

  // Compute speaker probability of "progressive" (utt index 0)
  var sw = speakerWeights(stateIdx, thetaR, thetaT);
  var swTotal = _.sum(sw);
  var probProg = swTotal > 0 ? sw[0] / swTotal : 0;

  // Reweight by speaker probability of observed utterance
  factor(Math.log(probProg + 1e-300));

  return {state: state, thetaR: thetaR, thetaT: thetaT};
});

// Marginal over state
var stateDist = Infer({method: 'enumerate'}, function() {
  var sample = sample(pragmaticListenerDist);
  return sample.state;
});

// Marginal over thetaR
var thetaRDist = Infer({method: 'enumerate'}, function() {
  var s = sample(pragmaticListenerDist);
  return s.thetaR;
});

// Marginal over thetaT
var thetaTDist = Infer({method: 'enumerate'}, function() {
  var s = sample(pragmaticListenerDist);
  return s.thetaT;
});

var ANSWER = {
  state: stateDist,
  thetaR: thetaRDist,
  thetaT: thetaTDist
};

// --- constants ---
var roles = ["Source","Goal","Other"];
var rolePrior = {Source: 1/3, Goal: 1/3, Other: 1/3};

var readingPrior = {Source: 0.1, Goal: 0.9};

var qudDists = {
  why:       {Source: 0.82, Goal: 0.17, Other: 0.01},
  whatNext:  {Source: 0.33, Goal: 0.66, Other: 0.01},
  who:       {Source: 1/3,  Goal: 1/3,  Other: 1/3}
};

var OPT = 2.5; // speaker optimality

// --- helper functions ---
var avgQUDProb = function(qudDist){
  return (qudDist.Source + qudDist.Goal + qudDist.Other) / 3.0;
};

// probability that the literal listener judges the QUD‑match as true
var literalProbTrue = function(utterance, reading, qudDist){
  if (utterance === "null") {
    return avgQUDProb(qudDist);
  } else { // "he"
    // the literal listener knows the referent = reading role
    return qudDist[reading];
  }
};

// speaker's probability of producing the utterance "he"
var speakerProbHe = function(reading, referent, qudDist){
  // --- probabilities for the literal listener ---
  var probTrueHe   = literalProbTrue("he",   reading, qudDist);
  var probTrueNull = literalProbTrue("null", reading, qudDist);

  // --- weight for each utterance (expectation over the speaker's own QUD‑match draw) ---
  var weightHe = 
        qudDist[referent]          * Math.pow(probTrueHe,   OPT) +
      (1 - qudDist[referent])      * Math.pow(1 - probTrueHe, OPT);

  var weightNull = 
        qudDist[referent]          * Math.pow(probTrueNull,   OPT) +
      (1 - qudDist[referent])      * Math.pow(1 - probTrueNull, OPT);

  // --- normalise ---
  return weightHe / (weightHe + weightNull);
};

// pragmatic listener model for a given QUD
var pragmaticListener = function(qudDist){
  return function(){
    // sample referent from its prior
    var referent = categorical({ps: [rolePrior.Source, rolePrior.Goal, rolePrior.Other],
                               vs: roles});

    // sample reading from its prior
    var reading = categorical({ps: [readingPrior.Source, readingPrior.Goal],
                               vs: ["Source","Goal"]});

    // likelihood that the speaker would have said "he"
    var utterLikelihood = speakerProbHe(reading, referent, qudDist);

    factor(Math.log(utterLikelihood)); // condition on hearing "he"

    return referent;
  };
};

// --- infer posteriors for each QUD ---
var whyPosterior      = Infer({method:"enumerate"}, pragmaticListener(qudDists.why));
var whatNextPosterior = Infer({method:"enumerate"}, pragmaticListener(qudDists.whatNext));
var whoPosterior      = Infer({method:"enumerate"}, pragmaticListener(qudDists.who));

// final answer object
var ANSWER = {
  whyQUD: whyPosterior,
  whatNextQUD: whatNextPosterior,
  whoQUD: whoPosterior
};

// Priors over referent and reading
var refPrior   = Categorical({Source:1/3, Goal:1/3, Other:1/3});
var readPrior  = Categorical({Source:0.1, Goal:0.9});
var lambda     = 2.5;

// QUD-specific probability distributions over referent
var QUDs = {
  why:      {Source:0.82, Goal:0.17, Other:0.01},
  whatNext: {Source:0.33, Goal:0.66, Other:0.01},
  who:      {Source:1/3,  Goal:1/3,  Other:1/3}
};

// Utility: probability that a literal listener outputs j (true/false)
// given utterance, reading, and QUD.
function listenerOutputProb(j, utter, read, QUD) {
  // Posterior over referent given utterance and reading
  var post = {};
  if (utter === 'he') {
    if (read === 'Source') { post.Source = 1; }
    else if (read === 'Goal') { post.Goal = 1; }
  } else { // null utterance
    post.Source = 1/3;
    post.Goal   = 1/3;
    post.Other  = 1/3;
  }
  // Compute probability of output j
  var sum = 0;
  for (var r in post) {
    var priorProb = post[r];
    var q = QUD[r];
    var outProb = j ? q : 1 - q;
    sum += priorProb * outProb;
  }
  return sum;
}

// Speaker probability of producing the observed utterance given referent, reading, QUD
function speakerProb(ref, read, QUD, utter) {
  var qTrue = QUD[ref]; // probability that the random match j is true
  var jTrue = function(j) {
    // weights for each utterance given j
    var wHe   = Math.pow(listenerOutputProb(j, 'he',   read, QUD), lambda);
    var wNull = Math.pow(listenerOutputProb(j, 'null', read, QUD), lambda);
    var total = wHe + wNull;
    var probU = (utter === 'he') ? wHe / total : wNull / total;
    return probU;
  };
  var prob = qTrue * jTrue(true) + (1 - qTrue) * jTrue(false);
  return prob;
}

// Pragmatic listener: posterior over referent given observed utterance 'he' for each QUD
function getPosterior(QUDkey) {
  var QUD = QUDs[QUDkey];
  return Infer({method:'enumerate'}, function(){
    var ref  = sample(refPrior);
    var read = sample(readPrior);
    var sProb = speakerProb(ref, read, QUD, 'he');
    factor(Math.log(sProb));
    return ref;
  });
}

var why        = getPosterior('why');
var whatNext   = getPosterior('whatNext');
var who        = getPosterior('who');

var ANSWER = {
  whyQUD: why,
  whatNextQUD: whatNext,
  whoQUD: who
};

// Referent prior
var referentPrior = function() {
  return uniformDraw(["Source", "Goal", "Other"]);
};

// Reading prior
var readingPrior = function() {
  return flip(0.1) ? "Source" : "Goal";
};

// QUD distributions
var qudsDistribution = {
  "Why?": function() { 
    return categorical({vs: ["Source", "Goal", "Other"], ps: [0.82, 0.17, 0.01]});
  },
  "What-next?": function() {
    return categorical({vs: ["Source", "Goal", "Other"], ps: [0.33, 0.66, 0.01]});
  },
  "Who?": function() {
    return uniformDraw(["Source", "Goal", "Other"]);
  }
};

// Check if utterance is true under given reading
var utteranceTrue = function(utterance, referent, reading) {
  if (utterance === "null") return true;
  if (utterance === "he") {
    if (reading === "Source") return referent === "Source";
    if (reading === "Goal") return referent === "Goal";
  }
  return false;
};

// Check if referent answers QUD
var answersQUD = function(referent, qud) {
  var drawn = qudsDistribution[qud]();
  return drawn === referent;
};

// Literal listener: given utterance, reading, and QUD
var literalListener = function(utterance, reading, qud) {
  return Infer({method: "enumerate"}, function() {
    var referent = referentPrior();
    condition(utteranceTrue(utterance, referent, reading));
    var answers = answersQUD(referent, qud);
    return {referent: referent, answers: answers};
  });
};

// Speaker: given true reading, true referent, and QUD
var speaker = function(trueReading, trueReferent, qud) {
  var alpha = 2.5;

  var utteranceScore = function(utterance) {
    // Draw fresh QUD-match judgment for true referent
    var speakerJudgment = answersQUD(trueReferent, qud);

    // Get literal listener's distribution for this utterance and reading
    var ll = literalListener(utterance, trueReading, qud);

    // Score how likely LL would produce same judgment as speaker
    var score = ll.score({referent: trueReferent, answers: speakerJudgment});

    return alpha * score;
  };

  return Infer({method: "enumerate"}, function() {
    var utterance = uniformDraw(["he", "null"]);
    factor(utteranceScore(utterance));
    return utterance;
  });
};

// Pragmatic listener: observes "he" utterance
var pragmaticListener = function(qud) {
  return Infer({method: "enumerate"}, function() {
    var referent = referentPrior();
    var reading = readingPrior();

    // Compute probability speaker would produce "he"
    var speakerDist = speaker(reading, referent, qud);
    observe(speakerDist, "he");

    return referent;
  });
};

var ANSWER = {
  whyQUD: pragmaticListener("Why?"),
  whatNextQUD: pragmaticListener("What-next?"),
  whoQUD: pragmaticListener("Who?")
};

// Define the prior distributions
var referentPrior = categorical(['Source', 'Goal', 'Other'], [1/3, 1/3, 1/3]);
var readingPrior = categorical(['Source', 'Goal'], [0.1, 0.9]);
var utterancePrior = categorical(['he', 'null'], [0.5, 0.5]);

// Define the distributions for QUD
var whyQUD = categorical(['Source', 'Goal', 'Other'], [0.82, 0.17, 0.01]);
var whatNextQUD = categorical(['Source', 'Goal', 'Other'], [0.33, 0.66, 0.01]);
var whoQUD = categorical(['Source', 'Goal', 'Other'], [1/3, 1/3, 1/3]);

// Define the speaker's rationality parameter
var alpha = 2.5;

// Define the literal listener's model
function literalListener(utterance, reading, QUD) {
  var referent = sample(referentPrior);
  var judgment = sample(QUD);

  // Condition on the utterance being true of the referent under the given reading
  var likelihood = (utterance === 'he' && 
                    ((reading === 'Source' && referent === 'Source') || 
                     (reading === 'Goal' && referent === 'Goal'))) || 
                   (utterance === 'null');

  // Report whether the referent counts as answering the QUD
  return likelihood && judgment === referent ? true : false;
}

// Define the speaker's model
function speaker(reading, referent, QUD) {
  var judgments = {};
  judgments['he'] = sample(QUD);
  judgments['null'] = sample(QUD);

  // Evaluate each utterance by the log-probability the literal listener assigns to this judgment
  var scores = {};
  scores['he'] = Math.log(literalListener('he', reading, QUD) ? 1 : 0);
  scores['null'] = Math.log(literalListener('null', reading, QUD) ? 1 : 0);

  // Choose among the two utterances with probability proportional to the exponential of the optimality parameter times this evaluation
  var utterance = sample(categorical(['he', 'null'], [Math.exp(alpha * scores['he']), Math.exp(alpha * scores['null'])]));

  return utterance;
}

// Define the pragmatic listener's model
function pragmaticListener(utterance, QUD) {
  var referent = sample(referentPrior);
  var reading = sample(readingPrior);

  // Reweight each (referent, reading) pair in proportion to the probability that the corresponding speaker would produce the observed utterance
  var weight = speaker(reading, referent, QUD) === utterance ? 1 : 0;

  return {referent, weight};
}

// Define the inference model
function model(QUD) {
  var utterance = 'he';
  var results = Infer({method: 'enumerate'}, function() {
    var referent = sample(referentPrior);
    var reading = sample(readingPrior);
    var weight = speaker(reading, referent, QUD) === utterance ? 1 : 0;
    return {referent, weight};
  });

  return results;
}

// Run the inference model for each QUD
var whyResults = model(whyQUD);
var whatNextResults = model(whatNextQUD);
var whoResults = model(whoQUD);

// Compute the posterior probability distributions
var whyDistribution = whyResults.normalize();
var whatNextDistribution = whatNextResults.normalize();
var whoDistribution = whoResults.normalize();

// Assign the answer to a top-level variable
var ANSWER = {
  whyQUD: whyDistribution,
  whatNextQUD: whatNextDistribution,
  whoQUD: whoDistribution
};

var referents = ["Source", "Goal", "Other"];
var utterances = ["he", "null"];
var alpha = 2.5;

var qudProbs = {
  "Why?": [0.82, 0.17, 0.01],
  "What-next?": [0.33, 0.66, 0.01],
  "Who?": [1/3, 1/3, 1/3]
};

// random QUD-match rule: draw a role from the QUD distribution, check equality
var qudFn = function(qud, referent) {
  var drawn = categorical({ps: qudProbs[qud], vs: referents});
  return drawn === referent;
};

var meaning = function(utterance, reading, referent) {
  return utterance === "null" ? true :
    (reading === "Source" ? referent === "Source" : referent === "Goal");
};

var literalListener = cache(function(utterance, reading, qud) {
  return Infer({method: 'enumerate'}, function() {
    var referent = uniformDraw(referents);
    condition(meaning(utterance, reading, referent));
    return qudFn(qud, referent);
  });
});

var speaker = cache(function(reading, referent, qud) {
  return Infer({method: 'enumerate'}, function() {
    var utterance = uniformDraw(utterances);
    var qudValue = qudFn(qud, referent);
    factor(alpha * literalListener(utterance, reading, qud).score(qudValue));
    return utterance;
  });
});

var pragmaticListener = function(utterance, qud) {
  return Infer({method: 'enumerate'}, function() {
    var referent = uniformDraw(referents);
    var reading = categorical({ps: [0.1, 0.9], vs: ["Source", "Goal"]});
    observe(speaker(reading, referent, qud), utterance);
    return referent;
  });
};

var ANSWER = {
