};

var qudMatch = function(referent, qudDist) {
  var sampledRole = categorical({ps: qudDist, vs: ['Source', 'Goal', 'Other']});
  return sampledRole === referent;
};

var whyDist = [0.82, 0.17, 0.01];
var whatNextDist = [0.33, 0.66, 0.01];
var whoDist = [1/3, 1/3, 1/3];

var literalListener = function(utterance, reading, qudDist) {
  return Infer({method: 'enumerate'}, function() {
    var referent = referentPrior();
    // Check if utterance is true under the given reading
    var isTrue = (utterance === 'null') ||
                 (utterance === 'he' && ((reading === 'Source' && referent === 'Source') ||
                                         (reading === 'Goal' && referent === 'Goal')));
    condition(isTrue);
    // Now draw a fresh QUD match judgment
    var matchesQUD = qudMatch(referent, qudDist);
    return matchesQUD;
  });
};

var alpha = 2.5;

var speaker = function(referent, reading, qudDist) {
