    // Draw a fresh QUD match for evaluation
    var matchesQUD = qudMatch(referent, qudDist);

    // Get literal listener's belief for this utterance and reading
    var llDist = literalListener(utterance, reading, qudDist);
    var logProb = Math.log(llDist.score(matchesQUD));

    factor(alpha * logProb);
    return utterance;
  });
};

var pragmaticListener = function(observedUtterance, qudDist) {
  return Infer({method: 'enumerate'}, function() {
    var referent = referentPrior();
    var reading = readingPrior();
    var speakerDist = speaker(referent, reading, qudDist);
    observe(speakerDist, observedUtterance);
