var alpha = 2.5;
var referents = ["Source", "Goal", "Other"];
var readings = ["Source", "Goal"];
var utterances = ["pronoun", "null"];

var qudPs = function(qud) {
  if (qud === "Why")       return [0.82, 0.17, 0.01];
  if (qud === "What-next") return [0.33, 0.66, 0.01];
  if (qud === "Who")       return [1/3,  1/3,  1/3];
};

var qudMatchProb = function(referent, qud) {
  var ps = qudPs(qud);
  var idx = referents.indexOf(referent);
  return ps[idx];
};

var truthful = function(utterance, reading, referent) {
  if (utterance === "null") return true;
  // utterance === "pronoun"
  if (reading === "Source") return referent === "Source";
  if (reading === "Goal")   return referent === "Goal";
  return false;
};

var literalListener = cache(function(utterance, reading, qud) {
  return Infer({method: 'enumerate'}, function() {
    var referent = uniformDraw(referents);
    condition(truthful(utterance, reading, referent));
    // QUD-match judgment drawn afresh
    var matchProb = qudMatchProb(referent, qud);
    var judgment = flip(matchProb);
    return judgment;
  });
});

var speaker = cache(function(reading, referent, qud) {
  return Infer({method: 'enumerate'}, function() {
    // Draw a fresh QUD-match judgment for the true referent
    var matchProb = qudMatchProb(referent, qud);
    var judgment = flip(matchProb);

    // Choose utterance; prior is uniform over {pronoun, null}
    var utterance = uniformDraw(utterances);

    // Evaluate utterance by log-prob the LL assigns to this judgment
    var ll = literalListener(utterance, reading, qud);
    factor(alpha * ll.score(judgment));

    return utterance;
  });
});

var pragmaticListener = function(qud) {
  return Infer({method: 'enumerate'}, function() {
    var referent = uniformDraw(referents);
    var reading  = categorical({vs: readings, ps: [0.1, 0.9]});

    var sp = speaker(reading, referent, qud);
    observe(sp, "pronoun");

    return referent;
  });
};

var ANSWER = {
