};

// WebPPL program

// actual price is known to the model
var actualPrice = 4;

// truthful responses (only those consistent with actual price)
var truthfulResponses = [
  {type: 'yesno', answer: 'no', cnt: 5},   // "No" is truthful, consistent with prices 1‑5
  {type: 'amount', value: 4, cnt: 1}      // "$4" is truthful, consistent with price 4 only
];

// base (uninformed) weights = 1 / cnt
var baseWeights = truthfulResponses.map(function(r){ return 1.0 / r.cnt; });

// helper: normalize a vector of numbers into a probability vector
function normalize(ws){
  var sum = _.sum(ws);
  return ws.map(function(w){ return w / sum; });
}

// the generative model for a given context
function responseModel(context){
  // draw a goal according to the context‑specific distribution
  var goal;
  if (context === 'buy'){
    // 0.5 exact, 0.5 exceeds‑5
    goal = sample(categorical([0.5, 0.5])) === 0 ? 'exact' : 'exceeds5';
  } else { // spendFive
    // 0.01 exact, 0.99 exceeds‑5
    goal = sample(categorical([0.01, 0.99])) === 0 ? 'exact' : 'exceeds5';
  }

  // compute informativeness for each truthful response under this goal
  var infos = truthfulResponses.map(function(r){
    if (goal === 'exact'){
      // guess the exact price uniformly from the consistent set (size = cnt)
      return 1.0 / r.cnt;
    } else { // goal === 'exceeds5'
      // all truthful responses give perfect information about whether price >5
      return 1.0;
    }
  });

  // re‑weight the truthful‑response distribution by informativeness (optimality = 1)
  var reweighted = truthfulResponses.map(function(_, i){
    return baseWeights[i] * Math.pow(infos[i], 1);
  });
  var probs = normalize(reweighted);

  // sample the final response according to the re‑weighted distribution
  var idx = categorical(probs);
  var finalResp = truthfulResponses[idx];

  // we return only the response “type”: 'yesno' or 'amount'
  return finalResp.type;
}

// inference for each context
var buyDist = Infer({method: 'enumerate'}, function(){ return responseModel('buy'); });
var spendDist = Infer({method: 'enumerate'}, function(){ return responseModel('spendFive'); });

var ANSWER = {
  buyWhiskeyContext: buyDist,
  spendFiveDollarsContext: spendDist
};

var makeModel = function(pExactGoal) {
  // Actual price is 4
  var actualPrice = 4;

  // Define truthful responses
  var responsive = [
    {type: "YesNo",  count:5,  val:"No"},  // literal: price <=5
    {type: "Amount", count:1,  val:"4"}    // literal: price =4
  ];

  // Prior probability of each response form (0.5 each)
  var formPrior = 0.5;

  // Truthful response probabilities (after weighting inversely by consistent count)
  var truthProb = {
    "YesNo": formPrior / 5,   // 0.5/5 = 0.1  -> normalized to 1/6
    "Amount": formPrior / 1   // 0.5/1 = 0.5  -> normalized to 5/6
  };
  // Normalize
  var totalTruth = truthProb["YesNo"] + truthProb["Amount"];
  truthProb["YesNo"] /= totalTruth;
  truthProb["Amount"] /= totalTruth;

  // Informativeness tables
  var info = {
    "exact":    {"YesNo": 0.2, "Amount": 1},
    "exceeds5": {"YesNo": 1,   "Amount": 1}
  };

  // Goal distribution
  var goalDist = categorical([pExactGoal, 1 - pExactGoal]); // [exact, exceeds5]
  var goal = goalDist() === 0 ? "exact" : "exceeds5";

  // Compute weighted probabilities for each truthful response under this goal
  var weights = [];
  responsive.forEach(function(r) {
    var w = truthProb[r.type] * info[goal][r.type];
    weights.push(w);
  });

  // Normalize weights to get response probabilities
  var sumW = weights.reduce(function(a, b) { return a + b; }, 0);
  var probs = weights.map(function(w) { return w / sumW; });

  // Sample a response type
  var respIndex = categorical(probs)();
  return responsive[respIndex].type;  // "YesNo" or "Amount"
};

