// response prior: form (yes/no vs exact amount) each 0.5, uniform within form
var responsePrior = function() {
  return flip(0.5)
    ? {type: 'yesno', val: flip(0.5)}
    : {type: 'amount', val: uniformDraw(prices)};
};

// literal meaning
var meaning = function(r, p) {
  return r.type === 'yesno' ? ((p > 5) === r.val) : (p === r.val);
};

// prices consistent with the response taken literally
var consistentPrices = function(r) {
  return filter(function(p) { return meaning(r, p); }, prices);
};

// distribution over truthful responses, weighted inversely by extension size
var truthfulDist = Infer({method: 'enumerate'}, function() {
  var r = responsePrior();
  condition(meaning(r, actualPrice));
  factor(-Math.log(consistentPrices(r).length));
  return r;
});

// goal-relevant quantity
var qud = function(goal, p) {
  return goal === 'exact' ? p : (p > 5);
};

// informativeness: chance a uniform guess among consistent prices matches truth on the QUD
var informativeness = function(r, goal) {
  var set = consistentPrices(r);
  var truth = qud(goal, actualPrice);
  var matches = sum(map(function(p) { return qud(goal, p) === truth ? 1 : 0; }, set));
  return matches / set.length;
};

