// Renormalized: each gets weight 0.5.

// Informativeness for each (response, goal) pair:
// Goal "exact" (guess exact price uniformly among consistent prices):
//   "no"  -> consistent = {1..5}, P(guess=4) = 1/5
//   "$4"  -> consistent = {4},    P(guess=4) = 1
// Goal "exceeds5" (guess whether price>5 uniformly among consistent prices):
//   true answer: 4>5 = false
//   "no"  -> consistent = {1..5}, all have exceeds5=false, P(correct) = 1
//   "$4"  -> consistent = {4},    4>5=false,               P(correct) = 1

var informativeness = function(response, goal) {
  if (response === "no") {
    return (goal === "exact") ? (1 / 5) : 1;
  } else {
    // response === "$4"
    return (goal === "exact") ? 1 : 1;
  }
};

