// Build answerer model for a given context (goalProbExact = P(goal="exact"))
var answererModel = function(goalProbExact) {
  return Infer({method: 'enumerate'}, function() {
    // Draw goal
    var goal = flip(goalProbExact) ? "exact" : "exceeds5";

    // Truthful response distribution (each has base weight 0.5)
    // Reweight by informativeness^alpha
    var wNo  = 0.5 * Math.pow(informativeness("no", goal), alpha);
    var wAmt = 0.5 * Math.pow(informativeness("$4", goal), alpha);
    var total = wNo + wAmt;

