// Compute the probability of an agent's report given a particular pRed
var reportProb = function(pRed, report) {
  var total = 0;
  // marginalise over the latent count k the agent could have observed
  for (var k = 0; k <= nMarbles; k++) {
    // P(k | pRed) for the agent's own draw
    var logPk = Binomial({n: nMarbles, p: pRed}).score(k);
    var Pk = Math.exp(logPk);

    // Compute the agent's posterior over p (given k)
    var weights = [];
    var sumW = 0;
    for (var i = 0; i < pVals.length; i++) {
      var p = pVals[i];
      var logLik = Binomial({n: nMarbles, p: p}).score(k);
      var w = Math.exp(logLik); // prior is uniform, so weight = likelihood
      weights[i] = w;
      sumW += w;
    }

    // probability of the observed report under this posterior
    var probReportGivenK = 0;
    for (var i = 0; i < pVals.length; i++) {
      var p = pVals[i];
      var postProb = weights[i] / sumW;      // posterior probability of p

      // prediction probability
      var predProb = (report.prediction === 'red') ? p : (1 - p);

      // confidence according to the model
