                     (report.prediction === 'blue' && p <= 0.4);
      var conf = confHigh ? 'high' : 'low';

      var confMatch = (conf === report.confidence) ? 1 : 0;

      probReportGivenK += postProb * predProb * confMatch;
    }

    total += Pk * probReportGivenK;
  }
  return total;
};

