    var reportProb = agentReportProb(m, report);
    // If reportProb == 0, the entire likelihood is zero; handle log(0) as -Infinity
    var contrib = binom * reportProb;
    if (contrib > 0) {
      sum += contrib;
    }
  }
  if (sum > 0) return Math.log(sum);
  return -Infinity;
}

