      var predProb = prediction === 'red' ? p : (1 - p);

      if (consistent) {
        reportProb += posteriorProb * predProb;
      }
    }

    totalProb += countProb * reportProb;
  }

  return Math.log(Math.max(totalProb, 1e-10));
};

