var factorial = function(n) { return n <= 1 ? 1 : n * factorial(n - 1); };
var choose = function(n, k) { return factorial(n) / (factorial(k) * factorial(n - k)); };
var binomPmf = function(n, k, p) {
  return choose(n, k) * Math.pow(p, k) * Math.pow(1 - p, n - k);
};

