  return Infer({method: 'enumerate'}, function() {
    var p = sample(post);
    var pred = flip(p) ? 'red' : 'blue';
    var conf = ((pred === 'red' && p >= threshold) ||
                (pred === 'blue' && p <= 1 - threshold)) ? 'high' : 'low';
    return {prediction: pred, confidence: conf};
  });
});

