      factor(Math.log(pChooseB));
    }
  }

  // Return Alice's own utilities
  return {
    ownUtilityBurgerBarn: aliceUtilityBurgerBarn,
    ownUtilityStirfryShack: aliceUtilityStirfryShack
  };
};

// Use SMC with 10000 particles
var posterior = Infer({
  method: 'SMC',
  particles: 10000
}, model);

// Extract marginals for each utility
var ownUtilityBurgerBarn = Infer({method: 'forward'}, function() {
  return sample(posterior).ownUtilityBurgerBarn;
});

var ownUtilityStirfryShack = Infer({method: 'forward'}, function() {
  return sample(posterior).ownUtilityStirfryShack;
});

var ANSWER = {
  ownUtilityBurgerBarn: ownUtilityBurgerBarn,
  ownUtilityStirfryShack: ownUtilityStirfryShack
};

var clip = function(x) {
    if (x <= 0.001) return 0.001;
    if (x >= 0.999) return 0.999;
    return x;
};

var ANSWER = Infer({ method: 'SMC', particles: 10000 }, function() {
    var B_mean = uniform(0, 1);
    var S_mean = uniform(0, 1);
    var sigma = uniform(0, 0.15);

    var AUB = clip(gaussian(B_mean, sigma));
    var AUS = clip(gaussian(S_mean, sigma));

    var O1_BB = clip(gaussian(B_mean, sigma));
    var O1_SS = clip(gaussian(S_mean, sigma));
    var O2_BB = clip(gaussian(B_mean, sigma));
    var O2_SS = clip(gaussian(S_mean, sigma));
    var O3_BB = clip(gaussian(B_mean, sigma));
    var O3_SS = clip(gaussian(S_mean, sigma));

    var reward = bernoulli(AUB);
    observe(reward, 1);

    var P1 = [O1_BB / (O1_BB + O1_SS), O1_SS / (O1_BB + O1_SS)];
    var choice1 = categorical(P1, 2);
    observe(choice1, 2);

    var P2 = [O2_BB / (O2_BB + O2_SS), O2_SS / (O2_BB + O2_SS)];
    var choice2 = categorical(P2, 2);
    observe(choice2, 2);

    var P3 = [O3_BB / (O3_BB + O3_SS), O3_SS / (O3_BB + O3_SS)];
    var choice3 = categorical(P3, 2);
    observe(choice3, 2);

    return {
        ownUtilityBurgerBarn: AUB,
        ownUtilityStirfryShack: AUS
    };
});

var clip = function(x) {
  return Math.max(0.001, Math.min(0.999, x));
};

var makeModel = function(returnWhich) {
  return function() {
    // Group-level mean utilities drawn from Beta(1,1) = Uniform(0,1)
    var meanBB = beta(1, 1);
    var meanSS = beta(1, 1);
    // Shared group-level standard deviation
    var std = uniform(0, 0.15);

    // Alice's own utilities, clipped to (0.001, 0.999)
    var aliceBB = clip(gaussian(meanBB, std));
    var aliceSS = clip(gaussian(meanSS, std));

    // Alice chose Burger Barn and received a positive reward signal
    // Soft evidence: Bernoulli(aliceBB) = true
    observe(Bernoulli({p: aliceBB}), true);

    // Three other agents each chose Stirfry Shack
    // Each agent has their own independently drawn utilities
    // Proportional choice: P(choose SS) = agentSS / (agentBB + agentSS)
    var agentChoosesSS = function() {
      var agentBB = clip(gaussian(meanBB, std));
      var agentSS = clip(gaussian(meanSS, std));
      var pSS = agentSS / (agentBB + agentSS);
      // Soft evidence: agent chose SS under proportional-choice rule
      observe(Bernoulli({p: pSS}), true);
    };

    agentChoosesSS();
    agentChoosesSS();
    agentChoosesSS();

    return returnWhich === 'BB' ? aliceBB : aliceSS;
  };
};

var distBurgerBarn = Infer({method: 'SMC', particles: 10000}, makeModel('BB'));
var distStirfryShack = Infer({method: 'SMC', particles: 10000}, makeModel('SS'));

var ANSWER = {
  ownUtilityBurgerBarn: distBurgerBarn,
  ownUtilityStirfryShack: distStirfryShack
};

// ----  Constants ----------------------------------------------------
var worlds = ["No","Just some","All"];
var worldPrior = 1 / worlds.length;               // uniform prior over worlds

var questions = [
  {name:"exact",  prob:0.8, classFn:w=>w},               // distinguish all three
  {name:"someOrAll", prob:0.1, classFn:w=> (w==="No")?"No":"SomeOrAll"}, // {Just some,All} vs {No}
  {name:"all?", prob:0.1, classFn:w=> (w==="All")?"All":"NotAll"}      // {All} vs {No,Just some}
];
var questionPrior = questions.map(q=>q.prob);

// utterance data ----------------------------------------------------
var utterances = ["some","all","no","not all","the","not the"];
var costs = {"some":1,"all":1,"no":1.5,"not all":2,"the":0,"not the":1};

var rho = 5;      // rationality

// ----  Lexicons ----------------------------------------------------
/* lexicon 0 : "the" = "some", "not the" = "no"
   lexicon 1 : "the" = "all",  "not the" = "not all"
   The four fixed utterances have the same meaning in both lexicons. */
// truth tables for the fixed utterances (same for both lexicons)
var fixedTruth = {
  "some":    w=> (w==="Just some"||w==="All"),
  "all":     w=> (w==="All"),
  "no":      w=> (w==="No"),
  "not all": w=> (w==="No"||w==="Just some")
};
// lexicon‑dependent truth functions
var truth = function(lex, u, w){ 
  if(u==="the")        return (lex===0 ? fixedTruth["some"](w)   : fixedTruth["all"](w));
  if(u==="not the")    return (lex===0 ? fixedTruth["no"](w)     : fixedTruth["not all"](w));
  return fixedTruth[u](w);         // the four core utterances
};

// ----  Helper: prior weight for (world,question) --------------------
var priorWeight = function(w,qIdx){
  return worldPrior * questionPrior[qIdx];
};

// ----  1. Literal listener probability ------------------------------
var literalProb = function(u,lex,w,qIdx){
  // probability that literal listener (lexicon = lex) outputs the true pair
  // given utterance u.
  // Compute normalising constant Z.
  var Z = 0;
  for (var w2 of worlds){
    for (var qi=0; qi<questions.length; ++qi){
      if(truth(lex,u,w2)){
        Z += priorWeight(w2,qi);
      }
    }
  }
  if(!truth(lex,u,w)) return 0;
  return priorWeight(w,qIdx) / Z;
};

// ----  2. Speaker level 1 -------------------------------------------
var speaker = {};   // speaker[n][w][qIdx][u] = prob
speaker[1] = {};
for (var w of worlds){
  speaker[1][w] = {};
  for (var qIdx=0; qIdx<questions.length; ++qIdx){
    // informativity scores for each utterance
    var scores = {};
    for (var u of utterances){
      var expInform = 0;
      for (var lex=0; lex<2; ++lex){
        var lp = literalProb(u,lex,w,qIdx);
        expInform += 0.5 * Math.log(lp);
      }
      scores[u] = expInform - costs[u];
    }
    // exponentiated, re‑normalise
    var maxScore = Math.max(...utterances.map(u=>scores[u]));
    var weights = {};
    var sum = 0;
    for (var u of utterances){
      var wgt = Math.exp(rho * (scores[u] - maxScore)); // avoid overflow
      weights[u] = wgt;
      sum += wgt;
    }
    // store probabilities
    for (var u of utterances){
      if(!speaker[1][w][qIdx]) speaker[1][w][qIdx] = {};
      speaker[1][w][qIdx][u] = weights[u] / sum;
    }
  }
}

// ----  3. Pragmatic listeners and higher‑level speakers -------------
for (var n=2; n<=5; ++n){
  // listener_{n-1} (already computed as speaker[n-1] inside)
  // compute speaker_n
  speaker[n] = {};
  for (var w of worlds){
    speaker[n][w] = {};
    for (var qIdx=0; qIdx<questions.length; ++qIdx){
      // first compute listener_{n-1} posterior over (w,q) given each utterance
      // we need P_{listener_{n-1}}(w,q | u) = const * prior(w,q) * speaker_{n-1}(u|w,q)
      // We'll compute it on the fly for each utterance when needed.
      var scores = {};
      for (var u of utterances){
        // compute listener_{n-1} probability for this (w,q) pair
        var Z = 0;
        for (var w2 of worlds){
          for (var q2=0; q2<questions.length; ++q2){
            Z += priorWeight(w2,q2) * speaker[n-1][w2][q2][u];
          }
        }
        var probListener = (priorWeight(w,qIdx) * speaker[n-1][w][qIdx][u]) / Z;
        scores[u] = Math.log(probListener) - costs[u];
      }
      // exponentiate and normalise
      var maxScore = Math.max(...utterances.map(u=>scores[u]));
      var weights = {};
      var sum = 0;
      for (var u of utterances){
        var wgt = Math.exp(rho * (scores[u] - maxScore));
        weights[u] = wgt;
        sum += wgt;
      }
      // store speaker_n probabilities
      for (var u of utterances){
        if(!speaker[n][w][qIdx]) speaker[n][w][qIdx] = {};
        speaker[n][w][qIdx][u] = weights[u] / sum;
      }
    }
  }
}

// ----  4. Level‑5 pragmatic listener for each utterance -------------
var ANSWER = {};

for (var u of utterances){
  // model that returns a world conditioned on hearing utterance u
  var model = function(){
    var w = uniformDraw(worlds);          // sample world uniformly
    var qIdx = categorical({ps:questionPrior}); // sample question index
    var prob = speaker[5][w][qIdx][u];     // speaker_5 probability of utterance u
    factor(Math.log(prob));               // reweight by this probability
    return w;
  };
  // Infer the posterior over worlds
  var dist = Infer({method:'enumerate'}, model);
  // Convert to plain object {No:…, "Just some":…, All:…}
  var obj = {};
  for (var sup of dist.support()){
    obj[sup] = dist.prob(sup);
  }
  ANSWER[u] = obj;
}

// WebPPL program to compute level‑5 pragmatic listener posteriors
var worlds = ["No", "Just some", "All"];
var worldIndex = {"No":0, "Just some":1, "All":2};

var utterances = ["some", "all", "no", "not all", "the", "not the"];
var utteranceIndex = {"some":0, "all":1, "no":2, "not all":3, "the":4, "not the":5};

var Q1=0, Q2=1, Q3=2;
var questionKeys = ["Q1", "Q2", "Q3"];
var questionDist = categorical({Q1:0.8, Q2:0.1, Q3:0.1});
var questionProb = [0.8, 0.1, 0.1];

var cost = [1, 1, 1.5, 2, 0, 1];
var beta = 5;

// Truth sets for the two lexicons
var lex1Truth = [
  [1,2],   // some
  [2],     // all
  [0],     // no
  [0,1],   // not all
  [1,2],   // the (same as some)
  [0]      // not the (same as no)
];
var lex2Truth = [
  [1,2],   // some
  [2],     // all
  [0],     // no
  [0,1],   // not all
  [2],     // the (same as all)
  [0,1]    // not the (same as not all)
];
var lexicons = [lex1Truth, lex2Truth];

// Helper to get class of a world under a question
function worldClass(wi, qi){
  if(qi===Q1){ return worlds[wi]; }
  if(qi===Q2){
    return (wi===0 ? "No" : "JustSomeOrAll");
  }
  // qi===Q3
  return (wi===2 ? "All" : "NoOrJustSome");
}

// Pre‑compute literal listener probabilities L0 for each lexicon, utterance, world, question
var l0LogProb = []; // [lex][utt][w][q]
for(var lex=0; lex<2; lex++){
  l0LogProb[lex] = [];
  for(var u=0; u<6; u++){
    var truthSet = lexicons[lex][u];
    var denom = truthSet.length;
    // Compute counts per class for each question
    var countsPerQ = [ {}, {}, {} ]; // [qid][class] = count
    for(var qi=0; qi<3; qi++){
      var counts = {};
      for(var wi=0; wi<3; wi++){
        var cls = worldClass(wi, qi);
        if(truthSet.indexOf(wi)!==-1){
          counts[cls] = (counts[cls]||0)+1;
        }
      }
      countsPerQ[qi] = counts;
    }
    // Now compute log probs
    l0LogProb[lex][u] = [];
    for(var wi=0; wi<3; wi++){
      l0LogProb[lex][u][wi] = [];
      var inTruth = truthSet.indexOf(wi)!==-1;
      for(var qi=0; qi<3; qi++){
        if(!inTruth){
          l0LogProb[lex][u][wi][qi] = -Infinity;
        }else{
          var cls = worldClass(wi, qi);
          var count = countsPerQ[qi][cls]||0;
          var prob = count/denom;
          l0LogProb[lex][u][wi][qi] = Math.log(prob);
        }
      }
    }
  }
}

// Compute speaker probabilities S_n and listener probabilities L_n for levels 1..5
var SProb = {}; // [level][u][w][q]
var LProb = {}; // [level][u][w][q]
var level;

for(level=1; level<=5; level++){
  SProb[level] = [];
  for(var u=0; u<6; u++){
    SProb[level][u] = [];
    for(var wi=0; wi<3; wi++){
      SProb[level][u][wi] = [];
      for(var qi=0; qi<3; qi++){
        // Compute utility
        var utility;
        if(level===1){
          // Expectation over lexicons of log(L0)
          var eLog = 0;
          for(var lex=0; lex<2; lex++){
            eLog += 0.5 * l0LogProb[lex][u][wi][qi];
          }
          utility = eLog - cost[u];
        }else{
          // Use previous listener L_{level-1}
          var logPrev = Math.log(LProb[level-1][u][wi][qi]);
          utility = logPrev - cost[u];
        }
        var unnorm = Math.exp(beta * utility);
        SProb[level][u][wi][qi] = unnorm;
      }
    }
  }
  // Normalize SProb over utterances for each w,q
  for(var u=0; u<6; u++){
    for(var wi=0; wi<3; wi++){
      for(var qi=0; qi<3; qi++){
        // Sum over utterances
        var sum = 0;
        for(var u2=0; u2<6; u2++){
          sum += SProb[level][u2][wi][qi];
        }
        SProb[level][u][wi][qi] /= sum;
      }
    }
  }
  // Now compute listener distribution LProb
  LProb[level] = [];
  for(var u=0; u<6; u++){
    LProb[level][u] = [];
    for(var wi=0; wi<3; wi++){
      LProb[level][u][wi] = [];
      for(var qi=0; qi<3; qi++){
        var unorm = (1/3) * questionProb[qi] * SProb[level][u][wi][qi];
        LProb[level][u][wi][qi] = unorm;
      }
    }
  }
  // Normalize LProb over w,q for each utterance
  for(var u=0; u<6; u++){
    var sum = 0;
    for(var wi=0; wi<3; wi++){
      for(var qi=0; qi<3; qi++){
        sum += LProb[level][u][wi][qi];
      }
    }
    for(var wi=0; wi<3; wi++){
      for(var qi=0; qi<3; qi++){
        LProb[level][u][wi][qi] /= sum;
      }
    }
  }
}

// Function that samples a world given an utterance using the level‑5 speaker
function listenerSample(utt){
  return Infer({method:'enumerate'}, function(){
    var w = sample(categorical({No:1/3, "Just some":1/3, All:1/3}));
    var wIdx = worldIndex[w];
    var qKey = sample(categorical({Q1:0.8, Q2:0.1, Q3:0.1}));
    var qIdx = questionKeys.indexOf(qKey);
    var prob = SProb[5][utteranceIndex[utt]][wIdx][qIdx];
    factor(Math.log(prob));
    return w;
  });
}

// Compute distributions for all utterances
var ans = {};
for(var u=0; u<6; u++){
  ans[utterances[u]] = listenerSample(utterances[u]);
}

var ANSWER = ans;

var worlds = ["No", "Just some", "All"];
var utterances = ["some", "all", "no", "not all", "the", "not the"];

var costs = {
  "the": 0,
  "not the": 1,
  "some": 1,
  "all": 1,
  "no": 1.5,
  "not all": 2
};

var literalTruth = function(utt, world, lex) {
  if (utt === "some") return world === "Just some" || world === "All";
  if (utt === "all") return world === "All";
  if (utt === "no") return world === "No";
  if (utt === "not all") return world === "No" || world === "Just some";
  if (utt === "the") {
    return lex === 0 ? (world === "Just some" || world === "All") : (world === "All");
  }
  if (utt === "not the") {
    return lex === 0 ? (world === "No") : (world === "No" || world === "Just some");
  }
  return false;
};

var qudSample = function() {
  if (flip(0.8)) return "q1";
  return flip(0.5) ? "q2" : "q3";
};

var getEquivalenceClass = function(world, qud) {
  if (qud === "q1") return world;
  if (qud === "q2") return (world === "No" ? "No" : "pos");
  return (world === "All" ? "All" : "other");
};

var literalListener = function(utt, lex) {
  return Infer({method: "enumerate"}, function() {
    var world = uniformDraw(worlds);
    var qud = qudSample();
    condition(literalTruth(utt, world, lex));
    var eqClass = getEquivalenceClass(world, qud);
    return {eqClass: eqClass, qud: qud};
  });
};

var level1Speaker = function(world, qud) {
  return Infer({method: "enumerate"}, function() {
    var utt = uniformDraw(utterances);
    var eqClass = getEquivalenceClass(world, qud);
    var logProb0 = literalListener(utt, 0).score({eqClass: eqClass, qud: qud});
    var logProb1 = literalListener(utt, 1).score({eqClass: eqClass, qud: qud});
    var avgLogProb = (logProb0 + logProb1) / 2;
    var informativity = avgLogProb - costs[utt];
    factor(5 * informativity);
    return utt;
  });
};

var pragmaticListener = function(n, utt) {
  return Infer({method: "enumerate"}, function() {
    var world = uniformDraw(worlds);
    var qud = qudSample();
    var speakerDist = (n === 1) ? level1Speaker(world, qud) : speaker(n, world, qud);
    observe(speakerDist, utt);
    return {world: world, qud: qud};
  });
};

var speaker = function(n, world, qud) {
  if (n === 1) return level1Speaker(world, qud);
  return Infer({method: "enumerate"}, function() {
    var utt = uniformDraw(utterances);
    var listenerDist = pragmaticListener(n - 1, utt);
    var informativity = listenerDist.score({world: world, qud: qud}) - costs[utt];
    factor(5 * informativity);
    return utt;
  });
};

var getWorldMarginal = function(utt) {
  var listenerDist = pragmaticListener(5, utt);
  return Infer({method: "enumerate"}, function() {
    var pair = sample(listenerDist);
    return pair.world;
  });
};

var ANSWER = {
  "some": getWorldMarginal("some"),
  "all": getWorldMarginal("all"),
  "no": getWorldMarginal("no"),
  "not all": getWorldMarginal("not all"),
  "the": getWorldMarginal("the"),
  "not the": getWorldMarginal("not the")
};

var lexicalUncertainty = 0.5;
var questions = {
  "exact": ["No", "Just some", "All"],
  "some or all": ["No", ["Just some", "All"]],
  "all": [["No", "Just some"], "All"]
};
var costs = {
  "some": 1,
  "all": 1,
  "no": 1.5,
  "not all": 2,
  "the": 0,
  "not the": 1
};
var alpha = 5;
var utterances = ["some", "all", "no", "not all", "the", "not the"];
var worlds = ["No", "Just some", "All"];
var lexicons = [
  function(utt) { return (utt === "some" || utt === "the") ? ["Just some", "All"] :
                    (utt === "all") ? ["All"] :
                    (utt === "no" || utt === "not the") ? ["No"] :
                    (utt === "not all") ? ["No", "Just some"] : []; },
  function(utt) { return (utt === "all" || utt === "the") ? ["All"] :
                    (utt === "some" || utt === "not the") ? ["No"] :
                    (utt === "no") ? ["No"] :
                    (utt === "not all") ? ["No", "Just some"] : []; }
];

// Literal listener
function literalListener(utterance, lexicon) {
  var results = [];
  for (var question in questions) {
    for (var world of worlds) {
      var literalTruth = lexicon(utterance).includes(world);
      var equivalenceClass = questions[question].find(eqClass => eqClass.includes(world) || eqClass.some(x => x.includes(world)));
      if (literalTruth) {
        results.push([equivalenceClass, question]);
      }
    }
  }
  return results;
}

// Level-1 speaker
function level1Speaker(world, question) {
  var scores = {};
  for (var utterance of utterances) {
    var score = 0;
    for (var lexicon of lexicons) {
      var literalListenerResults = literalListener(utterance, lexicon);
      var correctLiteralListenerResults = literalListenerResults.filter(result => result[0].includes(world) || result[0].some(x => x.includes(world)));
      var probability = correctLiteralListenerResults.length / literalListenerResults.length;
      score += lexicalUncertainty * Math.log(probability);
    }
    score -= costs[utterance];
    scores[utterance] = Math.exp(alpha * score);
  }
  var normalize = Object.values(scores).reduce((a, b) => a + b, 0);
  for (var utterance in scores) {
    scores[utterance] /= normalize;
  }
  return scores;
}

// Pragmatic listener and speaker
function pragmaticListener(utterance, level) {
  var results = [];
  for (var world of worlds) {
    for (var question in questions) {
      var probability = 1 / (worlds.length * Object.keys(questions).length);
      if (level === 1) {
        var speaker = level1Speaker(world, question);
        probability *= speaker[utterance];
      } else {
        var speaker = pragmaticSpeaker(world, question, level - 1);
        probability *= speaker[utterance];
      }
      results.push([world, question, probability]);
    }
  }
  var normalize = results.reduce((a, b) => a + b[2], 0);
  for (var result of results) {
    result[2] /= normalize;
  }
  return results;
}

function pragmaticSpeaker(world, question, level) {
  var scores = {};
  for (var utter!ance of utterances) {
    var score = 0;
    var listenerResults = pragmaticListener(utterance, level);
    for (var result of listenerResults) {
      if (result[0] === world && result[1] === question) {
        score += result[2];
      }
    }
    score -= costs[utterance];
    scores[utterance] = Math.exp(alpha * score);
  }
  var normalize = Object.values(scores).reduce((a, b) => a + b, 0);
  for (var utterance in scores) {
    scores[utterance] /= normalize;
  }
  return scores;
}

// Inference
