for (var utterance of utterances) {
  var results = pragmaticListener(utterance, 5);
  var distribution = {};
  for (var result of results) {
    if (!distribution[result[0]]) {
      distribution[result[0]] = 0;
    }
    distribution[result[0]] += result[2];
  }
  ANSWER[utterance] = distribution;
}

// RSA with lexical uncertainty and QUDs

var alpha = 5;

