var utterances = ["some", "all", "no", "not all", "the", "not the"];

var cost = {"some": 1, "all": 1, "no": 1.5, "not all": 2, "the": 0, "not the": 1};

var meaning = function(utt, lex, s) {
  return utt === "some" ? (s !== "No") :
         utt === "all" ? (s === "All") :
