// Given a world state and a question, return the equivalence class
var getEquivalenceClass = function(world, question) {
  if (question === "exact") {
    return world;
  } else if (question === "some-or-all") {
    return (world === "Just some" || world === "All") ? "some-or-all-yes" : "some-or-all-no";
  } else if (question === "all") {
