// Literal listener: given utterance and lexicon, returns distribution over (class, question)
var literalListener = function(utterance, lexicon) {
  return Infer({method: 'enumerate'}, function() {
    var world = uniformDraw(worldStates);
    var question = questionPrior();
    var trueClass = getEquivalenceClass(world, question);

    // Check if utterance is true in this world under lexicon
    var isTrue = _.includes(lexicons[lexicon][utterance], world);
    condition(isTrue);

    return {class: trueClass, question: question, world: world};
  });
};

// Level-1 speaker: given world and question, returns distribution over utterances
var speaker1 = cache(function(world, question) {
  return Infer({method: 'enumerate'}, function() {
    var utterance = uniformDraw(utterances);

    // Compute informativity: expected log prob of (true class, question) under literal listener
    var trueClass = getEquivalenceClass(world, question);

    var probLex1 = literalListener(utterance, "lex1").score({class: trueClass, question: question, world: world});
    var probLex2 = literalListener(utterance, "lex2").score({class: trueClass, question: question, world: world});

    var expectedLogProb = Math.log(0.5 * Math.exp(probLex1) + 0.5 * Math.exp(probLex2));

    var score = expectedLogProb - costs[utterance];

    factor(rationality * score);

    return utterance;
  });
});

// Level-n listener (n >= 1): given utterance, returns distribution over (world, question)
var listener = cache(function(level, utterance) {
  return Infer({method: 'enumerate'}, function() {
    var world = uniformDraw(worldStates);
    var question = questionPrior();

    var speakerFn = (level === 1) ? speaker1 : speaker;
    var speakerDist = speakerFn(level - 1, world, question);
    var speakerProb = Math.exp(speakerDist.score(utterance));

    factor(Math.log(speakerProb));

    return world;
  });
}, 3);

