  return Infer({method: 'enumerate'}, function() {
    var utterance = uniformDraw(utterances);

    var listenerDist = listener(level - 1, utterance);
    var listenerProb = Math.exp(listenerDist.score(world));

    var score = Math.log(listenerProb) - costs[utterance];

    factor(rationality * score);

    return utterance;
  });
}, 3);

