var alpha = 5;

var qudPrior = function() {
  return categorical({ps: [0.8, 0.1, 0.1], vs: quds});
};

var literalMeaning = function(utt, world, lex) {
  if (utt === "some")    return world === "Just some" || world === "All";
  if (utt === "all")     return world === "All";
  if (utt === "no")      return world === "No";
  if (utt === "not all") return world === "No" || world === "Just some";
  if (utt === "the")     return lex === 1 ? (world === "Just some" || world === "All") : world === "All";
  if (utt === "not the") return lex === 1 ? world === "No" : (world === "No" || world === "Just some");
};

var equivClass = function(world, qud) {
  if (qud === "exact")      return world;
  if (qud === "some-or-all") return (world === "Just some" || world === "All") ? "som_T" : "som_F";
  if (qud === "all-qud")    return world === "All" ? "all_T" : "all_F";
};

var L0 = cache(function(utt, lex) {
  return Infer({method: 'enumerate'}, function() {
