// Helper predicates.
var atLeastOne = function(arr, pred){ return arr.some(pred); };
var every = function(arr, pred){ return arr.every(pred); };

// Core model that returns a uniformly sampled true conclusion.
var makeModel = function(probs){
  return function(){
    // Sample four independent individuals.
    var inds = [
      sample(Categorical({ps: probs, vs: combos})),
      sample(Categorical({ps: probs, vs: combos})),
      sample(Categorical({ps: probs, vs: combos})),
      sample(Categorical({ps: probs, vs: combos}))
    ];

    // Condition on the premises.
    condition(atLeastOne(inds, function(p){ return p.B && p.A; }));           // some B are A
    condition(every(inds, function(p){ return !p.C || p.B; }));               // all C are B

    // Condition on each property appearing at least once.
    condition(atLeastOne(inds, function(p){ return p.A; }));
    condition(atLeastOne(inds, function(p){ return p.B; }));
    condition(atLeastOne(inds, function(p){ return p.C; }));

    // Evaluate the four possible conclusions.
    var allCA   = every(inds, function(p){ return !p.C || p.A; });
    var someCA  = atLeastOne(inds, function(p){ return p.C && p.A; });
    var noneCA  = every(inds, function(p){ return !(p.C && p.A); });
    var notAllCA = !allCA; // given at least one C, this matches "not all C are A"

    var trueSet = [];
    if (allCA)   trueSet.push("all C are A");
    if (someCA)  trueSet.push("some C are A");
    if (noneCA)  trueSet.push("none C are A");
    if (notAllCA) trueSet.push("not all C are A");

    // Uniformly pick one true conclusion.
    return uniformDraw(trueSet);
  };
};

