  var cfWeight=0, numWeight=0, denWeight=0;
  for (var aS of strengths)
  for (var bS of strengths)
  for (var aL of lazies)
  for (var bL of lazies)
  for (var tie of tieVals){
    // for each variable decide keep or resample probability
    // probability that this cf arises given the actual o:
