function L1prob(o,u){
  // numerator: prior(o)*truth(o,u)
  var num = o.prior * u.truth(o.out);
  // denominator: sum over all outcomes
  var den = 0;
  for (var oo of outcomes){
    den += oo.prior * u.truth(oo.out);
  }
  return den===0 ? 0 : num/den;
}

// ----- speaker probability for a given utterance -----
function speakerProb(o,u){
  // weight = priorU * (L1prob)^alpha
  var w = priorU(u) * Math.pow(L1prob(o,u), alpha);
  var Z = 0;
  for (var v of utterances){
    Z += priorU(v) * Math.pow(L1prob(o,v), alpha);
  }
  return Z===0 ? 0 : w / Z;
}

// ----- model for the second listener -----
var targetUtter = explanatory[0]; // "Alice won because Bob was lazy"

var model = function(){
  // sample a concrete outcome from the base process
  var o = sample(Categorical({
    ps: outcomes.map(x=>x.prior),
    vs: outcomes.map(x=>x)
  }));
  // weight by the second‑listener's rational update
  var sp = speakerProb(o, targetUtter);
  factor(alpha * Math.log(sp)); // same alpha as in speaker
  return {
    aliceLazy: o.out.aliceLazy,
    aliceStrength: o.out.aliceStrength,
    bobLazy: o.out.bobLazy,
    bobStrength: o.out.bobStrength,
    winner: o.out.winner
  };
};

var ANSWER = Infer({method:'enumerate'}, model);

var ANSWER = Infer({method:'enumerate'}, function() {

  // ---------- Utterances ----------
  var utterances = [
    {name:"Alice won", cost:1, type:"bare"},
    {name:"Bob won", cost:1, type:"bare"},
    {name:"Alice was lazy", cost:1, type:"bare"},
    {name:"Bob was lazy", cost:1, type:"bare"},
    {name:"Alice wasn't lazy", cost:1, type:"bare"},
    {name:"Bob wasn't lazy", cost:1, type:"bare"},
    {name:"Alice is strong", cost:1, type:"bare"},
    {name:"Alice is weak", cost:1, type:"bare"},
    {name:"Bob is strong", cost:1, type:"bare"},
    {name:"Bob is weak", cost:1, type:"bare"},
    {name:"Bob was lazy and Alice won", cost:6, type:"and", fact:"Bob was lazy"},
    {name:"Alice won because Bob was lazy", cost:6, type:"because", fact:"Bob was lazy"},
    {name:"Alice is strong and Alice won", cost:6, type:"and", fact:"Alice is strong"},
    {name:"Alice won because Alice is strong", cost:6, type:"because", fact:"Alice is strong"},
    {name:"Alice wasn't lazy and Alice won", cost:6, type:"and", fact:"Alice wasn't lazy"},
    {name:"Alice won because Alice wasn't lazy", cost:6, type:"because", fact:"Alice wasn't lazy"},
    {name:"Bob was weak and Alice won", cost:6, type:"and", fact:"Bob was weak"},
    {name:"Alice won because Bob was weak", cost:6, type:"because", fact:"Bob was weak"}
  ];

  // prior probability for each utterance
  var sumUttWeight=0;
  utterances.forEach(function(u){
    u.weight=Math.exp(-u.cost);
    sumUttWeight+=u.weight;
  });
  utterances.forEach(function(u){ u.prior=u.weight/sumUttWeight; });

  // ---------- Helper functions ----------
  function isFactTrue(fact, o){
    switch(fact){
      case "Bob was lazy": return o.bobLazy;
      case "Alice was lazy": return o.aliceLazy;
      case "Alice wasn't lazy": return !o.aliceLazy;
      case "Alice is strong": return o.aliceStrength=='strong';
      case "Bob was weak": return o.bobStrength=='weak';
    }
    return false;
  }

  function getTieCoinFromOutcome(o){
    var powA=(o.aliceStrength=='strong'?2:1)*(o.aliceLazy?0.5:1);
    var powB=(o.bobStrength=='strong'?2:1)*(o.bobLazy?0.5:1);
    if(powA!=powB) return false;           // arbitrary, ties not involved
    return o.winner=='Alice';
  }

  function explanatoryProb(fact, o){
    if(o.winner!='Alice') return 0;
    if(!isFactTrue(fact,o)) return 0;

    var actualTie=getTieCoinFromOutcome(o);

    var denom=0, numer=0;
    [true,false].forEach(function(aS){
      [true,false].forEach(function(bS){
        [true,false].forEach(function(aL){
          [true,false].forEach(function(bL){
            [true,false].forEach(function(tie){
              var w=1;
              // Alice strength
              w *= (aS== (o.aliceStrength=='strong')) ? 0.5 : 0.25;
              // Bob strength
              w *= (bS== (o.bobStrength=='strong')) ? 0.5 : 0.25;
              // Alice laziness
              w *= (aL==o.aliceLazy) ? 0.5 : (aL?0.15:0.35);
              // Bob laziness
              w *= (bL==o.bobLazy) ? 0.5 : (bL?0.15:0.35);
              // tie coin
              w *= (tie==actualTie) ? 0.5 : 0.25;

              var powCA=(aS?2:1)*(aL?0.5:1);
              var powCB=(bS?2:1)*(bL?0.5:1);
              var winCF;
              if(powCA>powCB) winCF='Alice';
              else if(powCA<powCB) winCF='Bob';
              else winCF= tie? 'Alice':'Bob';

              if(!bL){ // Bob not lazy
                denom+=w;
                if(winCF!='Alice') numer+=w;
              }
            });
          });
        });
      });
    });
    return denom>0? (numer/denom) : 0;
  }

  // ---------- Enumerate base outcomes ----------
  var boolVals=[true,false];
  var outcomesMap={};
  boolVals.forEach(function(aS){
    boolVals.forEach(function(bS){
      boolVals.forEach(function(aL){
        boolVals.forEach(function(bL){
          boolVals.forEach(function(tie){
            var powA=(aS?2:1)*(aL?0.5:1);
            var powB=(bS?2:1)*(bL?0.5:1);
            var winner;
            if(powA>powB) winner='Alice';
            else if(powA<powB) winner='Bob';
            else winner= tie? 'Alice':'Bob';
            var pr = 0.5*0.5*0.5*0.5; // strengths 0.5 each
            pr *= (aL?0.3:0.7);
            pr *= (bL?0.3:0.7);
            pr *= 0.5; // tie coin

            var key=aS? 'strong':'weak' + "\t" +
                   (bS? 'strong':'weak') + "\t" +
                   aL + "\t" +
                   bL + "\t" +
                   winner;

            var keyStr=(aS? 'strong':'weak')+"\t"+(bS? 'strong':'weak')+"\t"+aL+"\t"+bL+"\t"+winner;
            if(!outcomesMap[keyStr]){
              outcomesMap[keyStr]={
                aliceStrength: aS? 'strong':'weak',
                bobStrength: bS? 'strong':'weak',
                aliceLazy: aL,
                bobLazy: bL,
                winner: winner,
                prior: 0
              };
            }
            outcomesMap[keyStr].prior+=pr;
          });
        });
      });
    });
  });

  var outcomes=Object.values(outcomesMap);

  // ---- Attach actual tie coin used for counterfactuals ----
  outcomes.forEach(function(o){
    o.actualTie = getTieCoinFromOutcome(o);
  });

  // ---- Compute speaker distribution for each outcome ----
  outcomes.forEach(function(o){
    var weightByUtt={};
    var sum=0;
    utterances.forEach(function(u){
      var truth;
      if(u.type=='bare'){
        switch(u.name){
          case "Alice won": truth = (o.winner=='Alice'); break;
          case "Bob won": truth = (o.winner=='Bob'); break;
          case "Alice was lazy": truth = o.aliceLazy; break;
          case "Bob was lazy": truth = o.bobLazy; break;
          case "Alice wasn't lazy": truth = !o.aliceLazy; break;
          case "Bob wasn't lazy": truth = !o.bobLazy; break;
          case "Alice is strong": truth = o.aliceStrength=='strong'; break;
          case "Alice is weak": truth = o.aliceStrength=='weak'; break;
          case "Bob is strong": truth = o.bobStrength=='strong'; break;
          case "Bob is weak": truth = o.bobStrength=='weak'; break;
          default: truth = false;
        }
        truth = truth?1:0;
      } else if(u.type=='and'){
        truth = isFactTrue(u.fact,o) && o.winner=='Alice';
        truth = truth?1:0;
      } else if(u.type=='because'){
        truth = explanatoryProb(u.fact,o); // probability
      }
      var weight = u.prior * Math.pow(truth,5);
      weightByUtt[u.name]=weight;
      sum+=weight;
    });
    var speakerDist={};
    utterances.forEach(function(u){ speakerDist[u.name]=weightByUtt[u.name]/sum; });
    o.speakerDist = speakerDist;
  });

  // ---- Second listener inference ----
  var chosenUtterance = "Alice won because Bob was lazy";
  var totalWeight=0;
  outcomes.forEach(function(o){
    var w = Math.pow(o.speakerDist[chosenUtterance],5) * o.prior;
    o.posteriorWeight = w;
    totalWeight += w;
  });
  outcomes.forEach(function(o){ o.posteriorProb = o.posteriorWeight/totalWeight; });

  // ---- Build distribution to return ----
  var elements = outcomes.map(function(o){
    return {prob: o.posteriorProb, val:{
      aliceLazy: o.aliceLazy,
      aliceStrength: o.aliceStrength,
      bobLazy: o.bobLazy,
      bobStrength: o.bobStrength,
      winner: o.winner
    }};
  });

  return cat(elements);
});

var stickiness = 0.5;
var optimalityParameter = 5;

// Generate an outcome with 5 independent coin flips
var generateOutcome = function() {
  return {
    aliceStrength: flip(0.5) ? "strong" : "weak",
    bobStrength: flip(0.5) ? "strong" : "weak",
    aliceLazy: flip(0.3),
    bobLazy: flip(0.3),
    tiebreaker: flip(0.5)
  };
};

// Calculate pulling power given strength and laziness
var getPullingPower = function(strength, lazy) {
  var base = strength === "strong" ? 2 : 1;
  return lazy ? base / 2 : base;
};

// Determine winner based on pulling powers
var getWinner = function(outcome) {
  var alicePower = getPullingPower(outcome.aliceStrength, outcome.aliceLazy);
  var bobPower = getPullingPower(outcome.bobStrength, outcome.bobLazy);

  if (alicePower > bobPower) {
    return "Alice";
  } else if (bobPower > alicePower) {
    return "Bob";
  } else {
    return outcome.tiebreaker ? "Alice" : "Bob";
  }
};

// Check if a bare claim is true
var isBareClaim = function(claim, outcome, winner) {
  if (claim === "Alice won") return winner === "Alice";
  if (claim === "Bob won") return winner === "Bob";
  if (claim === "Alice was lazy") return outcome.aliceLazy;
  if (claim === "Bob was lazy") return outcome.bobLazy;
  if (claim === "Alice wasn't lazy") return !outcome.aliceLazy;
  if (claim === "Bob wasn't lazy") return !outcome.bobLazy;
  if (claim === "Alice is strong") return outcome.aliceStrength === "strong";
  if (claim === "Alice is weak") return outcome.aliceStrength === "weak";
  if (claim === "Bob is strong") return outcome.bobStrength === "strong";
  if (claim === "Bob is weak") return outcome.bobStrength === "weak";
  return false;
};

// Generate counterfactual with stickiness parameter
var generateCounterfactual = function(actual) {
  return {
    aliceStrength: flip(stickiness) ? actual.aliceStrength : (flip(0.5) ? "strong" : "weak"),
    bobStrength: flip(stickiness) ? actual.bobStrength : (flip(0.5) ? "strong" : "weak"),
    aliceLazy: flip(stickiness) ? actual.aliceLazy : flip(0.3),
    bobLazy: flip(stickiness) ? actual.bobLazy : flip(0.3),
    tiebreaker: flip(stickiness) ? actual.tiebreaker : flip(0.5)
  };
};

// Check if utterance is true
var isUtteranceTrue = function(utterance, actualOutcome, actualWinner) {
  var bareClaims = ["Alice won", "Bob won", "Alice was lazy", "Bob was lazy", 
                    "Alice wasn't lazy", "Bob wasn't lazy", "Alice is strong", 
                    "Alice is weak", "Bob is strong", "Bob is weak"];

  // Bare claims
  if (bareClaims.indexOf(utterance) !== -1) {
    return isBareClaim(utterance, actualOutcome, actualWinner);
  }

  // Plain conjunctions: "[fact] and [outcome]"
  if (utterance.indexOf(" and ") !== -1 && utterance.indexOf(" because ") === -1) {
    var parts = utterance.split(" and ");
    var fact = parts[0];
    var outcome = parts[1];
    return isBareClaim(fact, actualOutcome, actualWinner) && 
           isBareClaim(outcome, actualOutcome, actualWinner);
  }

  // Explanatory: "[outcome] because [fact]"
  if (utterance.indexOf(" because ") !== -1) {
    var parts = utterance.split(" because ");
    var outcome = parts[0];
    var fact = parts[1];

    // Both must be true in actual outcome
    if (!isBareClaim(outcome, actualOutcome, actualWinner)) return false;
    if (!isBareClaim(fact, actualOutcome, actualWinner)) return false;

    // Stochastic check: construct counterfactual
    var cf = generateCounterfactual(actualOutcome);
    var cfWinner = getWinner(cf);

    // If fact is false in counterfactual: utterance is true iff outcome also false
    if (!isBareClaim(fact, cf, cfWinner)) {
      return !isBareClaim(outcome, cf, cfWinner);
    }

    // If fact is true in counterfactual: utterance is false
    return false;
  }

  return false;
};

var allUtterances = [
  "Alice won", "Bob won",
  "Alice was lazy", "Bob was lazy", "Alice wasn't lazy", "Bob wasn't lazy",
  "Alice is strong", "Alice is weak", "Bob is strong", "Bob is weak",
  "Bob was lazy and Alice won", "Alice is strong and Alice won", 
  "Alice wasn't lazy and Alice won", "Bob is weak and Alice won",
  "Alice won because Bob was lazy", "Alice won because Alice is strong",
  "Alice won because Alice wasn't lazy", "Alice won because Bob is weak"
];

var getUtteranceCost = function(utterance) {
  var bareClaims = ["Alice won", "Bob won", "Alice was lazy", "Bob was lazy", 
                    "Alice wasn't lazy", "Bob wasn't lazy", "Alice is strong", 
                    "Alice is weak", "Bob is strong", "Bob is weak"];
  return bareClaims.indexOf(utterance) !== -1 ? 1 : 6;
};

var utterancePrior = function(utterance) {
  return Math.exp(-getUtteranceCost(utterance));
};

// First listener: infers outcome from hearing utterance
var firstListener = function(utterance) {
  return Infer({method: "enumerate"}, function() {
    var outcome = generateOutcome();
    var winner = getWinner(outcome);
    condition(isUtteranceTrue(utterance, outcome, winner));

    return {
      aliceStrength: outcome.aliceStrength,
      bobStrength: outcome.bobStrength,
      aliceLazy: outcome.aliceLazy,
      bobLazy: outcome.bobLazy,
      winner: winner
    };
  });
};

// Speaker: selects utterance given actual outcome
var speaker = function(actualOutcome) {
  var actualWinner = getWinner(actualOutcome);

  return Infer({method: "enumerate"}, function() {
    var utterance = uniformDraw(allUtterances);
    var logPrior = Math.log(utterancePrior(utterance));

    var listenerDist = firstListener(utterance);
    var actualObj = {
      aliceStrength: actualOutcome.aliceStrength,
      bobStrength: actualOutcome.bobStrength,
      aliceLazy: actualOutcome.aliceLazy,
      bobLazy: actualOutcome.bobLazy,
      winner: actualWinner
    };

    var logListenerProb = listenerDist.score(actualObj);
    factor(logPrior + optimalityParameter * logListenerProb);

    return utterance;
  });
};

// Second listener: infers outcome from hearing utterance
var secondListener = function(utterance) {
  return Infer({method: "enumerate"}, function() {
    var outcome = generateOutcome();
    var winner = getWinner(outcome);

    var speakerDist = speaker(outcome);
    var logSpeakerProb = speakerDist.score(utterance);

    factor(optimalityParameter * logSpeakerProb);

    return {
      aliceStrength: outcome.aliceStrength,
      bobStrength: outcome.bobStrength,
      aliceLazy: outcome.aliceLazy,
      bobLazy: outcome.bobLazy,
      winner: winner
    };
  });
};

var ANSWER = secondListener("Alice won because Bob was lazy");

var ANSWER = Infer({
  method: 'enumerate',
  model() {
    // Parameters
    const stickiness = 0.5;
    const optimality = 5;
    const costs = {
      bare: 1,
      paired: 6,
    };

    // Utterances
    const utterances = [
      'Alice won',
      'Bob won',
      'Alice was lazy',
      'Bob was lazy',
      'Alice was not lazy',
      'Bob was not lazy',
      'Alice is strong',
      'Alice is weak',
      'Bob is strong',
      'Bob is weak',
      'Bob was lazy and Alice won',
      'Alice is strong and Alice won',
      'Alice was not lazy and Alice won',
      'Bob was weak and Alice won',
      'Alice won because Bob was lazy',
      'Alice won because Alice is strong',
      'Alice won because Alice was not lazy',
      'Alice won because Bob was weak',
    ];

    // Prior over utterances
    const utterancePrior = utterances.reduce((acc, utterance) => {
      acc[utterance] = Math.exp(-costs[utterances.indexOf(utterance) < 10 ? 'bare' : 'paired']);
      return acc;
    }, {});

    // Normalize prior
    const utterancePriorTotal = Object.values(utterancePrior).reduce((acc, val) => acc + val, 0);
    Object.keys(utterancePrior).forEach((utterance) => {
      utterancePrior[utterance] /= utterancePriorTotal;
    });

    // Outcome structure
    const outcome = {
      aliceLazy: flip(0.3),
      aliceStrength: categorical({ strong: 0.5, weak: 0.5 }),
      bobLazy: flip(0.3),
      bobStrength: categorical({ strong: 0.5, weak: 0.5 }),
      tieBreakingCoin: flip(0.5),
    };

    // Simulate the game
    outcome.winner = function() {
      const alicePullingPower = (this.aliceStrength === 'strong' ? 2 : 1) * (this.aliceLazy ? 0.5 : 1);
      const bobPullingPower = (this.bobStrength === 'strong' ? 2 : 1) * (this.bobLazy ? 0.5 : 1);
      if (alicePullingPower > bobPullingPower) return 'Alice';
      if (alicePullingPower < bobPullingPower) return 'Bob';
      return this.tieBreakingCoin ? 'Alice' : 'Bob';
    };

    // First listener's probability of the actual outcome given an utterance
    const firstListenerProbability = (outcome, utterance) => {
      if (utterance === 'Alice won') return outcome.winner() === 'Alice';
      if (utterance === 'Bob won') return outcome.winner() === 'Bob';
      if (utterance === 'Alice was lazy') return outcome.aliceLazy;
      if (utterance === 'Bob was lazy') return outcome.bobLazy;
      if (utterance === 'Alice was not lazy') return !outcome.aliceLazy;
      if (utterance === 'Bob was not lazy') return !outcome.bobLazy;
      if (utterance === 'Alice is strong') return outcome.aliceStrength === 'strong';
      if (utterance === 'Alice is weak') return outcome.aliceStrength === 'weak';
      if (utterance === 'Bob is strong') return outcome.bobStrength === 'strong';
      if (utterance === 'Bob is weak') return outcome.bobStrength === 'weak';
      if (utterance === 'Bob was lazy and Alice won') return outcome.bobLazy && outcome.winner() === 'Alice';
      if (utterance === 'Alice is strong and Alice won') return outcome.aliceStrength === 'strong' && outcome.winner() === 'Alice';
      if (utterance === 'Alice was not lazy and Alice won') return !outcome.aliceLazy && outcome.winner() === 'Alice';
      if (utterance === 'Bob was weak and Alice won') return outcome.bobStrength === 'weak' && outcome.winner() === 'Alice';
      if (utterance.startsWith('Alice won because ')) {
        const fact = utterance.replace('Alice won because ', '');
        if (fact === 'Bob was lazy') return (
          outcome.bobLazy &&
          outcome.winner() === 'Alice' &&
          (flip(stickiness) ?
            true :
            (!outcome.bobLazy && outcome.winner() !== 'Alice'))
        );
        if (fact === 'Alice is strong') return (
          outcome.aliceStrength === 'strong' &&
          outcome.winner() === 'Alice' &&
          (flip(stickiness) ?
            true :
            (outcome.aliceStrength !== 'strong' && outcome.winner() !== 'Alice'))
        );
        if (fact === 'Alice was not lazy') return (
          !outcome.aliceLazy &&
          outcome.winner() === 'Alice' &&
          (flip(stickiness) ?
            true :
            (outcome.aliceLazy && outcome.winner() !== 'Alice'))
        );
        if (fact === 'Bob was weak') return (
          outcome.bobStrength === 'weak' &&
          outcome.winner() === 'Alice' &&
          (flip(stickiness) ?
            true :
            (outcome.bobStrength !== 'weak' && outcome.winner() !== 'Alice'))
        );
      }
      return false;
    };

    // Speaker's probability of an utterance given the actual outcome
    const speakerProbability = (outcome, utterance) => {
      const firstListenerProb = firstListenerProbability(outcome, utterance);
      return Math.pow(firstListenerProb, optimality) * utterancePrior[utterance];
    };

    // Second listener's probability of the actual outcome given an utterance
    const secondListenerProbability = (outcome, utterance) => {
      const speakerProb = speakerProbability(outcome, utterance);
      return Math.pow(speakerProb, optimality);
    };

    // Sample an outcome
    const sampleOutcome = () => ({
      aliceLazy: flip(0.3),
      aliceStrength: categorical({ strong: 0.5, weak: 0.5 }),
      bobLazy: flip(0.3),
      bobStrength: categorical({ strong: 0.5, weak: 0.5 }),
      tieBreakingCoin: flip(0.5),
      winner: function() {
        const alicePullingPower = (this.aliceStrength === 'strong' ? 2 : 1) * (this.aliceLazy ? 0.5 : 1);
        const bobPullingPower = (this.bobStrength === 'strong' ? 2 : 1) * (this.bobLazy ? 0.5 : 1);
        if (alicePullingPower > bobPullingPower) return 'Alice';
        if (alicePullingPower < bobPullingPower) return 'Bob';
        return this.tieBreakingCoin ? 'Alice' : 'Bob';
      },
    });

    // Utterance of interest
    const utteranceOfInterest = 'Alice won because Bob was lazy';

    // Normalize second listener's probability
    let normalizationConstant = 0;
    const outcomes = [];
    for (let aliceLazy = 0; aliceLazy < 2; aliceLazy++) {
      for (let aliceStrength in { strong: 0, weak: 1 }) {
        for (let bobLazy = 0; bobLazy < 2; bobLazy++) {
          for (let bobStrength in { strong: 0, weak: 1 }) {
            for (let tieBreakingCoin = 0; tieBreakingCoin < 2; tieBreakingCoin++) {
              const outcome = {
                aliceLazy: aliceLazy === 1,
                aliceStrength,
                bobLazy: bobLazy === 1,
                bobStrength,
                tieBreakingCoin: tieBreakingCoin === 1,
                winner: function() {
                  const alicePullingPower = (this.aliceStrength === 'strong' ? 2 : 1) * (this.aliceLazy ? 0.5 : 1);
                  const bobPullingPower = (this.bobStrength === 'strong' ? 2 : 1) * (this.bobLazy ? 0.5 : 1);
                  if (alicePullingPower > bobPullingPower) return 'Alice';
                  if (alicePullingPower < bobPullingPower) return 'Bob';
                  return this.tieBreakingCoin ? 'Alice' : 'Bob';
                },
              };
              const prob = secondListenerProbability(outcome, utteranceOfInterest);
              normalizationConstant += prob;
              outcomes.push({ outcome, prob });
            }
          }
        }
      }
    }

    // Return the distribution
    const distribution = outcomes.reduce((acc, { outcome, prob }) => {
      acc.push({ ...outcome, prob: prob / normalizationConstant });
      return acc;
    }, []);
    return distribution;
  },
});

// ---------- helpers ----------
var range = function(n){ return n === 0 ? [] : range(n-1).concat([n-1]); };

var alpha = 5;
var stick = 0.5;

var winnerOf = function(as, bs, al, bl, coin){
  var pa = (as ? 2 : 1) * (al ? 0.5 : 1);
  var pb = (bs ? 2 : 1) * (bl ? 0.5 : 1);
  return pa > pb ? 'alice' : (pb > pa ? 'bob' : (coin ? 'alice' : 'bob'));
};

// ---------- state space (32 full outcomes incl. tie-break coin) ----------
var states = map(function(i){
  var as   = (Math.floor(i/16) % 2) === 1;
  var bs   = (Math.floor(i/8)  % 2) === 1;
  var al   = (Math.floor(i/4)  % 2) === 1;
  var bl   = (Math.floor(i/2)  % 2) === 1;
  var coin = (i % 2) === 1;
  return {as: as, bs: bs, al: al, bl: bl, coin: coin,
          winner: winnerOf(as, bs, al, bl, coin)};
}, range(32));

var statePrior = function(s){
  return 0.5 * 0.5 * (s.al ? 0.3 : 0.7) * (s.bl ? 0.3 : 0.7) * 0.5;
};

// ---------- facts used in paired utterances ----------
var factFns = [
