    let ap = pullingPower(aliceStrong ? "strong" : "weak", aliceLazy);
    let bp = pullingPower(bobStrong ? "strong" : "weak", bobLazy);
    let winner = (ap > bp) ? "Alice" : (bp > ap) ? "Bob" : (tieBreaker ? "Alice" : "Bob");

    // Utterance: "Alice won because Bob was lazy" (explanatory)
    // Check if base facts hold in actual outcome
    let aliceWonActual = winner === "Alice";
    let bobLazyActual = bobLazy; // true if Billy was lazy

    // Explanatory utterance requires:
    // 1. Both fact (Bob was lazy) and outcome (Alice won) hold in actual
    // 2. Counterfactual construction where fact is false leads to Alice not winning
