    if (aliceWonActual && bobLazyActual) {
      // Generate counterfactual outcome by resampling with stickiness
      let cfAAS = flip(STICKINESS) ? (aliceStrong ? "strong" : "weak") : (flip(0.5) ? "strong" : "weak");
      let cfBBS = flip(STICKINESS) ? (bobStrong ? "strong" : "weak") : (flip(0.5) ? "strong" : "weak");
      let cfAAL = flip(STICKINESS) ? (aliceLazy ? "lazy" : "not lazy") : (flip(0.3) ? "lazy" : "not lazy");
      let cfBBL = flip(STICKINESS) ? (bobLazy ? "lazy" : "not lazy") : (flip(0.3) ? "lazy" : "not lazy");
      let cfTB = flip(STICKINESS) ? tieBreaker : (flip(0.5) ? true : false);

      let cfAp = pullingPower(cfAAS, cfAAL);
      let cfBp = pullingPower(cfBBS, cfBBL);
      let cfWinner = (cfAp > cfBp) ? "Alice" : (cfBp > cfAp) ? "Bob" : (cfTB ? "Alice" : "Bob");

