    var w2 = (1 - x <= 0) ? (exp2 <= 0 ? 1 : 0) : Math.pow(1 - x, exp2);
    return w1 * w2;
  }, xs);
  var total = sum(weights);
  var probs = map(function(w) { return w / total; }, weights);
  return Categorical({vs: integers, ps: probs});
};

var dDist = discretizedBeta(alpha, betaParam);
var nDist1 = discretizedBeta(1 - alpha, betaParam);
var nDist2 = discretizedBeta(0.1, gammaParam);

// Mixture N distribution
var nProbs = map(function(n) {
  return 0.2 * Math.exp(nDist1.score(n)) + 0.8 * Math.exp(nDist2.score(n));
}, integers);
var nDist = Categorical({vs: integers, ps: nProbs});

