var isTrue = function(utterance, N, D, reading) {
  if (utterance === null) {
    return true;
  }
  var T = utterance;
  var totalDur = N * D;
  if (reading === "episodic") {
    return (totalDur >= T) && (N === 1);
  } else {
    return (totalDur >= T) && (N > 1);
  }
};

var uttCost = function(T) { return T === null ? 2 : 1; };

var literalListener = cache(function(T, reading) {
  return Infer({method: 'enumerate'}, function() {
    var N = sample(nDist);
    var D = sample(dDist);
    condition(isTrue(T, N, D, reading));
    return {N: N, D: D};
  });
});

