var speaker = cache(function(reading, N, D) {
  return Infer({method: 'enumerate'}, function() {
    var T = flip(0.95) ? uniformDraw(timeframes) : null;
    var ll = literalListener(T, reading);
    var sc = ll.score({N: N, D: D});
    factor(speakerOptimality * sc - uttCost(T));
    return T;
  });
});

