function semTrue(u, n) {
  if (u === "Some") return n >= 1;
  if (u === "All")  return n === 15;
  if (u === "None") return n === 0;
  return false;
}

// Literal listener L0: given an utterance, returns a distribution over (wonky, n)
function literalListener(utter) {
  return Infer({method: 'enumerate'}, function () {
    var wonky = flip(0.5);
    var p = wonky ? 0.5 : 0.99;
    var n = sample(Binomial({n: 15, p: p}));
    // condition on utterance being literally true
    factor(semTrue(utter, n) ? 0 : -Infinity);
    return {wonky: wonky, n: n};
  });
}

// Speaker S1: knows the true world (wonky, n) and chooses an utterance
function speaker(world) {
  var utterances = ["Some", "All", "None"];
  var weights = utterances.map(function (u) {
    var dist = literalListener(u);               // L0 distribution given u
    var logp = dist.score(world);                // log probability of this world under L0|u
    return Math.exp(logp);                       // unnormalized weight
  });
  var total = weights.reduce(function (a, b) { return a + b; }, 0);
  var probs = weights.map(function (w) { return w / total; });
  return categoricalDraw(utterances, probs);    // sample an utterance
}

// Pragmatic listener PL: conditions on hearing "Some"
function pragmaticModel() {
  var wonky = flip(0.5);
  var p = wonky ? 0.5 : 0.99;
  var n = sample(Binomial({n: 15, p: p}));
  var utter = speaker({wonky: wonky, n: n});
  factor(utter === "Some" ? 0 : -Infinity);    // observed utterance
  var n_next = sample(Binomial({n: 15, p: wonky ? 0.5 : 0.99}));
  return {wonky: wonky, n: n, n_next: n_next};
}

