// Define the speaker
function speaker(world_state, regime, utterance) {
  var literal_prob = literalListener(utterance, world_state, regime);
  var utility = 0;
  if (regime === "wonky") {
    for (var i = 0; i <= 15; i++) {
      utility += Math.pow(1, 1) * literalListener(utterance, i, regime) * binomialPMF(i, 15, 0.5);
    }
  } else if (regime === "normal") {
    for (var i = 0; i <= 15; i++) {
      utility += Math.pow(1, 1) * literalListener(utterance, i, regime) * binomialPMF(i, 15, 0.99);
    }
  }
  return literal_prob * utility;
}

// Define the observation model
function observe(utterance) {
  return utterance === "Some" ? 1 : 0;
