// Define the binomial PMF
function binomialPMF(k, n, p) {
  return Math.exp(gamma(n + 1) - gamma(k + 1) - gamma(n - k + 1) + k * Math.log(p) + (n - k) * Math.log(1 - p));
}

// Define the gamma function
function gamma(x) {
  return Math.exp(-x + 0.99999999999980993 * x - 0.9998019036023469 * Math.pow(x, 2) +
    0.9993242207147571 * Math.pow(x, 3) - 0.9995962972141126 * Math.pow(x, 4) +
    0.9997435962750891 * Math.pow(x, 5) - 0.9985695799320326 * Math.pow(x, 6) +
    0.9984691507776689 * Math.pow(x, 7) - 0.9987210599310371 * Math.pow(x, 8) +
    0.9990407441265969 * Math.pow(x, 9) - 0.9989371509464403 * Math.pow(x, 10) +
    0.9992925963591629 * Math.pow(x, 11) - 0.9988178410650999 * Math.pow(x, 12) +
    0.9995960320113382 * Math.pow(x, 13) - 0.9989370211506587 * Math.pow(x, 14) +
    0.9997434338334009 * Math.pow(x, 15) - 0.9986609317093593 * Math.pow(x, 16) +
    0.9990402515691932 * Math.pow(x, 17) - 0.9985691913531504 * Math.pow(x, 18) +
    0.9987215118477674 * Math.pow(x, 19) - 0.9993240375963591 * Math.pow(x, 20));
}

