// Sweater price bins and prior probabilities
var priceBins = [1.5, 4.5, 7.5, 10.5, 13.5, 16.5];
var pricePrior = [0.00482838499944466, 0.00832934578733181, 0.0112952500492109,
                 0.0173774790108894, 0.0232006658974883, 0.0258422772579257];

// Parameters
var alpha = 2;
var cost = {expensive: 1, "not-inexpensive": 2};

// Soft semantics
var softProb = function(utt, price, thetaExp, thetaInexp) {
  if (utt === "expensive") {
    return price > thetaExp ? 0.9999 : 0.0001;
  } else { // not-inexpensive
    return price >= thetaInexp ? 0.9999 : 0.0001;
  }
};

// Normalising constant Z for an utterance given thresholds
var Zvalue = function(utt, thetaExp, thetaInexp) {
  var sum = 0;
  for (var i = 0; i < priceBins.length; i++) {
    sum += softProb(utt, priceBins[i], thetaExp, thetaInexp);
  }
  return sum;
};

// Speaker probability of emitting a particular utterance
var speakerProb = function(utt, price, thetaExp, thetaInexp) {
  var utts = ["expensive", "not-inexpensive"];
  var weights = {};
  for (var i = 0; i < utts.length; i++) {
    var u = utts[i];
    var sp = softProb(u, price, thetaExp, thetaInexp);
    var Z = Zvalue(u, thetaExp, thetaInexp);
    var logL = Math.log(sp) - Math.log(Z);          // literal listener log‑prob
    var w = Math.exp(alpha * (logL - cost[u]));    // unnormalised weight
    weights[u] = w;
  }
  var total = weights["expensive"] + weights["not-inexpensive"];
  return weights[utt] / total;
};

// Pragmatic listener model for a given heard utterance
var pragmaticListener = function(heardUtt) {
  // price from sweater prior
  var price = categorical({ps: pricePrior, vs: priceBins});

  // theta_expensive ~ uniform over bins
  var thetaExp = uniformDraw(priceBins);

  // theta_inexpensive correlation
  var same = flip(0.8);
  var thetaInexp = same ? thetaExp : uniformDraw(priceBins);

  // condition on speaker having produced heardUtt
  factor(Math.log(speakerProb(heardUtt, price, thetaExp, thetaInexp)));
  return price;
};

// Inference for 'expensive'
