  // Priors
  target += uniform_lpdf(omega | 0, 1);
  target += uniform_lpdf(p | 0, 1);

  // Likelihood
  for (i in 1:M) {
    bool zero_history = true;
    for (t in 1:T) {
      if (y[i, t] == 1)
        zero_history = false;
    }

    if (!zero_history) {
      // At least one capture: individual is certainly real
      for (t in 1:T)
        target += bernoulli_lpmf(y[i, t] | p);
    } else {
      // All zeros: mixture of real (never detected) and phantom
      target += log1m(omega) + log1m(p) * T; // real but never detected
      target += log1m(log1m(omega)) - log1m(omega) - log1m(p) * T; // phantom part
      // Equivalent to log(1 - omega + omega * (1 - p)^T)
      // but written with log-sum-exp to improve numeric stability
      target += log_sum_exp(
        log(1 - omega),
        log(omega) + T * log1m(p)
