      zero_count += y[i, t];
    }
    int all_zero = (zero_count == 0) ? 1 : 0;
    target += log_sum_exp(log(omega) + log(L_real),
                          log1m(omega) + (all_zero ? 0 : negative_infinity()));
  }
}

