  int<lower=0> M;                                   // Size of augmented data set
  int<lower=0> T;                                   // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y;              // Capture-history matrix
}

parameters {
  real<lower=0, upper=1> omega;                     // Inclusion probability
  vector<lower=0, upper=1>[T] p;                    // Occasion‑specific detection probs
  int<lower=0, upper=M> N;                          // Total population size
}

transformed_parameters {
  real<lower=0, upper=1> pr;                         // Prob. of never being captured
  real<lower=0, upper=1> omega_nd;                  // Prob. of presence given never detected

  pr = 1;
  for (t in 1:T)
    pr *= 1 - p[t];
  omega_nd = omega * pr / (omega * pr + (1 - omega));
}

model {
  // Prior for N
  target += binomial_lpmf(N | M, omega);

  for (i in 1:M) {
    real detect_prob = 1;
    int captured = 0;
    for (t in 1:T) {
      if (y[i, t] == 1) {
        detect_prob *= p[t];
        captured += 1;
      } else {
        detect_prob *= 1 - p[t];
      }
    }

    if (captured == 0) {
      // All zeros: include phantom possibility
      real weight = omega * detect_prob + (1 - omega);
      target += log(weight);
    } else {
      // Any capture: phantom cannot have contributed
      target += log(omega * detect_prob);
    }
  }
}

