  array[T] real<lower=0, upper=1> p;
}

transformed parameters {
  // Probability of never being captured given presence
  real pr = 1.0;
  for (t in 1:T) {
    pr *= (1 - p[t]);
  }

  // Probability of being present given never detected
  real omega_nd = omega * pr / (omega * pr + (1 - omega));

  // Estimated total population size
  real N;
  {
    int n_captured = 0;
    int n_not_captured = 0;

    for (i in 1:M) {
      int any_capture = 0;
      for (t in 1:T) {
        if (y[i, t] == 1) {
          any_capture = 1;
        }
      }
      if (any_capture == 1) {
        n_captured += 1;
      } else {
        n_not_captured += 1;
      }
    }

    // N = observed individuals with captures + expected real individuals among those never captured
    N = n_captured + n_not_captured * omega_nd;
  }
}

model {
  // Implicit Uniform(0, 1) priors for omega and p[t]

  // Likelihood with marginalized membership indicator
  for (i in 1:M) {
    int any_capture = 0;

    // Check if individual has any captures
    for (t in 1:T) {
      if (y[i, t] == 1) {
        any_capture = 1;
      }
    }

    if (any_capture == 1) {
      // Individual was captured: must be real with probability omega
      target += log(omega);
      for (t in 1:T) {
        target += y[i, t] * log(p[t]) + (1 - y[i, t]) * log(1 - p[t]);
      }
    } else {
      // Individual never captured: mixture of real (prob omega, never detected) and phantom (prob 1-omega)
      target += log_sum_exp(log(omega) + log(pr), log(1 - omega));
    }
  }
}

