  // Prior for omega and p
  target += uniform_lpdf(omega | 0, 1);
  target += uniform_lpdf(p[1] | 0, 1);
  target += uniform_lpdf(p[2] | 0, 1);
  target += uniform_lpdf(p[3] | 0, 1);

  // Likelihood
  for (i in 1:M) {
    real pr_i = 1;
    for (t in 1:T) {
      if (y[i, t] == 0) {
        pr_i *= (1 - p[t]);
      } else {
        pr_i *= p[t];
      }
    }

    target += log_mix(omega,
                       bernoulli_lpmf(0 | pr_i),
                       bernoulli_lpmf(1 | 1));
  }
}

