  // Marginalize over n using log_sum_exp for numerical stability
  vector[nmax - n_min + 1] log_contributions;
  for (i in 1:(nmax - n_min + 1)) {
    int n = n_min + i - 1;

    // Log uniform prior on n
    real log_prior_n = -log(nmax - n_min + 1);

    // Log likelihood: sum of binomial log pmfs across all occasions
    real log_lik = 0;
    for (j in 1:m) {
      log_lik += binomial_lpmf(k[j] | n, theta);
