model {
  real log_lik_sum = 0;
  int first = 1;
  for (n in n_min:nmax) {
    real log_p = 0;
    for (j in 1:m) {
      log_p += log(dbinom(k[j], n, theta));
    }
    if (first) {
      log_lik_sum = log_p;
      first = 0;
    } else {
      log_lik_sum = log_sum_exp(log_lik_sum, log_p);
    }
  }
