      int g = grade[i, j];
      if (g == -1) continue;               // missing observation
      int K = ncat[j];                      // number of categories for indicator j
      // cumulative probabilities Q_{j,k}
      vector[K - 1] Q;
      for (k in 1:(K - 1)) {
        Q[k] = inv_logit(delta[j] * (theta[i] - gamma[j, k]));
      }
      real prob;
      if (g == 1) {
        prob = 1 - Q[1];
      } else if (g == K) {
        prob = Q[K - 1];
      } else {
        prob = Q[g - 1] - Q[g];
      }
      target += log(prob);
    }
  }
}

