  // Prior on latent skeletal ages
  theta ~ normal(0, 36);

  // Likelihood
  for (i in 1:nChild) {
    for (j in 1:nInd) {
      if (grade[i, j] > 0) {
        // Non-missing observation
        int g = grade[i, j];
        int ncat_j = ncat[j];
        real delta_j = delta[j];
        real theta_i = theta[i];

        vector[ncat_j] probs;

        // Calculate category probabilities from cumulative probabilities
        if (ncat_j == 1) {
          probs[1] = 1.0;
        } else {
          for (k in 1:ncat_j) {
            if (k == 1) {
              // P(grade = 1) = 1 - Q_{j,1}
              real Q1 = inv_logit(delta_j * (theta_i - gamma[j, 1]));
              probs[1] = 1.0 - Q1;
            } else if (k < ncat_j) {
              // P(grade = k) = Q_{j,k-1} - Q_{j,k}
              real Q_prev = inv_logit(delta_j * (theta_i - gamma[j, k - 1]));
              real Q_k = inv_logit(delta_j * (theta_i - gamma[j, k]));
              probs[k] = Q_prev - Q_k;
            } else {
              // P(grade = ncat_j) = Q_{j,ncat_j-1}
              real Q_last = inv_logit(delta_j * (theta_i - gamma[j, ncat_j - 1]));
              probs[ncat_j] = Q_last;
            }
          }
        }

        grade[i, j] ~ categorical(probs);
      }
    }
  }
}

