  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}

parameters {
  vector[nChild] theta;
}

model {
  // Prior for latent skeletal ages
  theta ~ normal(0, 36);

  // Likelihood for each child and indicator combination
  for (i in 1:nChild) {
    for (j in 1:nInd) {
      if (grade[i, j] == -1) next;

      // Calculate Q values (cumulative probabilities at each threshold)
      // Q[k] = inv_logit(delta[j] * (theta[i] - gamma[j,k]))

      real Q[ncat[j] - 1];

      for (k in 1:ncat[j] - 1) {
        if (gamma[j, k] != -1) {
          Q[k] = inv_logit(delta[j] * (theta[i] - gamma[j, k]));
        } else {
          // If threshold missing, use default cumulative probability 0.5
          Q[k] = 0.5;
        }
      }

      // Derive categorical probabilities
      real categorical_probs[ncat[j]};

      // P(grade = 1) = 1 - Q[1]
      categorical_probs[1] = 1 - Q[1];

      for (k in 2:ncat[j] - 1) {
        // P(grade = k) = Q[k-1] - Q[k]
        categorical_probs[k] = Q[k - 1] - Q[k];
      }

      // P(grade = ncat_j) = Q[ncat_j - 1]
      categorical_probs[ncat[j]] = Q[ncat[j] - 1];

      grade[i, j] ~ categorical(categorical_probs);
    }
  }
