      // Skip missing observations
      if (grade[i, j] != -1) {
        int g = grade[i, j];
        int K = ncat[j];

        // If only one category, log-prob contribution is 0
        if (K >= 2) {
          real log_prob;

          if (g == 1) {
            // P(grade = 1) = 1 - Q[j,1]
            real Q1 = inv_logit(delta[j] * (theta[i] - gamma[j, 1]));
            log_prob = log1m(Q1);
          } else if (g == K) {
            // P(grade = K) = Q[j, K-1]
            real QK = inv_logit(delta[j] * (theta[i] - gamma[j, K - 1]));
            log_prob = log(QK);
          } else {
            // P(grade = g) = Q[j, g-1] - Q[j, g]  for 2 <= g <= K-1
            real Q_prev = inv_logit(delta[j] * (theta[i] - gamma[j, g - 1]));
            real Q_curr = inv_logit(delta[j] * (theta[i] - gamma[j, g]));
            log_prob = log(Q_prev - Q_curr);
          }

          target += log_prob;
        }
      }
    }
  }
}

