data {
  int<lower=0> T;
  array[T] real y;
  real<lower=0> sigma1;
}
parameters {
  real mu;
  real<lower=0> alpha0;
  real<lower=0, upper=1> alpha1;
  real<lower=0, upper=1> beta1;
}
transformed parameters {
  vector[T] sigma;
  sigma[1] = sigma1;
  for (t in 2:T) {
    sigma[t] = sqrt(alpha0
                    + alpha1 * square(y[t - 1] - mu)
                    + beta1 * square(sigma[t - 1]));
  }
}
model {
  // enforce the restriction beta1 <= 1 - alpha1
  if (beta1 > 1 - alpha1)
    reject("beta1 + alpha1 must be <= 1");

  // likelihood for all observations
  y[1] ~ normal(mu, sigma[1]);
  for (t in 2:T) {
    y[t] ~ normal(mu, sigma[t]);
  }
}

data {
  int<lower=0> T;
  array[T] real y;
  real<lower=0> sigma1;
}

parameters {
  real mu;
  real<lower=0> alpha0;
  real<lower=0, upper=1> alpha1;
  real<lower=0, upper=1> beta_raw;
}

transformed parameters {
  real<lower=0, upper=1 - alpha1> beta1;
  beta1 = beta_raw * (1 - alpha1);
}

model {
  vector[T] sigma;
  sigma[1] = sigma1;
  for (t in 2:T) {
    sigma[t] = sqrt(alpha0 + alpha1 * square(y[t-1] - mu) + beta1 * square(sigma[t-1]));
  }
  for (t in 1:T) {
    target += normal_lpdf(y[t] | mu, sigma[t]);
  }
}

data {
  int<lower=0> T;
  array[T] real y;
  real<lower=0> sigma1;
}

parameters {
  real mu;
  real<lower=0> alpha0;
  real<lower=0, upper=1> alpha1;
  real<lower=0, upper=1-alpha1> beta1;
}

model {
  // GARCH(1,1) model with conditional heteroscedasticity
  vector[T] sigma;
  sigma[1] = sigma1;

  // Likelihood contributions
  y[1] ~ normal(mu, sigma[1]);

  for (t in 2:T) {
    // Conditional standard deviation recursion
    sigma[t] = sqrt(alpha0 + alpha1 * square(y[t-1] - mu) + beta1 * square(sigma[t-1]));

    // Observation distribution
    y[t] ~ normal(mu, sigma[t]);
  }
}

data {
  int<lower=0> T;
  array[T] real y;
  real<lower=0> sigma1;
}

parameters {
  real mu;
  real<lower=0> alpha0;
  real<lower=0, upper=1> alpha1;
  real<lower=0, upper=1 - alpha1> beta1;
}

model {
  array[T] real sigma;

  sigma[1] = sigma1;

  for (t in 2:T) {
    sigma[t] = sqrt(alpha0 + alpha1 * pow(y[t - 1] - mu, 2) + beta1 * pow(sigma[t - 1], 2));
  }

  for (t in 1:T) {
    y[t] ~ normal(mu, sigma[t]);
  }
}

