data {
  int<lower=0> T;
  array[T] real y;
  real<lower=0> sigma1;
}
parameters {
  real mu;
  real<lower=0> alpha0;
  real<lower=0, upper=1> alpha1;
  real<lower=0, upper=(1 - alpha1)> beta1;
}
transformed parameters {
  array[T] real<lower=0> sigma;
  sigma[1] = sigma1;
  for (t in 2:T) {
    sigma[t] = sqrt(alpha0 + alpha1 * pow(y[t-1] - mu, 2) + beta1 * pow(sigma[t-1], 2));
  }
}
model {
  // Priors (flat improper uniforms implied by constraints)
  // mu: improper uniform over reals
  // alpha0: improper uniform over (0, inf)
  // alpha1: improper uniform over [0, 1]
  // beta1: improper uniform over [0, 1 - alpha1]

  // Likelihood
  for (t in 1:T) {
    y[t] ~ normal(mu, sigma[t]);
  }
}

data {
  int<lower=0> T;
  array[T] real y;
  real<lower=0> sigma1;
}
parameters {
  real mu;
  real<lower=0> alpha0;
  real<lower=0, upper=1> alpha1;
  real<lower=0, upper=1> u_beta;
}
transformed parameters {
  real beta1 = u_beta * (1 - alpha1);
}
model {
  // Flat improper priors
  // Priors are implicitly uniform within constraints

  // Likelihood for time 1
  // Sigma at time 1 is fixed at sigma1
  target += normal_lpdf(y[1] | mu, sigma1);

  // GARCH(1,1) state and likelihood
  // Iterate from t=2 to T
  real sigma_prev = sigma1; // sigma[t-1]
  for (t in 2:T) {
    real eps = y[t-1] - mu;
    real sigma_sq_prev = sigma_prev * sigma_prev;
    // sigma[t] recursive formula
    real sigma_curr = sqrt(alpha0 + alpha1 * eps * eps + beta1 * sigma_sq_prev);

    // Add likelihood for y[t]
    target += normal_lpdf(y[t] | mu, sigma_curr);

    // Update sigma_prev for next iteration
    sigma_prev = sigma_curr;
  }
}
// Note: u_beta is an auxiliary parameter introduced to enforce
// the constraint beta1 <= 1 - alpha1 with a flat prior on beta1.
// beta1 is exposed as the quantity of interest.
// The names mu, alpha0, alpha1, beta1 are available in the output.

data {
  int<lower=0> T;
  array[T] real y;
  real<lower=0> sigma1;
}

parameters {
  real mu;
  real<lower=0> alpha0;
  real<lower=0, upper=1> alpha1;
  real<lower=0, upper=1 - alpha1> beta1;
}

transformed parameters {
  vector[T] sigma;
  sigma[1] = sigma1;
  for (t in 2:T) {
    sigma[t] = sqrt(alpha0 + alpha1 * square(y[t-1] - mu) + beta1 * square(sigma[t-1]));
  }
}

model {
  // flat improper priors on all parameters (no explicit prior statements)
  for (t in 1:T) {
    y[t] ~ normal(mu, sigma[t]);
  }
}

data {
  int<lower=1> N;
  array[N] real x;
  array[N] int k;
}
parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  vector[N] f;
}
model {
  // Priors on hyperparameters
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2) T[0,];  // half‑normal

  // Squared‑exponential covariance matrix
  matrix[N, N] K;
  for (i in 1:N) {
    for (j in i:N) {
      K[i, j] = square(alpha) * exp(-0.5 * square((x[i] - x[j]) / rho));
      if (i != j)
        K[j, i] = K[i, j];
    }
    // jitter for numerical stability
    K[i, i] = K[i, i] + 1e-6;
  }

  // GP prior on latent function values
  f ~ multi_normal(rep_vector(0, N), K);

  // Poisson likelihood with log‑link
  for (i in 1:N) {
    k[i] ~ poisson_log(f[i]);
  }
}

data {
  int<lower=1> N;
  array[N] real x;
  array[N] int k;
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  vector[N] f;
}

model {
  matrix[N,N] K;
  for (i in 1:N) {
    for (j in i:N) {
      real d   = x[i] - x[j];
      real val = alpha * alpha * exp(-0.5 * square(d / rho));
      K[i, j] = val;
      K[j, i] = val;  // symmetry
    }
  }

  // GP prior on latent values
  f ~ multi_normal(rep_vector(0., N), K);

  // Poisson likelihood
  k ~ poisson_log(f);

  // Hyperparameter priors
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2);  // truncated on alpha > 0 by parameter constraint
}

data {
  int<lower=1> N;
  array[N] real x;
  array[N] int k;
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  vector[N] f;
}

model {
  // Priors
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2);

  // Compute squared exponential covariance matrix
  matrix[N, N] K;
  for (i in 1:N) {
    for (j in i:N) {
      K[i, j] = alpha^2 * exp(-(x[i] - x[j])^2 / (2.0 * rho^2));
      if (i != j) K[j, i] = K[i, j];
    }
    K[i, i] = K[i, i] + 1e-9;
  }

  // Cholesky decomposition for numerical stability
  matrix[N, N] L_K = cholesky_decompose(K);

  // Gaussian process prior
  f ~ multi_normal_cholesky(rep_vector(0, N), L_K);

  // Poisson likelihood with log-link
  k ~ poisson_log(f);
}

data {
  int<lower=1> N;
  array[N] real x;
  array[N] int k;
}

transformed data {
  cov_matrix[N] K;
  for (i in 1:N) {
    K[i, i] = 1;
  }
  for (i in 1:N) {
    for (j in 1:N) {
      if (i != j) {
        K[i, j] = exp(-0.5 * (x[i] - x[j]) * (x[i] - x[j]));
      }
    }
  }
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  vector[N] f;
}

transformed parameters {
  real f1 = f[1];
  real f2 = f[2];
  real f3 = f[3];
  real f4 = f[4];
  real f5 = f[5];
  real f6 = f[6];
  real f7 = f[7];
  real f8 = f[8];
  real f9 = f[9];
  real f10 = f[10];
  real f11 = f[11];
}

model {
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2) T[0,];
  {
    matrix[N, N] L_K;
    L_K = cholesky_decompose(alpha * K);
    f ~ multi_normal_cholesky(rep_vector(0, N), L_K);
  }
  for (i in 1:N) {
    k[i] ~ poisson_log(exp(f[i]));
  }
}

data {
