data {
  int<lower=1> N;
  array[N] real x;
  array[N] int k;
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  array[N] real f;
}

model {
  // Priors
  rho ~ gamma(25, 4);
  alpha ~ half_normal(2.0);

  // Build Gaussian process covariance matrix using exponential-quadratic kernel
  matrix[N, N] Sigma;
  for (i in 1:N) {
    for (j in 1:N) {
      real diff = (x[i] - x[j]) / rho;
      Sigma[i, j] = alpha^2 * exp(-0.5 * diff * diff);
    }
  }

  // GP prior: f ~ MVN(0, Sigma)
  f ~ multi_normal(rep_vector(0, N), Sigma);

  // Likelihood: k ~ Poisson(exp(f))
  for (i in 1:N) {
    k[i] ~ poisson(exp(f[i]));
  }
}

data {
  int<lower=1> N;
  array[N] real x;
  array[N] int k;
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  vector[N] f;
}

model {
  // Priors
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2);

  // Build squared exponential covariance matrix
  matrix[N, N] K;
  for (i in 1:N) {
    for (j in i:N) {
      real sq_dist = square(x[i] - x[j]);
      K[i, j] = square(alpha) * exp(-0.5 * sq_dist / square(rho));
      K[j, i] = K[i, j];
    }
  }
  // Add jitter for numerical stability
  for (i in 1:N) {
    K[i, i] = K[i, i] + 1e-9;
  }

  // GP prior
  f ~ multi_normal(rep_vector(0.0, N), K);

  // Likelihood
  for (i in 1:N) {
    k[i] ~ poisson_log(f[i]);
  }
}

data {
  int<lower=1> N;
  array[N] real x;
  vector[N] y;
}
parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  real<lower=0> sigma;
}
model {
  // Priors
  target += gamma_lpdf(rho | 25, 4);
  target += normal_lpdf(alpha | 0, 2);
  target += normal_lpdf(sigma | 0, 1);

  // Covariance matrix using squared exponential kernel
  matrix[N, N] K;
  for (i in 1:N) {
    K[i, i] = square(alpha);
    for (j in (i + 1):N) {
      real d = (x[i] - x[j]) / rho;
      real k_ij = square(alpha) * exp(-0.5 * square(d));
      K[i, j] = k_ij;
      K[j, i] = k_ij;
    }
  }

  // Add noise term (sigma on the diagonal, not sigma^2)
  matrix[N, N] Sigma = K + sigma * diag_matrix(rep_vector(1.0, N));

  // Cholesky factor
  matrix[N, N] L = cholesky_decompose(Sigma);

  // Likelihood
  y ~ multi_normal_cholesky(rep_vector(0.0, N), L);
}

data {
  int<lower=1> N;
  array[N] real x;
  vector[N] y;
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  real<lower=0> sigma;
}

model {
  matrix[N, N] K;
  matrix[N, N] cov;

  // Priors
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2);
  sigma ~ normal(0, 1);

  // Squared exponential covariance matrix
  for (i in 1:N) {
    for (j in 1:N) {
      K[i, j] = alpha^2 * exp(-0.5 * square((x[i] - x[j]) / rho));
    }
  }

  // Add noise variance (as sigma, not sigma^2)
  cov = K + sigma * diag_matrix(rep_vector(1, N));

  // Likelihood
  target += multi_normal_cholesky_lpdf(y | rep_vector(0, N), cholesky_decompose(cov));
}

data {
  int<lower=1> N;
  array[N] real x;
  vector[N] y;
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  real<lower=0> sigma;
}

model {
  // Priors
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2);
  sigma ~ normal(0, 1);

  // Squared exponential (RBF) kernel covariance matrix
  matrix[N, N] K;
  for (i in 1:N) {
    for (j in 1:N) {
      K[i, j] = alpha * alpha * exp(-0.5 * (x[i] - x[j])^2 / (rho * rho));
    }
  }

  // Add noise to diagonal
  for (i in 1:N) {
    K[i, i] += sigma;
  }

  // Likelihood: y ~ MVN(0, K + sigma*I)
  y ~ multi_normal(rep_vector(0.0, N), K);
}

data {
  int<lower=1> N;
  array[N] real x;
  vector[N] y;
}

parameters {
  real<lower=0> rho;
  real<lower=0> alpha;
  real<lower=0> sigma;
}

model {
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2);
  sigma ~ normal(0, 1);

  {
    matrix[N, N] K;
    for (i in 1:N) {
      K[i, i] = alpha * alpha;
      for (j in 1:(i-1)) {
        K[i, j] = alpha * alpha * exp(-((x[i] - x[j]) * (x[i] - x[j])) / (2 * rho * rho));
        K[j, i] = K[i, j];
      }
    }
    y ~ multi_normal_cholesky(rep_vector(0, N), cholesky_decompose(K + diag_matrix(rep_vector(sigma, N))));
  }
}

