  matrix[N, N] K;
  matrix[N, N] Sigma;

  // Exp squared exponential kernel K[i, j] = alpha * exp(-0.5 * (x[i] - x[j])^2 / rho^2)
  for (i in 1:N) {
    for (j in 1:N) {
      K[i, j] = alpha * exp(-0.5 * (x[i] - x[j])^2 / rho^2);
    }
  }

  // Covariance Sigma = K + sigma * I (noise on each observation is sigma)
  for (i in 1:N) {
    for (j in 1:N) {
      Sigma[i, j] = K[i, j] + (i == j ? sigma : 0);
    }
  }
}

