  // Priors
  rho ~ gamma(25, 4);
  alpha ~ normal(0, 2);
  sigma ~ normal(0, 1);

  // Build covariance matrix: K + sigma * I
  matrix[N, N] K;
  for (i in 1:N) {
    for (j in i:N) {
      real sq_dist = square(x[i] - x[j]) / (2.0 * square(rho));
      K[i, j] = square(alpha) * exp(-sq_dist);
      K[j, i] = K[i, j];
    }
  }
  // Add sigma (not sigma^2) to diagonal
  for (i in 1:N) {
    K[i, i] = K[i, i] + sigma;
  }

  // Likelihood
  y ~ multi_normal(rep_vector(0.0, N), K);
}

data {
