model {
  // Priors
  mu[1] ~ normal(3, 1);
  mu[2] ~ normal(10, 1);
  // theta1 and theta2 have flat priors (implicit via simplex)

  // Forward algorithm for HMM likelihood
  vector[K] log_alpha = rep_vector(0, K);

  // Initial state at t=1: uniform distribution
  for (k in 1:K) {
    log_alpha[k] = log(1.0 / K) + normal_lpdf(y[1] | mu[k], 1);
  }

  // Recursion for t=2 to N
  for (t in 2:N) {
    vector[K] log_alpha_next = rep_vector(negative_infinity(), K);

    for (k in 1:K) {
      // Transition probabilities TO state k from any previous state j
      for (j in 1:K) {
        real log_trans;
        if (j == 1) {
          log_trans = log(theta1[k]);
        } else {
          log_trans = log(theta2[k]);
        }
        log_alpha_next[k] = log_sum_exp(log_alpha_next[k], log_alpha[j] + log_trans);
      }
      // Emission probability at time t in state k
      log_alpha_next[k] += normal_lpdf(y[t] | mu[k], 1);
    }

    log_alpha = log_alpha_next;
  }

  // Marginalize over final states
  target += log_sum_exp(log_alpha);
}

data {
  int<lower=0> N;
  int<lower=0> K;
  array[N] real y;
}

parameters {
  simplex[K] theta1; // transition probabilities from state 1
  simplex[K] theta2; // transition probabilities from state 2
  real mu1; // observation mean for state 1
  real<lower=mu1> mu2; // observation mean for state 2, constrained to be >= mu1
}

transformed parameters {
  real mu[2];
  mu[1] = mu1;
  mu[2] = mu2;
}

model {
  // prior for theta1 and theta2: uniform over the simplex
  target += 0;

  // priors for mu1 and mu2: Normal(3, 1) and Normal(10, 1), respectively
  target += normal_lpdf(mu1 | 3, 1);
  target += normal_lpdf(mu2 | 10, 1);

  // initialize the hidden state at time 1
  real gamma[K]; // probability of being in each state at time 1
  for (k in 1:K) {
    gamma[k] = 1.0 / K; // uniform prior over the states
  }

  // iterate over the observations
  for (n in 1:N) {
    real probabilities[K]; // probability of each observation given the state
    for (k in 1:K) {
      probabilities[k] = normal_lpdf(y[n] | mu[k], 1);
    }

    // calculate the forward probabilities
    real new_gamma[K];
    for (j in 1:K) {
      real sum = 0;
      for (k in 1:K) {
        if (k == 1) {
          sum += gamma[k] * theta1[j] * exp(probabilities[j]);
        } else {
          sum += gamma[k] * theta2[j] * exp(probabilities[j]);
        }
      }
      new_gamma[j] = sum;
    }

    // normalize the probabilities
    real sum = 0;
    for (k in 1:K) {
      sum += new_gamma[k];
    }
    for (k in 1:K) {
      new_gamma[k] /= sum;
    }

    // update the probabilities for the next iteration
    gamma = new_gamma;
  }

  // add the log probability of the final state
  target += log_sum_exp(log(gamma));
}

data {
  int<lower=0> N;
  int<lower=0> K;
  array[N] real y;
