  // priors
  mu[1] ~ normal(3, 1);
  mu[2] ~ normal(10, 1);
  // theta1, theta2 have flat priors over the simplex

  {
    array[2] vector[2] theta;
    array[2] real acc;
    array[N] vector[2] gamma;

    theta[1] = theta1;
    theta[2] = theta2;

    // forward algorithm (marginalize over hidden states)
    for (k in 1:2)
      gamma[1, k] = log(0.5) + normal_lpdf(y[1] | mu[k], 1);

    for (t in 2:N) {
      for (k in 1:2) {
        for (j in 1:2)
          acc[j] = gamma[t - 1, j] + log(theta[j, k])
                   + normal_lpdf(y[t] | mu[k], 1);
        gamma[t, k] = log_sum_exp(acc);
      }
    }
    target += log_sum_exp(gamma[N]);
  }
}

data {
  int<lower=0> N;
  int<lower=0> K;
  array[N] real y;
}
parameters {
  simplex[2] theta1;
  simplex[2] theta2;
  ordered[2] mu;
}
model {
  // Priors
  mu[1] ~ normal(3, 1);
  mu[2] ~ normal(10, 1);

  // Hidden Markov Model with marginalized states
  // Forward algorithm for HMM
  array[N] simplex[2] alpha; // forward probabilities

  // Initialize at t=1
  alpha[1, 1] = 0.5 * normal_lpdf(y[1] | mu[1], 1);
  alpha[1, 2] = 0.5 * normal_lpdf(y[1] | mu[2], 1);
  alpha[1] = alpha[1] / sum(alpha[1]); // normalize

  // Forward pass
  for (t in 2:N) {
    real acc[2];
    for (k in 1:2) {
      acc[1] = alpha[t-1, 1] * theta1[k];
      acc[2] = alpha[t-1, 2] * theta2[k];
      alpha[t, k] = sum(acc) * normal_lpdf(y[t] | mu[k], 1);
    }
    alpha[t] = alpha[t] / sum(alpha[t]); // normalize
  }

  // Likelihood contribution
  target += log(sum(alpha[N]));
}

data {
  int<lower=0> N;
  int<lower=0> K;
  array[N] real y;
}

parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] mu;
}

model {
  // Priors on mu: Normal(3, 1) for mu[1] and Normal(10, 1) for mu[2]
  target += normal_lpdf(mu[1] | 3, 1);
  target += normal_lpdf(mu[2] | 10, 1);

  // HMM forward algorithm to compute marginal likelihood of observations
  // Integrates out the hidden state sequence

  if (N > 0) {
    // log_alpha[t, k]: log P(y[1:t], state[t] = k | parameters)
    array[N] vector[K] log_alpha;

    // Initialize at t=1: uniform prior over states (1/K each)
    for (k in 1:K) {
      log_alpha[1][k] = log(1.0 / K) + normal_lpdf(y[1] | mu[k], 1);
    }

    // Forward recursion over t = 2 to N
    for (t in 2:N) {
      for (k in 1:K) {
        real log_sum = -infinity;
        for (j in 1:K) {
          // Transition probability from state j to state k:
          // theta1[k] if j = 1, theta2[k] if j = 2
          if (K == 1) {
            log_sum += log_alpha[t-1][j] + log(sum(theta1));
          } else if (K == 2) {
            if (j == 1) {
              log_sum += log_alpha[t-1][j] + log(theta1[k]);
            } else {
              log_sum += log_alpha[t-1][j] + log(theta2[k]);
            }
          }
          // For K > 2, use component-wise vector indexing based on j
          else {
            real p_trans;
            if (j == 1) {
              p_trans = theta1[k];
            } else if (j == 2) {
              p_trans = theta2[k];
            } else {
              p_trans = 0.0;
            }
            if (p_trans > 0) {
              log_sum += log_alpha[t-1][j] + log(p_trans);
            }
          }
        }
        log_alpha[t][k] = log_sum + normal_lpdf(y[t] | mu[k], 1);
      }
    }

    // Log marginal likelihood = sum over final states of log P(y[1:N], state[N]=k)
    real log_marginal = log_sum_exp(log_alpha[N]);
    target += log_marginal;
  }
}

data {
  int<lower=0> N;
  int<lower=0> K;
  array[N] real y;
}

parameters {
  simplex[2] theta1;
  simplex[2] theta2;
  ordered[2] mu;
}

model {
  // Priors on emission means (ordered enforces mu[1] <= mu[2])
  mu[1] ~ normal(3, 1);
  mu[2] ~ normal(10, 1);

  // Soft positivity constraint on mu[1] (mu[2] > mu[1] follows from ordered)
  if (mu[1] <= 0) {
    target += negative_infinity();
  }

  // theta1 and theta2 have flat (improper uniform) priors via simplex declaration

  // Forward algorithm to marginalize over hidden states
  // log_alpha[k] = log P(y[1..t], state_t = k)
  array[2] real log_alpha;
  array[2] real log_alpha_new;
  array[2] real log_theta_col;

  // Initialize at t = 1 with uniform initial state distribution
  for (k in 1:2) {
    log_alpha[k] = log(0.5) + normal_lpdf(y[1] | mu[k], 1);
  }

  // Recurse for t = 2, ..., N
  for (t in 2:N) {
    for (k in 1:2) {
      // Collect log(theta[j][k]) for j = 1, 2
      // Row 1 = theta1, Row 2 = theta2
      log_theta_col[1] = log(theta1[k]);
      log_theta_col[2] = log(theta2[k]);

      // log sum_j [ alpha[t-1, j] * theta[j][k] ]
      log_alpha_new[k] = log_sum_exp(log_alpha[1] + log_theta_col[1],
                                     log_alpha[2] + log_theta_col[2])
                         + normal_lpdf(y[t] | mu[k], 1);
    }
    log_alpha = log_alpha_new;
  }

  // Add marginal log-likelihood: sum over terminal states
  target += log_sum_exp(log_alpha[1], log_alpha[2]);
}

functions {
  real[] lotka_volterra(real t,
                        real[] y,
                        real[] theta,
                        real[] x_r,
                        int[] x_i) {
    real dydt[2];
    real u = y[1];
    real v = y[2];
    real theta1 = theta[1];
    real theta2 = theta[2];
    real theta3 = theta[3];
    real theta4 = theta[4];
    dydt[1] = (theta1 - theta2 * v) * u;
    dydt[2] = (-theta3 + theta4 * u) * v;
    return dydt;
  }
}
