  target += lognormal_lpdf(z_init[1] | log(10), 1);
  target += lognormal_lpdf(z_init[2] | log(10), 1);

  target += lognormal_lpdf(sigma[1] | -1, 1);
  target += lognormal_lpdf(sigma[2] | -1, 1);

  // Observation model for initial measurements
  target += lognormal_lpdf(y_init[1] | log(z_init[1]), sigma[1]);
  target += lognormal_lpdf(y_init[2] | log(z_init[2]), sigma[2]);

  // ODE integration and likelihood for subsequent observations
  array[0] real x_r;
  int[0] x_i;
  array[2] real y0 = {z_init[1], z_init[2]};

  for (n in 1:N) {
