                                 theta, x_r, x_i, 1e-6, 1e-6);
    target += lognormal_lpdf(y[n, 1] | log(u_v[1]), sigma[1]);
    target += lognormal_lpdf(y[n, 2] | log(u_v[2]), sigma[2]);
