}

transformed data {
  real x_r[2] = {0, 0}; // dummy initial conditions
}

parameters {
  real<lower=0> theta[4]; // system parameters
  real<lower=0> z_init[2]; // initial populations
  real<lower=0> sigma[2]; // measurement error standard deviations
}

transformed parameters {
  // Lotka-Volterra system
  real du_dt[2];
  du_dt[1] = (theta[1] - theta[2]*z_init[2])*z_init[1];
  du_dt[2] = (-theta[3] + theta[4]*z_init[1])*z_init[2];
}

model {
  theta[1] ~ normal(1, 0.5); // prior for theta[1]
  theta[2] ~ normal(0.05, 0.05); // prior for theta[2]
  theta[3] ~ normal(1, 0.5); // prior for theta[3]
  theta[4] ~ normal(0.05, 0.05); // prior for theta[4]
  z_init[1] ~ lognormal(log(10), 1); // prior for z_init[1]
  z_init[2] ~ lognormal(log(10), 1); // prior for z_init[2]
  sigma[1] ~ lognormal(-1, 1); // prior for sigma[1]
  sigma[2] ~ lognormal(-1, 1); // prior for sigma[2]

  // initial populations model
  y_init[1] ~ lognormal(log(z_init[1]), sigma[1]);
  y_init[2] ~ lognormal(log(z_init[2]), sigma[2]);

  // integrate ODE for each measurement time
  real z[N, 2];
  z[1, 1] = z_init[1];
  z[1, 2] = z_init[2];

  for (n in 1:N) {
    real z_new[2];

    // Lotka-Volterra system with numerical integration (using a simple Euler method here, for simplicity)
    z_new[1] = z[n, 1] + (theta[1] - theta[2]*z[n, 2])*z[n, 1]*(ts[n]-ts[n-1]);
    z_new[2] = z[n, 2] + (-theta[3] + theta[4]*z[n, 1])*z[n, 2]*(ts[n]-ts[n-1]);

