transformed parameters {
  // extract scalar eigenvalues (assume first dimension is relevant)
  vector[NBgp_1] lambda_1;
  for (j in 1:NBgp_1)
    lambda_1[j] = slambda_1[j][1];

  vector[NBgp_sigma_1] lambda_sigma_1;
  for (j in 1:NBgp_sigma_1)
    lambda_sigma_1[j] = slambda_sigma_1[j][1];

  // scaling for each basis according to marginal sd and length‑scale
  vector[NBgp_1] scale_1 = sdgp_1 * exp(-0.5 * lscale_1 * lambda_1);
  vector[NBgp_sigma_1] scale_sigma_1 = sdgp_sigma_1 * exp(-0.5 * lscale_sigma_1 * lambda_sigma_1);

  // latent smooth functions
  vector[N] f_mean = Intercept + Xgp_1 * (zgp_1 .* scale_1);
  vector[N] log_sigma = Intercept_sigma + Xgp_sigma_1 * (zgp_sigma_1 .* scale_sigma_1);
  vector[N] sigma = exp(log_sigma);
}

