  lscale_sigma_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_sigma_1 ~ normal(0, 1);

  // Likelihood
  if (!prior_only) {
    vector[N] mu;
    vector[N] sigma;

    // Compute mean function
    for (n in 1:N) {
      mu[n] = Intercept;
      for (k in 1:NBgp_1) {
        mu[n] += Xgp_1[n, k] * sdgp_1 * sqrt(slambda_1[k, 1]) * 
                 exp(-0.5 * lscale_1 * slambda_1[k, 1]) * zgp_1[k];
      }
    }

    // Compute log-variance function and transform to standard deviation
    for (n in 1:N) {
      real log_sigma_raw = Intercept_sigma;
      for (k in 1:NBgp_sigma_1) {
        log_sigma_raw += Xgp_sigma_1[n, k] * sdgp_sigma_1 * sqrt(slambda_sigma_1[k, 1]) * 
                         exp(-0.5 * lscale_sigma_1 * slambda_sigma_1[k, 1]) * zgp_sigma_1[k];
      }
      sigma[n] = exp(log_sigma_raw);
    }

    // Likelihood
    Y ~ normal(mu, sigma);
  }
}

