functions {
  /* Spectral density of the squared exponential (exp. quadratic) kernel
   * evaluated at the (square roots of the) Laplacian eigenvalues.
   *   x: array of eigenvalue vectors (sqrt lambda)
   *   sdgp: marginal SD of the GP
   *   lscale: length-scale (isotropic)
   */
  vector spd_cov_exp_quad(data array[] vector x, real sdgp, real lscale) {
    int NB = size(x);
    int D = size(x[1]);
    vector[NB] out;
    real constant = square(sdgp) * (sqrt(2 * pi()) * lscale) ^ D;
    real neg_half_lscale2 = -0.5 * square(lscale);
    for (m in 1 : NB) {
      out[m] = constant * exp(neg_half_lscale2 * dot_self(x[m]));
    }
    return out;
  }
  /* Approximate latent Gaussian process */
  vector gpa(data array[] vector x, real sdgp, real lscale, vector zgp,
             data matrix Xgp) {
    return Xgp * (sqrt(spd_cov_exp_quad(x, sdgp, lscale)) .* zgp);
  }
}
