  if (!prior_only) {
    vector[N] mu = rep_vector(0.0, N);
    vector[N] sigma = rep_vector(0.0, N);
    mu += Intercept + gpa(slambda_1, sdgp_1, lscale_1, zgp_1, Xgp_1);
    sigma += Intercept_sigma
             + gpa(slambda_sigma_1, sdgp_sigma_1, lscale_sigma_1,
