  int<lower=1> Dgp_1; // GP dimension
  // number of basis functions of an approximate GP
  int<lower=1> NBgp_1;
  // approximate GP basis matrices
  matrix[N, NBgp_1] Xgp_1;
  // approximate GP eigenvalues
  array[NBgp_1] vector[Dgp_1] slambda_1;
  // data related to GPs
  // number of sub-GPs (equal to 1 unless 'by' was used)
  int<lower=1> Kgp_sigma_1;
  int<lower=1> Dgp_sigma_1; // GP dimension
  // number of basis functions of an approximate GP
  int<lower=1> NBgp_sigma_1;
  // approximate GP basis matrices
  matrix[N, NBgp_sigma_1] Xgp_sigma_1;
  // approximate GP eigenvalues
  array[NBgp_sigma_1] vector[Dgp_sigma_1] slambda_sigma_1;
  int prior_only; // should the likelihood be ignored?
}

parameters {
  real Intercept;
  real<lower=0> sdgp_1;
  real<lower=0> lscale_1;
  vector[40] zgp_1;
  real Intercept_sigma;
  real<lower=0> sdgp_sigma_1;
  real<lower=0> lscale_sigma_1;
  vector[20] zgp_sigma_1;
}

transformed parameters {
  vector[N] mu;
  vector[N] log_sigma;
  vector[N] sigma;

  // Mean GP contribution using spectral basis functions
  mu = Intercept + Xgp_1 * zgp_1;

  // Log-variance GP contribution using spectral basis functions
  log_sigma = Intercept_sigma + Xgp_sigma_1 * zgp_sigma_1;

  // Standard deviation from log-variance GP
  sigma = exp(log_sigma);
}

model {
  // Priors for mean GP
  Intercept ~ student_t(3, -13, 36);
  sdgp_1 ~ student_t(3, 0, 36);
  lscale_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_1 ~ normal(0, 1);

  // Priors for log-variance GP
  Intercept_sigma ~ student_t(3, 0, 10);
  sdgp_sigma_1 ~ student_t(3, 0, 36);
  lscale_sigma_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_sigma_1 ~ normal(0, 1);

  // Likelihood
  if (prior_only == 0) {
    Y ~ normal(mu, sigma);
  }
}

functions {
  vector diagSPD_cov_exp_quad(real sdgp, real lscale,
                               array[] vector slambda,
                               int Dgp, int NBgp) {
    vector[NBgp] out;
    real constant = square(sdgp) * pow(sqrt(2.0 * pi()) * lscale, Dgp);
    for (m in 1:NBgp) {
      out[m] = sqrt(constant * exp(-0.5 * square(lscale) * dot_self(slambda[m])));
    }
    return out;
  }
}

