  {
    vector[NBgp_1] diagSPD_1 = diagSPD_cov_exp_quad(sdgp_1, lscale_1, slambda_1, Dgp_1, NBgp_1);
    vector[NBgp_sigma_1] diagSPD_sigma_1 = diagSPD_cov_exp_quad(sdgp_sigma_1, lscale_sigma_1, slambda_sigma_1, Dgp_sigma_1, NBgp_sigma_1);
    mu = Intercept + Xgp_1 * (diagSPD_1 .* zgp_1);
    sigma = exp(Intercept_sigma + Xgp_sigma_1 * (diagSPD_sigma_1 .* zgp_sigma_1));
  }
}

