  vector[N] logit_p;

  for (i in 1:N) {
    logit_p[i] = alpha + beta[1] * income[i];
  }

  // Bernoulli likelihood for each observation
  // equivalent to: vote[i] ~ bernoulli(inv_logit(logit_p[i]))
  target += sum(normalogit(logit_p * vote));

  // Or equivalently using bernoulli_lpmf
  // for (i in 1:N) {
  //   target += bernoulli_lpmf(vote[i] | logit_p[i]);
  // }
}

data {
  int<lower=0> N;
  vector[N] income;
  array[N] int<lower=0, upper=1> vote;
}

parameters {
  real alpha;
  vector[1] beta;
}

model {
  vote ~ bernoulli_logit(alpha + beta[1] * income);
}

functions {
  vector ode_pk(real t,
                vector y,
                real[] theta,
                real[] x_r,
                int[] x_i) {
    // theta[1] = k_a, theta[2] = K_m, theta[3] = V_m
    // x_r[1] = D,    x_r[2] = V
    real k_a = theta[1];
    real K_m = theta[2];
    real V_m = theta[3];
    real D   = x_r[1];
    real V   = x_r[2];
    real C   = y[1];

    real dC_dt = (k_a * D / V) * exp(-k_a * t)
                 - (V_m / V) * C / (K_m + C);

    vector[1] dy;
    dy[1] = dC_dt;
    return dy;
  }
}
