  real D; // Total dosage in mg
  real V; // Compartment volume in L

  int<lower=1> N_t;
  array[N_t] real times; // Measurement times in days

  // Measured concentrations in effect compartment in mg/L
  array[N_t] real C_hat;
}
parameters {
  real<lower=0> k_a;   // absorption rate constant
  real<lower=0> K_m;   // Michaelis-Menten half-saturation constant
  real<lower=0> V_m;   // maximum elimination rate
  real<lower=0> sigma; // measurement error standard deviation (log‐scale)
}
transformed parameters {
  array[N_t] real C_pred;          // model predicted concentrations
  vector[1] y0 = rep_vector(0.0, 1); // initial concentration (zero)
  real theta[3];
  real x_r[2];
  int x_i[0];

  theta[1] = k_a;
  theta[2] = K_m;
  theta[3] = V_m;
  x_r[1] = D;
  x_r[2] = V;

  // Solve ODE at the measurement times
  array[N_t] vector[1] y_hat = integrate_ode_rk45(
    ode_pk, y0, t0, times, theta, x_r, x_i
  );

  for (i in 1:N_t) {
    C_pred[i] = y_hat[i][1];
  }
}
model {
  // Half‑Cauchy(0,1) priors
  target += cauchy_lpdf(k_a | 0, 1) + log(2);
  target += cauchy_lpdf(K_m | 0, 1) + log(2);
  target += cauchy_lpdf(V_m | 0, 1) + log(2);
  target += cauchy_lpdf(sigma | 0, 1) + log(2);

  // Likelihood: lognormal observation model
  for (i in 1:N_t) {
    // avoid taking log of non‑positive predictions
    target += lognormal_lpdf(C_hat[i] | log(C_pred[i]), sigma);
  }
}

functions {
  real[] pk_ode(real t, real[] y, real[] theta, real[] x_r, int[] x_i) {
    // State
    real C = y[1];
    // Parameters
    real k_a = theta[1];
    real K_m = theta[2];
    real V_m = theta[3];
    // Constants
    real D = x_r[1];
    real V = x_r[2];
    // Absorption term
    real absorption = k_a * D * exp(-k_a * t) / V;
    // Saturable elimination term
    real elimination = (V_m / V) * C / (K_m + C);
    return [absorption - elimination];
  }
}

data {
  real t0;                 // Initial time (usually 0)
  real D;                  // Total dose (mg)
  real V;                  // Compartment volume (L)
  int<lower=1> N_t;        // Number of measurement times
  array[N_t] real times;   // Measurement times (days)
  array[N_t] real C_hat;   // Measured concentrations (mg/L)
}

parameters {
  real<lower=0> k_a;   // Absorption rate constant (1/day)
  real<lower=0> K_m;   // Michaelis–Menten half–saturation (mg/L)
  real<lower=0> V_m;   // Maximum elimination rate (1/day)
  real<lower=0> sigma; // Lognormal measurement error (mg/L)
}

transformed parameters {
  vector[N_t] C_pred;  // ODE‑predicted concentrations at measurement times

  // Initial concentration vector
  vector[1] y0;
  y0[1] = 0.0;

  // Build a full time grid that includes the initial time
  array[N_t+1] real all_times = rep_array(0.0, N_t+1);
  all_times[1] = t0;
  for (i in 1:N_t) {
    all_times[i+1] = times[i];
  }

  // Assemble parameter and constant vectors for the ODE solver
  real[] theta = {k_a, K_m, V_m};
  real[] x_r   = {D, V};

  // Solve the ODE at all time points
  real[][] y_sol = integrate_ode_rk45(pk_ode, y0, t0, all_times, theta, x_r);

  // Extract predictions at the measurement times (skip the initial row)
  C_pred = to_vector(y_sol[2:N_t+1, 1]);
}

model {
  // Half-Cauchy priors for all positive parameters
  k_a ~ cauchy(0, 1);
  K_m ~ cauchy(0, 1);
  V_m ~ cauchy(0, 1);
  sigma ~ cauchy(0, 1);

  // Likelihood: lognormal with log-mean equal to log(predicted concentration)
  for (n in 1:N_t) {
    C_hat[n] ~ lognormal(log(C_pred[n]), sigma);
  }
}

functions {
  vector concentration_derivatives(real t, vector y, real k_a, real D, real V, 
                                   real K_m, real V_m) {
    vector[1] dydt;
    real C = y[1];
    // dC/dt = k_a * (D/V) * exp(-k_a * t) - (V_m / V) * C / (K_m + C)
    dydt[1] = k_a * (D / V) * exp(-k_a * t) - (V_m / V) * C / (K_m + C);
    return dydt;
  }
}

