model {
  // Priors (half-Cauchy)
  k_a ~ cauchy(0, 1);
  K_m ~ cauchy(0, 1);
  V_m ~ cauchy(0, 1);
  sigma ~ cauchy(0, 1);

  // Initial condition: C(t0) = 0
  vector[1] C0 = [0];

  // Solve ODE
  array[N_t] vector[1] C_sol = integrate_ode_rk45(concentration_derivatives, C0, t0, times, k_a, D, V, K_m, V_m);

  // Extract predictions
  vector[N_t] C_pred;
  for (i in 1:N_t) {
    C_pred[i] = C_sol[i, 1];
  }

  // Likelihood - lognormal distribution
  // log(C_hat) ~ Normal(log(C_pred), sigma)
  C_hat ~ lognormal(log(C_pred), sigma);
}

