  real<lower=0> K_m;
  real<lower=0> V_m;
  real<lower=0> sigma;
}

model {
  k_a ~ cauchy(0, 1);
  K_m ~ cauchy(0, 1);
  V_m ~ cauchy(0, 1);
  sigma ~ cauchy(0, 1);

  real C[N_t];
  C[1] = 0;

  for (t in 2:N_t) {
    real dC_dt;
    dC_dt = (k_a * D / V) * exp(-k_a * times[t]) - (V_m / V) * (C[t-1] / (K_m + C[t-1]));
    C[t] = C[t-1] + dC_dt * (times[t] - times[t-1]);
  }

  for (n in 1:N_t) {
    C_hat[n] ~ lognormal(log(C[n]), sigma);
  }
}

