  real<lower=0> K_m;
  real<lower=0> V_m;
  real<lower=0> sigma;
}

model {
  // Half-Cauchy(0, 1) priors via parameter bounds and Cauchy distribution
  k_a ~ cauchy(0, 1);
  K_m ~ cauchy(0, 1);
  V_m ~ cauchy(0, 1);
  sigma ~ cauchy(0, 1);

  // Solve ODE from t0 to each measurement time with initial condition y(t0) = 0
  array[N_t] real C_pred;

  for (i in 1:N_t) {
    C_pred[i] = integrate_ode_rk45(
      odefun,
      t0,
      times[i],
      0,
      {k_a, K_m, V_m},
      {D, V},
      1e-5
    );
  }

  // Lognormal likelihood with log-mean = log(predicted concentration)
  for (i in 1:N_t) {
    if (C_pred[i] > 0) {
      C_hat[i] ~ lognormal(log(C_pred[i]), sigma);
    }
  }
}

