  vector pk_ode(real t, vector y, real k_a, real K_m, real V_m,
                real D, real V, real t0) {
    vector[1] dydt;
    real C = y[1];
    // Absorption: first-order input from gut; Elimination: Michaelis-Menten
    dydt[1] = k_a * (D / V) * exp(-k_a * (t - t0))
              - (V_m / V) * C / (K_m + C);
