// Truth function
var truth = function(o, u) {
  if (u === "blue" || u === "green") {
    return o.color === u;
  } else if (u === "square" || u === "circle") {
    return o.shape === u;
  } else {
    return true; // vacuous truth for any other utterance
  }
};

// Literal listener L0(o | u)  (uniform prior + truth)
var L0 = function(o, u) {
  var denom = objects.reduce(function(s, obj) {
    return s + (truth(obj, u) ? 1 : 0);
  }, 0);
  return truth(o, u) ? 1 / denom : 0;
};

// Speaker S1(u | o, alpha)  proportional to L0(o|u)^alpha
var S1 = function(u, o, alpha) {
  var num = Math.pow(L0(o, u), alpha);
  var denom = utterances.reduce(function(s, ut) {
    return s + Math.pow(L0(o, ut), alpha);
  }, 0);
  return num / denom;
};

// Pragmatic listener that conditions on hearing a given utterance
var pragmaticListener = function(alpha, utterance) {
  return function() {
    var o = uniformDraw(objects);               // uniform prior over objects
    factor(Math.log(S1(utterance, o, alpha))); // weight by speaker's production prob.
    return o;
  };
};

