// WebPPL program computing pragmatic listener posteriors for different alphas
var objects = [
  {shape: 'square', color: 'blue'},
  {shape: 'circle', color: 'blue'},
  {shape: 'square', color: 'green'}
];

var utterances = ['blue', 'green', 'square', 'circle'];

// truth function
function truth(utt, obj) {
  if (utt === 'blue' || utt === 'green')
    return obj.color === utt;
  if (utt === 'square' || utt === 'circle')
    return obj.shape === utt;
  return true; // vacuously true for unexpected utterances
}

// Precomputed denominators for literal listener
var denom = {'blue': 2, 'green': 1, 'square': 2, 'circle': 1};

function literalProb(obj, utt) {
  var t = truth(utt, obj);
  return t ? 1 / denom[utt] : 0;
}

// Speaker probability of utterance 'blue' given an object and alpha
function speakerProbBlue(obj, alpha) {
  var total = 0;
  var wBlue = 0;
  for (var i = 0; i < utterances.length; i++) {
    var utt = utterances[i];
    var L = literalProb(obj, utt);      // P(object | utt) from literal listener
    var w = Math.pow(L, alpha);         // exp(alpha * log L) = L^alpha
    if (utt === 'blue') wBlue = w;
    total += w;
  }
  return total === 0 ? 0 : wBlue / total; // probability utterance 'blue'
}

// Pragmatic listener posterior given utterance 'blue' for a specific alpha
function pragmaticPosterior(alpha) {
  var objDist = Infer({method: 'enumerate'}, function () {
    // uniformly pick an object (prior 1/3)
    var idx = randomInteger([0, objects.length - 1]);
    var obj = objects[idx];

    // weight by speaker's probability of saying 'blue'
    var spProb = speakerProbBlue(obj, alpha);
    if (spProb === 0) factor(-Infinity);
    else factor(Math.log(spProb));

    return obj;
  });
  return objDist;
}

