// Intervention: do(Cough = true) — cough is forced externally,
// so the causal parents (LC, cold) are NOT updated; their distributions
// remain at the prior. This is the do-operator cutting the back-channel.
var intervention = Infer({method: 'enumerate'}, function() {
  var lc = flip(0.01);
  // Cough is forced to true, but this doesn't alter the distribution of lc
  // (the causal arrow from lc -> cough is severed by the intervention).
  return lc;
});

// Conditioning: observe(Cough = true) — Bayes' rule propagates information
// back through the causal graph to update beliefs about causes.
var conditioning = Infer({method: 'enumerate'}, function() {
  var lc   = flip(0.01);
  var cold = flip(0.2);

  // Each causal pathway fires independently
  var lc_pathway   = lc   ? flip(0.3) : false;
  var cold_pathway = cold ? flip(0.5) : false;

  // Cough occurs if at least one pathway fires
  var cough = lc_pathway || cold_pathway;

  // Observe that the person is coughing
  condition(cough === true);

  return lc;
});

