var model = function() {
  var N = flip(0.7); // niceness

  // Past 5 days: observed not smiling
  for (var d = 0; d < 5; d++) {
    var w = flip(N ? 0.2 : 0.5); // wanting this day
    var p_wc = w ? 0.8 : 0.5;     // wanting channel prob
    var p_nc = N ? 0.8 : 0.5;     // niceness channel prob

    var c_wc = flip(p_wc);
    var c_nc = flip(p_nc);
    var smile = c_wc || c_nc;
    condition(!smile); // not smiling observed
  }

  // Today: observed smiling
  var w_t = flip(N ? 0.2 : 0.5); // wanting today
  var p_wc_t = w_t ? 0.8 : 0.5;
  var p_nc_t = N ? 0.8 : 0.5;

  var c_wc_t = flip(p_wc_t);
  var c_nc_t = flip(p_nc_t);
  var smile_t = c_wc_t || c_nc_t;
  condition(smile_t); // smiling observed

  return w_t; // return whether today they want something
};

