var smile = function(nice, wants) {
  var wantChannel = wants ? 0.8 : 0.5;
  var niceChannel = nice ? 0.8 : 0.5;
  return (wantChannel > 0.5 ? true : (Math.random() < wantChannel)) || 
         (niceChannel > 0.5 ? true : (Math.random() < niceChannel));
};

