  var nice = flip(0.7);
  var wantsHistory = [];
  var smileHistory = [];
  for (var i = 0; i < 5; i++) {
    var wants = nice ? flip(0.2) : flip(0.5);
    wantsHistory.push(wants);
    smileHistory.push(smile(nice, wants));
    condition(!smileHistory[i]);
  }
  var wantsToday = nice ? flip(0.2) : flip(0.5);
  var smileToday = smile(nice, wantsToday);
  condition(smileToday);
  return wantsToday;
};

