var model = function() {
  var nice = flip(0.7);
  var smileProb = function(wants) {
    var pw = wants ? 0.8 : 0.5;
    var pn = nice ? 0.8 : 0.5;
    return 1 - (1 - pw) * (1 - pn);
  };
  var day = function(smiled) {
    var wants = flip(nice ? 0.2 : 0.5);
    observe(Bernoulli({p: smileProb(wants)}), smiled);
    return wants;
  };
  map(function(i) { return day(false); }, [1, 2, 3, 4, 5]);
  var wantsToday = day(true);
  return wantsToday;
};

