var sameStoreDist = Infer({method:'forward', N:10000}, function() {
  // Draw a store type: 0 = fresh, 1 = rotten
  var storeType = sample(new Categorical({ps:[0.5, 0.5]}));
  var alpha = (storeType === 0) ? 0.1 : 0.3;
  var beta  = (storeType === 0) ? 0.3 : 0.1;
  var betaDist = new Beta({alpha: alpha, beta: beta});

  function drawBarrel() {
    var p = sample(betaDist);
    var count = 0;
    for (var i = 0; i < 10; i++) {
      var rotten = sample(new Bernoulli({p: p}));
      if (rotten) count += 1;
    }
    return count;
  }

  var count1 = drawBarrel();
  var count2 = drawBarrel();
  return Math.abs(count1 - count2);
});

