function factorial(n) {
  var f = 1;
  for (var i = 2; i <= n; i++) { f *= i; }
  return f;
}

// Dirichlet‑Multinomial marginal (log) with α_i = 1 for all K=5 categories
function logDirichletMultMarginal(counts) {
  var K = counts.length;            // =5
  var N = counts.reduce(function(a,b){return a+b;}, 0);
  var logNum = Math.log(factorial(K-1)); // log Gamma(K) = log (K‑1)!
  var logDen = Math.log(factorial(N + K - 1)); // log Gamma(N+K)
  var sumLogFact = counts.reduce(function(s,c){ return s + Math.log(factorial(c)); }, 0);
  return logNum + sumLogFact - logDen;
}

