// Binomial log-probability helper (ignore combinatorial constant)
function logBinomProb(k, n, p) {
  if (p <= 0) return -Infinity; // impossible
  if (p >= 1) return -Infinity; // impossible
  return k * Math.log(p) + (n - k) * Math.log(1 - p);
}

// Computes posterior expectation of cp under the CP model
function cpExpected(numEWithC, numEWithoutC) {
  var sumW = 0;
  var sumCpW = 0;
  for (var ic = 0; ic < cpVals.length; ic++) {
