    for (var ib = 0; ib < bVals.length; ib++) {
      var b = bVals[ib];
      var a = cp + b - cp * b; // noisy-OR probability when C=true
      var logW = logBinomProb(numEWithC, 8, a) + logBinomProb(numEWithoutC, 8, b);
      if (logW == -Infinity) continue;
      var w = Math.exp(logW);
      sumW += w;
      sumCpW += cp * w;
    }
  }
  return sumCpW / sumW;
}

// Computes posterior expectation of relation * cp under the CS model
function csExpected(numEWithC, numEWithoutC) {
  var sumWRelation1 = 0;    // weight for relation = true
  var sumCpWRelation1 = 0;  // cp * weight for relation = true
  var sumWRelation0 = 0;    // weight for relation = false
  // Relation = true
  for (var ic = 0; ic < cpVals.length; ic++) {
    var cp = cpVals[ic];
    for (var ib = 0; ib < bVals.length; ib++) {
      var b = bVals[ib];
      var a = cp + b - cp * b;
      var logW = logBinomProb(numEWithC, 8, a) + logBinomProb(numEWithoutC, 8, b);
      if (logW == -Infinity) continue;
      var w = Math.exp(logW);
      sumWRelation1 += w;
      sumCpWRelation1 += cp * w;
    }
  }
  // Relation = false
  for (var ib = 0; ib < bVals.length; ib++) {
    var b = bVals[ib];
    var logW = logBinomProb(numEWithC, 8, b) + logBinomProb(numEWithoutC, 8, b);
    if (logW == -Infinity) continue;
    var w = Math.exp(logW);
    // cp irrelevant, integrate over cp uniformly
    // Sum over cp gives factor equal to number of cp grid points
    sumWRelation0 += w * cpVals.length;
  }
  var totalW = sumWRelation1 + sumWRelation0;
  var pRelTrue = sumWRelation1 / totalW;
  var cpExpRel1 = sumCpWRelation1 / sumWRelation1;
  return pRelTrue * cpExpRel1;
