    var numTrueWithC = numEWithC;
    var numFalseWithC = 8 - numTrueWithC;
    var pEGivenC = marginalEProb(cp, b, true);
    logLik += numTrueWithC * Math.log(pEGivenC) + numFalseWithC * Math.log(1 - pEGivenC);

    // Trials where C = false (8 trials)
    var numTrueWithoutC = numENotWithC;
    var numFalseWithoutC = 8 - numTrueWithoutC;
    var pEGivenNotC = marginalEProb(cp, b, false);
