function model() {
  var goal = uniformDraw([bagel, cookie, doughnut]);
  var isDeceptive = Bernoulli(0.5);

  var vendingMachine = {
    a: {bagel: 0.8, cookie: 0.1, doughnut: 0.1},
    b: {bagel: 0.1, cookie: 0.8, doughnut: 0.1},
    c: {bagel: 0.1, cookie: 0.1, doughnut: 0.8}
  };

  var selectedAction;
  if (isDeceptive === true) {
    // Deceptive: chooses action that mismatches goal (lowest probability)
    var weights = [
      vendingMachine[a][goal],
      vendingMachine[b][goal],
      vendingMachine[c][goal]
    ];
    var minWeight = Math.min(...weights);
    var candidates = [];
    if (weights[0] === minWeight) candidates.push(a);
    if (weights[1] === minWeight) candidates.push(b);
    if (weights[2] === minWeight) candidates.push(c);
    selectedAction = uniformDraw(candidates);
  } else {
    // Non-deceptive: chooses action that matches goal (highest probability)  
    var weights = [
      vendingMachine[a][goal],
      vendingMachine[b][goal],
      vendingMachine[c][goal]
    ];
    var maxWeight = Math.max(...weights);
    var candidates = [];
    if (weights[0] === maxWeight) candidates.push(a);
    if (weights[1] === maxWeight) candidates.push(b);
    if (weights[2] === maxWeight) candidates.push(c);
    selectedAction = uniformDraw(candidates);
  }

  var observation1 = selectedAction;
  var observation2 = selectedAction;

  condition(observation1 === b);
  condition(observation2 === b);

  return goal;
}

